11\\u01b0\\u1ee3c l\\u01b0u \\n\\u0111\\u00fang, th\\u1ed1ng k\\u00ea c\\u00f3 ch\\u00ednh x\\u00e1c v\\u00e0 c\\u00e1c thao t\\u00e1c nghi\\u1ec7p v\\u1ee5 c\\u00f3 ph\\u00f9 h\\u1ee3p v\\u1edbi quy\\u1ec1n \\n\\u0111\\u01b0\\u1ee3c c\\u1ea5p hay kh\\u00f4ng. \\n\\u0110\\u1ed1i v\\u1edbi Gi\\u1ea3ng vi\\u00ean, nh\\u1eefng ch\\u1ee9c n\\u0103ng li\\u00ean quan g\\u1ed3m \\u0111\\u1ec1 xu\\u1ea5t v\\u00e0 h\\u01b0\\u1edbng \\nd\\u1eabn \\u0111\\u1ec1 t\\u00e0i, xem b\\u00e1o c\\u00e1o, nh\\u1eadn x\\u00e9t ti\\u1ebfn \\u0111\\u1ed9, tham gia h\\u1ed9i \\u0111\\u1ed3ng v\\u00e0 \\u0111\\u1ecdc b\\u1ea3n t\\u00f3m t\\u1eaft \\nAI. Ch\\u1ee9c n\\u0103ng AI ch\\u1ec9 cung c\\u1ea5p n\\u1ed9i dung tham kh\\u1ea3o, kh\\u00f4ng t\\u1ef1 quy\\u1ebft \\u0111\\u1ecbnh m\\u1ee9c \\u0111\\u1ed9 \\nho\\u00e0n th\\u00e0nh c\\u1ee7a sinh vi\\u00ean. \\n\\u0110\\u1ed1i v\\u1edbi Sinh vi\\u00ean, h\\u1ec7 th\\u1ed1ng h\\u01b0\\u1edbng \\u0111\\u1ebfn h\\u1ed7 tr\\u1ee3 tra c\\u1ee9u \\u0111\\u1ec1 t\\u00e0i, \\u0111\\u0103ng k\\u00fd, n\\u1ed9p \\nb\\u00e1o c\\u00e1o, ti\\u1ebfp nh\\u1eadn nh\\u1eadn x\\u00e9t v\\u00e0 theo d\\u00f5i c\\u00e1c th\\u1ee7 t\\u1ee5c b\\u1ea3o v\\u1ec7. C\\u00e1c t\\u00ecnh hu\\u1ed1ng kh\\u00f4ng \\n 1\\n\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":133,\"snippet\":\" xu\\u1ea5t v\\u00e0 h\\u01b0\\u1edbng \\nd\\u1eabn \\u0111\\u1ec1 t\\u00e0i, xem b\\u00e1o c\\u00e1o, nh\\u1eadn x\\u00e9t ti\\u1ebfn \\u0111\\u1ed9, tham gia h\\u1ed9i \\u0111\\u1ed3ng v\\u00e0 \\u0111\\u1ecdc b\\u1ea3n t\\u00f3m t\\u1eaft \\nAI. Ch\\u1ee9c n\\u0103ng AI ch\\u1ec9 cung c\\u1ea5p n\\u1ed9i dung tham kh\\u1ea3o, kh\\u00f4ng t\\u1ef1 quy\\u1ebft \\u0111\\u1ecbnh m\\u1ee9c \\u0111\\u1ed9 \\nho\\u00e0n th\\u00e0nh c\\u1ee7a sinh vi\\u00ean. \\n\\u0110\\u1ed1i v\\u1edbi Sinh vi\\u00ean, h\\u1ec7 th\\u1ed1ng h\\u01b0\\u1edbng \\u0111\\u1ebfn h\\u1ed7 tr\\u1ee3 tra c\\u1ee9u \\u0111\\u1ec1 t\\u00e0i, \\u0111\\u0103ng k\\u00fd, n\\u1ed9p \\nb\\u00e1o c\\u00e1o, ti\\u1ebfp nh\\u1eadn nh\\u1eadn x\\u00e9t v\\u00e0 theo d\\u00f5i c\\u00e1c th\\u1ee7 t\\u1ee5c b\\u1ea3o v\\u1ec7. C\\u00e1c t\\u00ecnh hu\\u1ed1ng kh\\u00f4ng \\n 1\\n\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":134,\"snippet\":\"h\\u1ee3p l\\u1ec7 c\\u1ea7n c\\u00f3 th\\u00f4ng b\\u00e1o r\\u00f5 r\\u00e0ng \\u0111\\u1ec3 ng\\u01b0\\u1eddi d\\u00f9ng hi\\u1ec3u l\\u00fd do thao t\\u00e1c ch\\u01b0a th\\u1ec3 th\\u1ef1c \\nhi\\u1ec7n. \\n[C\\u1ea6N B\\u1ed4 SUNG: N\\u1ebfu c\\u00f3 kh\\u1ea3o s\\u00e1t ng\\u01b0\\u1eddi d\\u00f9ng, b\\u1ed5 sung s\\u1ed1 l\\u01b0\\u1ee3ng ng\\u01b0\\u1eddi tham gia, b\\u1ed9 c\\u00e2u h\\u1ecfi v\\u00e0 k\\u1ebft \\nqu\\u1ea3; n\\u1ebfu kh\\u00f4ng c\\u00f3, ch\\u1ec9 tr\\u00ecnh b\\u00e0y \\u0111\\u00e1nh gi\\u00e1 ch\\u1ee9c n\\u0103ng theo vai tr\\u00f2.] \\n6.7.3.  \\u0110\\u00e1nh gi\\u00e1 kh\\u1ea3 n\\u0103ng \\u00e1p d\\u1ee5ng th\\u1ef1c t\\u1ebf \\nKh\\u1ea3 n\\u0103ng \\u00e1p d\\u1ee5ng th\\u1ef1c t\\u1ebf c\\u1ee7a h\\u1ec7 th\\u1ed1ng ph\\u1ee5 thu\\u1ed9c v\\u00e0o m\\u1ee9c \\u0111\\u1ed9 ho\\u00e0n thi\\u1ec7n \\nnghi\\u1ec7p v\\u1ee5, t\\u00ednh ch\\u00ednh x\\u00e1c c\\u1ee7a d\\u1eef li\\u1ec7u, c\\u01a1 ch\\u1ebf ph\\u00e2n quy\\u1ec1n v\\u00e0 s\\u1ef1 \\u1ed5n \\u0111\\u1ecbnh khi nhi\\u1ec1u \\nng\\u01b0\\u1eddi d\\u00f9ng thao t\\u00e1c. Nh\\u1eefng \\u0111i\\u1ec1u ki\\u1ec7n n\\u00e0y c\\u1ea7n \\u0111\\u01b0\\u1ee3c ki\\u1ec3m tra tr\\u01b0\\u1edbc khi tri\\u1ec3n khai \\nch\\u00ednh th\\u1ee9c trong m\\u00f4i tr\\u01b0\\u1eddng qu\\u1ea3n l\\u00fd kh\\u00f3a lu\\u1eadn c\\u1ee7a khoa ho\\u1eb7c nh\\u00e0 tr\\u01b0\\u1eddng. \\nRi\\u00eang ch\\u1ee9c n\\u0103ng AI, c\\u00e1c y\\u1ebfu t\\u1ed1 c\\u1ea7n quan t\\u00e2m g\\u1ed3m chi ph\\u00ed g\\u1ecdi API, th\\u1eddi \\ngian x\\u1eed l\\u00fd t\\u00e0i li\\u1ec7u d\\u00e0i, kh\\u1ea3 n\\u0103ng x\\u1eed l\\u00fd l\\u1ed7i k\\u1ebft n\\u1ed1i v\\u00e0 b\\u1ea3o m\\u1eadt n\\u1ed9i dung b\\u00e1o c\\u00e1o khi \\ng\\u1eedi \\u0111\\u1ebfn d\\u1ecbch v\\u1ee5 b\\u00ean ngo\\u00e0i. Ng\\u01b0\\u1eddi d\\u00f9ng c\\u1ea7n c\\u00f3 kh\\u1ea3 n\\u0103ng truy c\\u1eadp b\\u00e1o c\\u00e1o g\\u1ed1c \\u0111\\u1ec3 \\nki\\u1ec3m tra tr\\u01b0\\u1edbc khi \\u0111\\u01b0a ra \\u0111\\u00e1nh gi\\u00e1. \\nVi\\u1ec7c s\\u1eed d\\u1ee5ng h\\u1ec7 th\\u1ed1ng \\u1edf quy m\\u00f4 l\\u1edbn n\\u00ean \\u0111\\u01b0\\u1ee3c xem x\\u00e9t sau khi ho\\u00e0n t\\u1ea5t \\nc\\u00e1c tr\\u01b0\\u1eddng h\\u1ee3p th\\u1eed nghi\\u1ec7m \\u0111\\u1ea1i di\\u1ec7n. B\\u00e1o c\\u00e1o c\\u1ea7n ph\\u00e2n bi\\u1ec7t k\\u1ebft qu\\u1ea3 \\u0111\\u00e3 quan s\\u00e1t \\ntrong m\\u00f4i tr\\u01b0\\u1eddng th\\u1eed nghi\\u1ec7m v\\u00e0 nh\\u1eefng \\u0111i\\u1ec1u ki\\u1ec7n d\\u1ef1 ki\\u1ebfn khi m\\u1edf r\\u1ed9ng tri\\u1ec3n khai. \\n6.8.  K\\u1ebeT CH\\u01af\\u01a0NG \\nCh\\u01b0\\u01a1ng 6 \\u0111\\u00e3 tr\\u00ecnh b\\u00e0y qu\\u00e1 tr\\u00ecnh th\\u1eed nghi\\u1ec7m v\\u00e0 \\u0111\\u00e1nh gi\\u00e1 h\\u1ec7 th\\u1ed1ng qu\\u1ea3n l\\u00fd \\nc\\u00f4ng t\\u00e1c kh\\u00f3a lu\\u1eadn t\\u1ed1t nghi\\u1ec7p sau khi ho\\u00e0n th\\u00e0nh c\\u00e1c giai \\u0111o\\u1ea1n ph\\u00e2n t\\u00edch, thi\\u1ebft k\\u1ebf \\nv\\u00e0 c\\u00e0i \\u0111\\u1eb7t. N\\u1ed9i dung th\\u1eed nghi\\u1ec7m t\\u1eadp trung v\\u00e0o c\\u00e1c quy tr\\u00ecnh nghi\\u1ec7p v\\u1ee5 ch\\u00ednh g\\u1ed3m \\nl\\u1eadp k\\u1ebf ho\\u1ea1ch kh\\u00f3a lu\\u1eadn, qu\\u1ea3n l\\u00fd v\\u00e0 \\u0111\\u0103ng k\\u00fd \\u0111\\u1ec1 t\\u00e0i, theo d\\u00f5i ti\\u1ebfn \\u0111\\u1ed9, qu\\u1ea3n l\\u00fd b\\u1ea3o \\nv\\u1ec7 v\\u00e0 th\\u1ed1ng k\\u00ea k\\u1ebft qu\\u1ea3 \\u0111\\u1ed1i v\\u1edbi ba nh\\u00f3m ng\\u01b0\\u1eddi d\\u00f9ng l\\u00e0 Gi\\u00e1o v\\u1ee5, Gi\\u1ea3ng vi\\u00ean v\\u00e0 \\nSinh vi\\u00ean. \\nB\\u00ean c\\u1ea1nh vi\\u1ec7c th\\u1eed nghi\\u1ec7m c\\u00e1c ch\\u1ee9c n\\u0103ng qu\\u1ea3n l\\u00fd, ch\\u01b0\\u01a1ng \\u0111\\u00e3 tri\\u1ec3n khai v\\u00e0 \\n\\u0111\\u00e1nh gi\\u00e1 ch\\u1ee9c n\\u0103ng t\\u1ef1 \\u0111\\u1ed9ng t\\u00f3m t\\u1eaft b\\u00e1o c\\u00e1o. Quy tr\\u00ecnh x\\u1eed l\\u00fd bao g\\u1ed3m tr\\u00edch xu\\u1ea5t \\nn\\u1ed9i dung b\\u00e1o c\\u00e1o, ph\\u00e2n \\u0111o\\u1ea1n v\\u0103n b\\u1ea3n b\\u1eb1ng Chunking, g\\u1eedi t\\u1eebng ph\\u1ea7n n\\u1ed9i dung \\n\\u0111\\u1ebfn LLM, t\\u1ed5ng h\\u1ee3p c\\u00e1c k\\u1ebft qu\\u1ea3 b\\u1eb1ng ph\\u01b0\\u01a1ng ph\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":134,\"snippet\":\"\\u0111\\u1ec1 t\\u00e0i, theo d\\u00f5i ti\\u1ebfn \\u0111\\u1ed9, qu\\u1ea3n l\\u00fd b\\u1ea3o \\nv\\u1ec7 v\\u00e0 th\\u1ed1ng k\\u00ea k\\u1ebft qu\\u1ea3 \\u0111\\u1ed1i v\\u1edbi ba nh\\u00f3m ng\\u01b0\\u1eddi d\\u00f9ng l\\u00e0 Gi\\u00e1o v\\u1ee5, Gi\\u1ea3ng vi\\u00ean v\\u00e0 \\nSinh vi\\u00ean. \\nB\\u00ean c\\u1ea1nh vi\\u1ec7c th\\u1eed nghi\\u1ec7m c\\u00e1c ch\\u1ee9c n\\u0103ng qu\\u1ea3n l\\u00fd, ch\\u01b0\\u01a1ng \\u0111\\u00e3 tri\\u1ec3n khai v\\u00e0 \\n\\u0111\\u00e1nh gi\\u00e1 ch\\u1ee9c n\\u0103ng t\\u1ef1 \\u0111\\u1ed9ng t\\u00f3m t\\u1eaft b\\u00e1o c\\u00e1o. Quy tr\\u00ecnh x\\u1eed l\\u00fd bao g\\u1ed3m tr\\u00edch xu\\u1ea5t \\nn\\u1ed9i dung b\\u00e1o c\\u00e1o, ph\\u00e2n \\u0111o\\u1ea1n v\\u0103n b\\u1ea3n b\\u1eb1ng Chunking, g\\u1eedi t\\u1eebng ph\\u1ea7n n\\u1ed9i dung \\n\\u0111\\u1ebfn LLM, t\\u1ed5ng h\\u1ee3p c\\u00e1c k\\u1ebft qu\\u1ea3 b\\u1eb1ng ph\\u01b0\\u01a1ng ph\\u00e1p Map\\u2013Reduce v\\u00e0 t\\u00edch h\\u1ee3p k\\u1ebft \\nqu\\u1ea3 t\\u00f3m t\\u1eaft tr\\u1edf l\\u1ea1i h\\u1ec7 th\\u1ed1ng. N\\u1ed9i dung n\\u00e0y nh\\u1eb1m h\\u1ed7 tr\\u1ee3 gi\\u1ea3ng vi\\u00ean nhanh ch\\u00f3ng \\nn\\u1eafm b\\u1eaft nh\\u1eefng th\\u00f4ng tin quan tr\\u1ecdng trong qu\\u00e1 tr\\u00ecnh th\\u1ef1c hi\\u1ec7n kh\\u00f3a lu\\u1eadn c\\u1ee7a sinh \\nvi\\u00ean. \\nTh\\u00f4ng qua qu\\u00e1 tr\\u00ecnh th\\u1eed nghi\\u1ec7m, k\\u1ebft qu\\u1ea3 th\\u1eed nghi\\u1ec7m l\\u00e0 c\\u01a1 s\\u1edf \\u0111\\u1ec3 x\\u00e1c \\u0111\\u1ecbnh \\nnh\\u1eefng ch\\u1ee9c n\\u0103ng \\u0111\\u00e3 \\u0111\\u00e1p \\u1ee9ng y\\u00eau c\\u1ea7u, nh\\u1eefng \\u0111i\\u1ec3m c\\u00f2n h\\u1ea1n ch\\u1ebf v\\u00e0 kh\\u1ea3 n\\u0103ng \\u00e1p \\nd\\u1ee5ng h\\u1ec7 th\\u1ed1ng trong th\\u1ef1c t\\u1ebf. \\u0110\\u1ed3ng th\\u1eddi, c\\u00e1c k\\u1ebft qu\\u1ea3 thu \\u0111\\u01b0\\u1ee3c c\\u0169ng t\\u1ea1o ti\\u1ec1n \\u0111\\u1ec1 \\ncho vi\\u1ec7c t\\u1ed5ng h\\u1ee3p, \\u0111\\u00e1nh gi\\u00e1 to\\u00e0n b\\u1ed9 qu\\u00e1 tr\\u00ecnh th\\u1ef1c hi\\u1ec7n \\u0111\\u1ec1 t\\u00e0i, x\\u00e1c \\u0111\\u1ecbnh nh\\u1eefng \\n 1\\n\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":135,\"snippet\":\"k\\u1ebft qu\\u1ea3 \\u0111\\u1ea1t \\u0111\\u01b0\\u1ee3c v\\u00e0 \\u0111\\u1ec1 xu\\u1ea5t h\\u01b0\\u1edbng ph\\u00e1t tri\\u1ec3n trong t\\u01b0\\u01a1ng lai. \\n 1\\n\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":136,\"snippet\":\"K\\u1ebeT LU\\u1eacN \\n\\u2013 K\\u1ebft qu\\u1ea3 \\u0111\\u1ea1t \\u0111\\u01b0\\u1ee3c: Tr\\u00ecnh b\\u00e0y t\\u00f3m t\\u1eaft k\\u1ebft qu\\u1ea3 \\u0111\\u1ea1t \\u0111\\u01b0\\u1ee3c c\\u1ee7a \\u0111\\u1ec1 t\\u00e0i \\n\\u2013 \\u0110\\u00e1nh gi\\u00e1 k\\u1ebft qu\\u1ea3: X\\u00e1c \\u0111\\u1ecbnh h\\u1ec7 th\\u1ed1ng \\u0111\\u00e3 ho\\u00e0n th\\u00e0nh \\u0111\\u01b0\\u1ee3c nh\\u1eefng y\\u00eau c\\u1ea7u n\\u00e0o, \\nm\\u1ee9c \\u0111\\u1ed9 ho\\u00e0n thi\\u1ec7n bao nhi\\u00eau so v\\u1edbi m\\u1ee5c ti\\u00eau ban \\u0111\\u1ea7u. \\n\\u2013 H\\u1ea1n ch\\u1ebf: N\\u00eau ra nh\\u1eefng \\u0111i\\u1ec3m c\\u00f2n h\\u1ea1n ch\\u1ebf, kh\\u00f3 kh\\u0103n g\\u1eb7p ph\\u1ea3i trong qu\\u00e1 tr\\u00ecnh \\nth\\u1ef1c hi\\u1ec7n. \\n\\u2013 H\\u01b0\\u1edbng ph\\u00e1t tri\\u1ec3n: \\u0110\\u1ec1 xu\\u1ea5t c\\u00e1c c\\u1ea3i ti\\u1ebfn ho\\u1eb7c m\\u1edf r\\u1ed9ng \\u0111\\u1ec3 ph\\u00e1t tri\\u1ec3n h\\u1ec7 th\\u1ed1ng \\nho\\u00e0n thi\\u1ec7n h\\u01a1n trong t\\u01b0\\u01a1ng lai. \\n