REPLACE INTO `khoibaocaotiendo` (`id`, `MaKhoi`, `MaBaoCao`, `MaDotNop`, `MaGiaiDoan`, `MaDeTai`, `LanBaoCao`, `LanNop`, `TieuDe`, `NoiDungBaoCao`, `KetQuaDatDuoc`, `KhoKhan`, `CongViecChuaHoanThanh`, `HuongGiaiQuyet`, `KeHoachTiepTheo`, `TenFile`, `DuongDanFile`, `LinkCode`, `TrangThai`, `PhanTramHoanThanh`, `NhanXetGV`, `NguoiNhanXet`, `NgayNop`, `NgayNhanXet`, `TomTatAI`, `TomTatJson`, `created_at`, `updated_at`) VALUES ('3', 'KHOI_D1_V3_0c9bd7', 'BC_DOT_1', '1', '1', 'DT27', '1', '3', 'Đợt 1 – Khảo sát và mô tả nghiệp vụ (Phiên bản 3)', 'test phân tích', '', '', '', '', '', '01_Quan ly do an_v5.pdf', 'baocao/baocao_dot1_v3_e6cb732b8ae6d1c1.pdf', NULL, 'Chờ duyệt', NULL, NULL, NULL, '2026-11-01 10:02:00', NULL, 'Báo cáo trình bày tổng quan về hệ thống quản lý khóa luận tại Khoa Công nghệ Thông tin, Trường Đại học Công Thương Thành phố Hồ Chí Minh, bao gồm khảo sát quy trình nghiệp vụ, phân tích và thiết kế hệ thống với các nhóm người dùng chính. Đồng thời, tác giả xây dựng cơ sở lý thuyết về mô hình Client - Server, kiến trúc MVC, cơ sở dữ liệu quan hệ và tích hợp mô hình ngôn ngữ lớn.

Trong giai đoạn thực hiện, tác giả đã tiến hành cài đặt ứng dụng web bằng PHP, Laravel và cơ sở dữ liệu MySQL, kết hợp tính năng tự động tóm tắt báo cáo tiến độ bằng AI thông qua phương pháp Map-Reduce. Quá trình thử nghiệm cho thấy hệ thống thực hiện được các thao tác quản lý cơ bản, tuy nhiên chức năng xử lý tài liệu và kiểm thử vẫn còn một số hạn chế về thời gian, độ ổn định và phạm vi đánh giá.', '{\"overall_summary\":\"B\\u00e1o c\\u00e1o tr\\u00ecnh b\\u00e0y t\\u1ed5ng quan v\\u1ec1 h\\u1ec7 th\\u1ed1ng qu\\u1ea3n l\\u00fd kh\\u00f3a lu\\u1eadn t\\u1ea1i Khoa C\\u00f4ng ngh\\u1ec7 Th\\u00f4ng tin, Tr\\u01b0\\u1eddng \\u0110\\u1ea1i h\\u1ecdc C\\u00f4ng Th\\u01b0\\u01a1ng Th\\u00e0nh ph\\u1ed1 H\\u1ed3 Ch\\u00ed Minh, bao g\\u1ed3m kh\\u1ea3o s\\u00e1t quy tr\\u00ecnh nghi\\u1ec7p v\\u1ee5, ph\\u00e2n t\\u00edch v\\u00e0 thi\\u1ebft k\\u1ebf h\\u1ec7 th\\u1ed1ng v\\u1edbi c\\u00e1c nh\\u00f3m ng\\u01b0\\u1eddi d\\u00f9ng ch\\u00ednh. \\u0110\\u1ed3ng th\\u1eddi, t\\u00e1c gi\\u1ea3 x\\u00e2y d\\u1ef1ng c\\u01a1 s\\u1edf l\\u00fd thuy\\u1ebft v\\u1ec1 m\\u00f4 h\\u00ecnh Client - Server, ki\\u1ebfn tr\\u00fac MVC, c\\u01a1 s\\u1edf d\\u1eef li\\u1ec7u quan h\\u1ec7 v\\u00e0 t\\u00edch h\\u1ee3p m\\u00f4 h\\u00ecnh ng\\u00f4n ng\\u1eef l\\u1edbn.\\n\\nTrong giai \\u0111o\\u1ea1n th\\u1ef1c hi\\u1ec7n, t\\u00e1c gi\\u1ea3 \\u0111\\u00e3 ti\\u1ebfn h\\u00e0nh c\\u00e0i \\u0111\\u1eb7t \\u1ee9ng d\\u1ee5ng web b\\u1eb1ng PHP, Laravel v\\u00e0 c\\u01a1 s\\u1edf d\\u1eef li\\u1ec7u MySQL, k\\u1ebft h\\u1ee3p t\\u00ednh n\\u0103ng t\\u1ef1 \\u0111\\u1ed9ng t\\u00f3m t\\u1eaft b\\u00e1o c\\u00e1o ti\\u1ebfn \\u0111\\u1ed9 b\\u1eb1ng AI th\\u00f4ng qua ph\\u01b0\\u01a1ng ph\\u00e1p Map-Reduce. Qu\\u00e1 tr\\u00ecnh th\\u1eed nghi\\u1ec7m cho th\\u1ea5y h\\u1ec7 th\\u1ed1ng th\\u1ef1c hi\\u1ec7n \\u0111\\u01b0\\u1ee3c c\\u00e1c thao t\\u00e1c qu\\u1ea3n l\\u00fd c\\u01a1 b\\u1ea3n, tuy nhi\\u00ean ch\\u1ee9c n\\u0103ng x\\u1eed l\\u00fd t\\u00e0i li\\u1ec7u v\\u00e0 ki\\u1ec3m th\\u1eed v\\u1eabn c\\u00f2n m\\u1ed9t s\\u1ed1 h\\u1ea1n ch\\u1ebf v\\u1ec1 th\\u1eddi gian, \\u0111\\u1ed9 \\u1ed5n \\u0111\\u1ecbnh v\\u00e0 ph\\u1ea1m vi \\u0111\\u00e1nh gi\\u00e1.\",\"completed_work\":[{\"content\":\"S\\u1eed d\\u1ee5ng LLM d\\u1ecbch v\\u1ee5 \\u0111\\u00e3 hu\\u1ea5n luy\\u1ec7n s\\u1eb5n kh\\u00f4ng t\\u1ef1 tinh ch\\u1ec9nh v\\u00e0 d\\u00f9ng PyMuPDF \\u0111\\u1ec3 tr\\u00edch xu\\u1ea5t v\\u0103n b\\u1ea3n, t\\u00ecm d\\u1ea5u hi\\u1ec7u nh\\u1eadn di\\u1ec7n ch\\u01b0\\u01a1ng m\\u1ee5c t\\u1eeb PDF, k\\u1ebft h\\u1ee3p th\\u01b0 vi\\u1ec7n PHP qu\\u1ea3n l\\u00fd qua Composer v\\u00e0 t\\u00edch h\\u1ee3p API m\\u00f4 h\\u00ecnh ng\\u00f4n ng\\u1eef l\\u1edbn \\u0111\\u1ec3 ph\\u00e2n t\\u00edch, t\\u00f3m t\\u1eaft b\\u00e1o c\\u00e1o.\",\"kind\":\"reported_work\",\"source_ids\":[\"AI-006:0010\",\"AI-008:0002\",\"AI-008:0004\",\"AI-009:0005\",\"AI-009:0006\"],\"source_pages\":[45,51,52,57],\"evidence\":\"Trong h\\u1ec7 th\\u1ed1ng c\\u1ee7a nh\\u00f3m, LLM \\u0111\\u01b0\\u1ee3c s\\u1eed d\\u1ee5ng nh\\u01b0 m\\u1ed9t d\\u1ecbch v\\u1ee5 \\u0111\\u00e3 hu\\u1ea5n luy\\u1ec7n \\ns\\u1eb5n \\u0111\\u1ec3 h\\u1ed7 tr\\u1ee3 \\u0111\\u1ecdc b\\u00e1o c\\u00e1o. Nh\\u00f3m kh\\u00f4ng t\\u1ef1 hu\\u1ea5n luy\\u1ec7n hay tinh ch\\u1ec9nh c\\u00e1c tham s\\u1ed1 \\nc\\u1ee7a m\\u00f4 h\\u00ecnh.\",\"source_references\":[{\"source_id\":\"AI-006:0010\",\"page\":45,\"end_page\":45,\"quote\":\"Trong h\\u1ec7 th\\u1ed1ng c\\u1ee7a nh\\u00f3m, LLM \\u0111\\u01b0\\u1ee3c s\\u1eed d\\u1ee5ng nh\\u01b0 m\\u1ed9t d\\u1ecbch v\\u1ee5 \\u0111\\u00e3 hu\\u1ea5n luy\\u1ec7n \\ns\\u1eb5n \\u0111\\u1ec3 h\\u1ed7 tr\\u1ee3 \\u0111\\u1ecdc b\\u00e1o c\\u00e1o. Nh\\u00f3m kh\\u00f4ng t\\u1ef1 hu\\u1ea5n luy\\u1ec7n hay tinh ch\\u1ec9nh c\\u00e1c tham s\\u1ed1 \\nc\\u1ee7a m\\u00f4 h\\u00ecnh.\",\"start\":63630,\"end\":63795,\"quote_verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"source_id\":\"AI-008:0002\",\"page\":51,\"end_page\":51,\"quote\":\"Trong ph\\u1ea1m vi x\\u1eed l\\u00fd hi\\u1ec7n t\\u1ea1i, nh\\u00f3m s\\u1eed d\\u1ee5ng PyMuPDF \\u0111\\u1ec3 tr\\u00edch xu\\u1ea5t v\\u0103n b\\u1ea3n v\\u00e0 \\nth\\u00f4ng tin trang t\\u1eeb PDF c\\u00f3 l\\u1edbp v\\u0103n b\\u1ea3n.\",\"start\":75776,\"end\":75891,\"quote_verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"source_id\":\"AI-008:0004\",\"page\":52,\"end_page\":52,\"quote\":\"Sau khi nh\\u1eadn b\\u00e1o c\\u00e1o PDF, ch\\u01b0\\u01a1ng tr\\u00ecnh tr\\u00edch xu\\u1ea5t v\\u0103n b\\u1ea3n r\\u1ed3i t\\u00ecm c\\u00e1c d\\u1ea5u \\nhi\\u1ec7u nh\\u1eadn di\\u1ec7n ch\\u01b0\\u01a1ng, m\\u1ee5c nh\\u01b0 s\\u1ed1 \\u0111\\u1ec1 m\\u1ee5c, ti\\u00eau \\u0111\\u1ec1 ho\\u1eb7c c\\u00e1ch tr\\u00ecnh b\\u00e0y.\",\"start\":77848,\"end\":77993,\"quote_verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"source_id\":\"AI-009:0005\",\"page\":57,\"end_page\":57,\"quote\":\"H\\u1ec7 th\\u1ed1ng s\\u1eed d\\u1ee5ng c\\u00e1c th\\u01b0 vi\\u1ec7n PHP \\u0111\\u01b0\\u1ee3c qu\\u1ea3n l\\u00fd th\\u00f4ng qua Composer \\u0111\\u1ec3 h\\u1ed7 \\ntr\\u1ee3 x\\u1eed l\\u00fd v\\u00e0 tr\\u00edch xu\\u1ea5t n\\u1ed9i dung t\\u1eeb c\\u00e1c t\\u1ec7p t\\u00e0i li\\u1ec7u.\",\"start\":86802,\"end\":86928,\"quote_verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"source_id\":\"AI-009:0006\",\"page\":57,\"end_page\":57,\"quote\":\"H\\u1ec7 th\\u1ed1ng t\\u00edch h\\u1ee3p API c\\u1ee7a m\\u00f4 h\\u00ecnh ng\\u00f4n ng\\u1eef l\\u1edbn (LLM) \\u0111\\u1ec3 th\\u1ef1c hi\\u1ec7n ch\\u1ee9c \\nn\\u0103ng ph\\u00e2n t\\u00edch v\\u00e0 t\\u00f3m t\\u1eaft n\\u1ed9i dung b\\u00e1o c\\u00e1o.\",\"start\":87758,\"end\":87873,\"quote_verified\":true,\"semantic_support\":\"NOT_VERIFIED\"}],\"verified\":true,\"relevance_verified\":false,\"semantic_support\":\"NOT_VERIFIED\"},{\"content\":\"Ph\\u00e2n t\\u00edch h\\u1ec7 th\\u1ed1ng qu\\u1ea3n l\\u00fd c\\u00f4ng t\\u00e1c kh\\u00f3a lu\\u1eadn t\\u1ed1t nghi\\u1ec7p b\\u1eb1ng UML \\u0111\\u1ec3 bi\\u1ec3u di\\u1ec5n quy tr\\u00ecnh nghi\\u1ec7p v\\u1ee5, ch\\u1ee9c n\\u0103ng v\\u00e0 x\\u00e1c \\u0111\\u1ecbnh c\\u00e1c y\\u00eau c\\u1ea7u nghi\\u1ec7p v\\u1ee5, lu\\u1ed3ng s\\u1ef1 ki\\u1ec7n c\\u00f9ng c\\u1ea5u tr\\u00fac d\\u1eef li\\u1ec7u c\\u01a1 s\\u1edf cho thi\\u1ebft k\\u1ebf.\",\"kind\":\"reported_work\",\"source_ids\":[\"AI-012:0001\",\"AI-012:0003\"],\"source_pages\":[79],\"evidence\":\"Trong ch\\u01b0\\u01a1ng 3, nh\\u00f3m \\u0111\\u00e3 ti\\u1ebfn h\\u00e0nh ph\\u00e2n t\\u00edch h\\u1ec7 th\\u1ed1ng qu\\u1ea3n l\\u00fd c\\u00f4ng t\\u00e1c kh\\u00f3a lu\\u1eadn t\\u1ed1t nghi\\u1ec7p b\\u1eb1ng c\\u00e1ch \\u00e1p d\\u1ee5ng c\\u00e1c c\\u00f4ng c\\u1ee5 m\\u00f4 h\\u00ecnh h\\u00f3a UML \\u0111\\u1ec3 bi\\u1ec3u di\\u1ec5n quy tr\\u00ecnh nghi\\u1ec7p v\\u1ee5 v\\u00e0 ch\\u1ee9c n\\u0103ng h\\u1ec7 th\\u1ed1ng.\",\"source_references\":[{\"source_id\":\"AI-012:0001\",\"page\":79,\"end_page\":79,\"quote\":\"Trong ch\\u01b0\\u01a1ng 3, nh\\u00f3m \\u0111\\u00e3 ti\\u1ebfn h\\u00e0nh ph\\u00e2n t\\u00edch h\\u1ec7 th\\u1ed1ng qu\\u1ea3n l\\u00fd c\\u00f4ng t\\u00e1c kh\\u00f3a lu\\u1eadn t\\u1ed1t nghi\\u1ec7p b\\u1eb1ng c\\u00e1ch \\u00e1p d\\u1ee5ng c\\u00e1c c\\u00f4ng c\\u1ee5 m\\u00f4 h\\u00ecnh h\\u00f3a UML \\u0111\\u1ec3 bi\\u1ec3u di\\u1ec5n quy tr\\u00ecnh nghi\\u1ec7p v\\u1ee5 v\\u00e0 ch\\u1ee9c n\\u0103ng h\\u1ec7 th\\u1ed1ng.\",\"start\":104450,\"end\":104644,\"quote_verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"source_id\":\"AI-012:0003\",\"page\":79,\"end_page\":79,\"quote\":\"K\\u1ebft qu\\u1ea3 ph\\u00e2n t\\u00edch \\u0111\\u00e3 ch\\u1ec9 ra \\u0111\\u01b0\\u1ee3c c\\u00e1c y\\u00eau c\\u1ea7u nghi\\u1ec7p v\\u1ee5, c\\u00e1c lu\\u1ed3ng s\\u1ef1 ki\\u1ec7n ch\\u00ednh v\\u00e0 ph\\u1ee5, c\\u0169ng nh\\u01b0 c\\u1ea5u tr\\u00fac d\\u1eef li\\u1ec7u c\\u1ea7n thi\\u1ebft cho h\\u1ec7 th\\u1ed1ng. \\u0110\\u00e2y l\\u00e0 c\\u01a1 s\\u1edf quan tr\\u1ecdng \\u0111\\u1ec3 chuy\\u1ec3n sang giai \\u0111o\\u1ea1n thi\\u1ebft k\\u1ebf, \\u0111\\u1ea3m b\\u1ea3o r\\u1eb1ng h\\u1ec7 th\\u1ed1ng \\u0111\\u01b0\\u1ee3c x\\u00e2y d\\u1ef1ng ph\\u00f9 h\\u1ee3p v\\u1edbi m\\u1ee5c ti\\u00eau \\u0111\\u1ec1 t\\u00e0i, \\u0111\\u00e1p \\u1ee9ng nhu c\\u1ea7u qu\\u1ea3n l\\u00fd th\\u1ef1c t\\u1ebf v\\u00e0 h\\u1ed7 tr\\u1ee3 qu\\u00e1 tr\\u00ecnh s\\u1ed1 h\\u00f3a c\\u00f4ng t\\u00e1c kh\\u00f3a lu\\u1eadn t\\u1ed1t nghi\\u1ec7p.\",\"start\":104861,\"end\":105216,\"quote_verified\":true,\"semantic_support\":\"NOT_VERIFIED\"}],\"verified\":true,\"relevance_verified\":false,\"semantic_support\":\"NOT_VERIFIED\"},{\"content\":\"Th\\u1eed nghi\\u1ec7m h\\u1ec7 th\\u1ed1ng qu\\u1ea3n l\\u00fd kh\\u00f3a lu\\u1eadn v\\u1edbi PHP, Laravel, MySQL, Blade, HTML, CSS, JavaScript v\\u00e0 t\\u00edch h\\u1ee3p t\\u00ednh n\\u0103ng x\\u1eed l\\u00fd b\\u00e1o c\\u00e1o ti\\u1ebfn \\u0111\\u1ed9 b\\u1eb1ng LLM, PyMuPDF, Laravel queue k\\u1ebft h\\u1ee3p worker g\\u1ecdi Python; \\u0111\\u1ed3ng th\\u1eddi ki\\u1ec3m th\\u1eed quy tr\\u00ecnh \\u0111\\u0103ng t\\u1ea3i, c\\u00f4ng b\\u1ed1 k\\u1ebf ho\\u1ea1ch.\",\"kind\":\"reported_work\",\"source_ids\":[\"AI-021:0001\",\"AI-021:0002\",\"AI-021:0005\",\"AI-021:0006\",\"AI-021:0008\",\"AI-023:0002\",\"AI-023:0007\"],\"source_pages\":[124,125,126,127,141,143],\"evidence\":\"Sau khi ho\\u00e0n th\\u00e0nh qu\\u00e1 tr\\u00ecnh ph\\u00e2n t\\u00edch, thi\\u1ebft k\\u1ebf v\\u00e0 c\\u00e0i \\u0111\\u1eb7t, h\\u1ec7 th\\u1ed1ng qu\\u1ea3n l\\u00fd \\nc\\u00f4ng t\\u00e1c kh\\u00f3a lu\\u1eadn t\\u1ed1t nghi\\u1ec7p \\u0111\\u01b0\\u1ee3c ti\\u1ebfn h\\u00e0nh th\\u1eed nghi\\u1ec7m nh\\u1eb1m \\u0111\\u00e1nh gi\\u00e1 m\\u1ee9c \\u0111\\u1ed9 \\n\\u0111\\u00e1p \\u1ee9ng c\\u00e1c y\\u00eau c\\u1ea7u nghi\\u1ec7p v\\u1ee5 v\\u00e0 m\\u1ee5c ti\\u00eau \\u0111\\u00e3 \\u0111\\u1ec1 ra.\",\"source_references\":[{\"source_id\":\"AI-021:0001\",\"page\":124,\"end_page\":124,\"quote\":\"Sau khi ho\\u00e0n th\\u00e0nh qu\\u00e1 tr\\u00ecnh ph\\u00e2n t\\u00edch, thi\\u1ebft k\\u1ebf v\\u00e0 c\\u00e0i \\u0111\\u1eb7t, h\\u1ec7 th\\u1ed1ng qu\\u1ea3n l\\u00fd \\nc\\u00f4ng t\\u00e1c kh\\u00f3a lu\\u1eadn t\\u1ed1t nghi\\u1ec7p \\u0111\\u01b0\\u1ee3c ti\\u1ebfn h\\u00e0nh th\\u1eed nghi\\u1ec7m nh\\u1eb1m \\u0111\\u00e1nh gi\\u00e1 m\\u1ee9c \\u0111\\u1ed9 \\n\\u0111\\u00e1p \\u1ee9ng c\\u00e1c y\\u00eau c\\u1ea7u nghi\\u1ec7p v\\u1ee5 v\\u00e0 m\\u1ee5c ti\\u00eau \\u0111\\u00e3 \\u0111\\u1ec1 ra.\",\"start\":147791,\"end\":147999,\"quote_verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"source_id\":\"AI-021:0002\",\"page\":124,\"end_page\":124,\"quote\":\"Ngo\\u00e0i c\\u00e1c ch\\u1ee9c n\\u0103ng qu\\u1ea3n l\\u00fd truy\\u1ec1n th\\u1ed1ng, h\\u1ec7 th\\u1ed1ng c\\u00f2n t\\u00edch h\\u1ee3p ch\\u1ee9c n\\u0103ng \\nh\\u1ed7 tr\\u1ee3 x\\u1eed l\\u00fd b\\u00e1o c\\u00e1o ti\\u1ebfn \\u0111\\u1ed9 b\\u1eb1ng m\\u00f4 h\\u00ecnh ng\\u00f4n ng\\u1eef l\\u1edbn (LLM).\",\"start\":148545,\"end\":148681,\"quote_verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"source_id\":\"AI-021:0005\",\"page\":125,\"end_page\":125,\"quote\":\"M\\u00f4i tr\\u01b0\\u1eddng th\\u1eed nghi\\u1ec7m \\u0111\\u01b0\\u1ee3c x\\u00e2y d\\u1ef1ng d\\u1ef1a tr\\u00ean c\\u1ea5u h\\u00ecnh c\\u00e0i \\u0111\\u1eb7t \\u1edf Ch\\u01b0\\u01a1ng \\n5. Theo b\\u00e1o c\\u00e1o thi\\u1ebft k\\u1ebf, h\\u1ec7 th\\u1ed1ng s\\u1eed d\\u1ee5ng PHP v\\u00e0 Laravel \\u1edf ph\\u00eda m\\u00e1y ch\\u1ee7, \\nMySQL \\u0111\\u1ec3 qu\\u1ea3n l\\u00fd d\\u1eef li\\u1ec7u, c\\u00f9ng Blade, HTML, CSS v\\u00e0 JavaScript \\u0111\\u1ec3 x\\u00e2y d\\u1ef1ng \\ngiao di\\u1ec7n ng\\u01b0\\u1eddi d\\u00f9ng.\",\"start\":150917,\"end\":151160,\"quote_verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"source_id\":\"AI-021:0006\",\"page\":126,\"end_page\":126,\"quote\":\"D\\u1eef li\\u1ec7u th\\u1eed nghi\\u1ec7m \\u0111\\u01b0\\u1ee3c chia th\\u00e0nh hai nh\\u00f3m. Nh\\u00f3m d\\u1eef li\\u1ec7u nghi\\u1ec7p v\\u1ee5 \\ng\\u1ed3m h\\u1ecdc k\\u1ef3, gi\\u00e1o v\\u1ee5, gi\\u1ea3ng vi\\u00ean, sinh vi\\u00ean, \\u0111\\u1ec1 t\\u00e0i, phi\\u1ebfu \\u0111\\u0103ng k\\u00fd, b\\u00e1o c\\u00e1o ti\\u1ebfn \\u0111\\u1ed9, \\nh\\u1ed3 s\\u01a1 b\\u1ea3o v\\u1ec7 v\\u00e0 k\\u1ebft qu\\u1ea3. Nh\\u00f3m d\\u1eef li\\u1ec7u AI g\\u1ed3m c\\u00e1c b\\u00e1o c\\u00e1o PDF m\\u00e0 nh\\u00f3m c\\u00f3 \\nquy\\u1ec1n s\\u1eed d\\u1ee5ng \\u0111\\u1ec3 ki\\u1ec3m tra quy tr\\u00ecnh tr\\u00edch xu\\u1ea5t v\\u00e0 t\\u00f3m t\\u1eaft n\\u1ed9i dung.\",\"start\":151886,\"end\":152180,\"quote_verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"source_id\":\"AI-021:0008\",\"page\":127,\"end_page\":127,\"quote\":\"K\\u1ebft qu\\u1ea3 ki\\u1ec3m th\\u1eed cho th\\u1ea5y h\\u1ec7 th\\u1ed1ng th\\u1ef1c hi\\u1ec7n \\u0111\\u01b0\\u1ee3c c\\u00e1c thao t\\u00e1c l\\u01b0u k\\u1ebf \\nho\\u1ea1ch, ki\\u1ec3m tra d\\u1eef li\\u1ec7u b\\u1eaft bu\\u1ed9c, c\\u1eadp nh\\u1eadt k\\u1ebf ho\\u1ea1ch c\\u00f9ng h\\u1ecdc k\\u1ef3 v\\u00e0 c\\u00f4ng b\\u1ed1 k\\u1ebf \\nho\\u1ea1ch.\",\"start\":154686,\"end\":154842,\"quote_verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"source_id\":\"AI-023:0002\",\"page\":141,\"end_page\":141,\"quote\":\"B\\u1ea3n tri\\u1ec3n khai s\\u1eed d\\u1ee5ng PyMuPDF 1.28.2 tr\\u00ean Python 3.10.6 \\u0111\\u1ec3 tr\\u00edch xu\\u1ea5t v\\u0103n b\\u1ea3n, c\\u1ee1 ch\\u1eef v\\u00e0 v\\u1ecb tr\\u00ed ngu\\u1ed3n.\",\"start\":164847,\"end\":164951,\"quote_verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"source_id\":\"AI-023:0007\",\"page\":143,\"end_page\":143,\"quote\":\"Laravel \\u0111\\u01b0a t\\u00e1c v\\u1ee5 v\\u00e0o h\\u00e0ng \\u0111\\u1ee3i ai-reports, worker php artisan ai:work g\\u1ecdi Python \\u0111\\u1ec3 x\\u1eed l\\u00fd PDF.\",\"start\":167962,\"end\":168058,\"quote_verified\":true,\"semantic_support\":\"NOT_VERIFIED\"}],\"verified\":true,\"relevance_verified\":false,\"semantic_support\":\"NOT_VERIFIED\"},{\"content\":\"Th\\u1ef1c hi\\u1ec7n ch\\u1ea1y ph\\u00e2n \\u0111o\\u1ea1n c\\u1ee5c b\\u1ed9 tr\\u00ean t\\u00e0i li\\u1ec7u PDF th\\u1eed nghi\\u1ec7m, ghi nh\\u1eadn k\\u1ebft qu\\u1ea3 s\\u1ed1 m\\u1ee5c c\\u1ea5u tr\\u00fac, s\\u1ed1 chunk, s\\u1ed1 g\\u00f3i Map v\\u00e0 th\\u1eddi gian quan s\\u00e1t; \\u0111\\u1ed3ng th\\u1eddi \\u0111\\u00e1nh gi\\u00e1 ch\\u1ea5t l\\u01b0\\u1ee3ng t\\u00f3m t\\u1eaft ghi nh\\u1eadn k\\u1ef9 thu\\u1eadt ho\\u00e0n t\\u1ea5t nh\\u01b0ng n\\u1ed9i dung ch\\u01b0a \\u1ed5n \\u0111\\u1ecbnh ho\\u00e0n to\\u00e0n v\\u00e0 th\\u1eddi gian ch\\u01b0a \\u0111\\u1ea1t m\\u1ee5c ti\\u00eau.\",\"kind\":\"reported_work\",\"source_ids\":[\"AI-023:0003\",\"AI-023:0010\",\"AI-024:0001\",\"AI-024:0007\",\"AI-024:0008\"],\"source_pages\":[141,146,151],\"evidence\":\"Ch\\u1ea1y l\\u1ea1i ph\\u00e2n \\u0111o\\u1ea1n c\\u1ee5c b\\u1ed9 tr\\u00ean PDF 124 trang nh\\u1eadn di\\u1ec7n 234 m\\u1ee5c\\/v\\u00f9ng c\\u1ea5u tr\\u00fac, t\\u1ea1o 240 chunk v\\u00e0 \\u0111\\u00f3ng th\\u00e0nh 23 g\\u00f3i Map.\",\"source_references\":[{\"source_id\":\"AI-023:0003\",\"page\":141,\"end_page\":141,\"quote\":\"Ch\\u1ea1y l\\u1ea1i ph\\u00e2n \\u0111o\\u1ea1n c\\u1ee5c b\\u1ed9 tr\\u00ean PDF 124 trang nh\\u1eadn di\\u1ec7n 234 m\\u1ee5c\\/v\\u00f9ng c\\u1ea5u tr\\u00fac, t\\u1ea1o 240 chunk v\\u00e0 \\u0111\\u00f3ng th\\u00e0nh 23 g\\u00f3i Map.\",\"start\":165344,\"end\":165462,\"quote_verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"source_id\":\"AI-023:0010\",\"page\":146,\"end_page\":146,\"quote\":\"Th\\u1eddi gian quan s\\u00e1t l\\u1ea7n l\\u01b0\\u1ee3t l\\u00e0 382 gi\\u00e2y (6 ph\\u00fat 22 gi\\u00e2y), 448 gi\\u00e2y (7 ph\\u00fat 28 gi\\u00e2y) v\\u00e0 901 gi\\u00e2y (15 ph\\u00fat 01 gi\\u00e2y).\",\"start\":171128,\"end\":171243,\"quote_verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"source_id\":\"AI-024:0001\",\"page\":146,\"end_page\":146,\"quote\":\"Ch\\u1ea5t l\\u01b0\\u1ee3ng b\\u1ea3n t\\u00f3m t\\u1eaft \\u0111\\u01b0\\u1ee3c \\u0111\\u00e1nh gi\\u00e1 qua vi\\u1ec7c so s\\u00e1nh t\\u1eebng \\u00fd v\\u1edbi t\\u00e0i li\\u1ec7u PDF. Ngo\\u00e0i y\\u00eau c\\u1ea7u n\\u1ed9i dung ng\\u1eafn g\\u1ecdn, nh\\u00f3m xem x\\u00e9t b\\u1ea3n t\\u00f3m t\\u1eaft c\\u00f3 \\u0111\\u00fang th\\u00f4ng tin, ph\\u1ea3n \\u00e1nh \\u0111\\u01b0\\u1ee3c c\\u00e1c n\\u1ed9i dung ch\\u00ednh v\\u00e0 gi\\u1eef \\u0111\\u00fang c\\u1ea5u tr\\u00fac ch\\u01b0\\u01a1ng, m\\u1ee5c c\\u1ee7a b\\u00e1o c\\u00e1o hay kh\\u00f4ng.\",\"start\":171665,\"end\":171912,\"quote_verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"source_id\":\"AI-024:0007\",\"page\":151,\"end_page\":151,\"quote\":\"Ba t\\u00e1c v\\u1ee5 \\u0111\\u1ea1i di\\u1ec7n \\u0111\\u00e3 ho\\u00e0n t\\u1ea5t v\\u1ec1 k\\u1ef9 thu\\u1eadt, nh\\u01b0ng ki\\u1ec3m tra n\\u1ed9i dung cho th\\u1ea5y ch\\u1ee9c n\\u0103ng ch\\u01b0a \\u1ed5n \\u0111\\u1ecbnh ho\\u00e0n to\\u00e0n \\u1edf ph\\u00e2n c\\u1ea5p ch\\u01b0\\u01a1ng\\/m\\u1ee5c v\\u00e0 vi\\u1ec7c ph\\u00e2n bi\\u1ec7t \\u0111\\u1ec1 c\\u01b0\\u01a1ng v\\u1edbi n\\u1ed9i dung \\u0111\\u00e3 vi\\u1ebft.\",\"start\":179615,\"end\":179797,\"quote_verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"source_id\":\"AI-024:0008\",\"page\":151,\"end_page\":151,\"quote\":\"Th\\u1eddi gian to\\u00e0n t\\u00e1c v\\u1ee5 382\\u2013901 gi\\u00e2y cho th\\u1ea5y ch\\u01b0a \\u0111\\u1ea1t m\\u1ee5c ti\\u00eau 3\\u20135 ph\\u00fat \\u1edf c\\u00e1c l\\u01b0\\u1ee3t quan s\\u00e1t; c\\u1ea7n \\u0111o th\\u00eam v\\u1edbi c\\u00f9ng \\u0111i\\u1ec1u ki\\u1ec7n cache, quota v\\u00e0 m\\u1ea1ng tr\\u01b0\\u1edbc khi k\\u1ebft lu\\u1eadn v\\u1ec1 hi\\u1ec7u n\\u0103ng.\",\"start\":179900,\"end\":180078,\"quote_verified\":true,\"semantic_support\":\"NOT_VERIFIED\"}],\"verified\":true,\"relevance_verified\":false,\"semantic_support\":\"NOT_VERIFIED\"},{\"content\":\"Ghi nh\\u1eadn c\\u00e1c ch\\u1ee9c n\\u0103ng c\\u00f3 d\\u1eef li\\u1ec7u ki\\u1ec3m tra \\u0111\\u00e1p \\u1ee9ng mong \\u0111\\u1ee3i l\\u00e0 ho\\u00e0n th\\u00e0nh trong ph\\u1ea1m vi th\\u1eed nghi\\u1ec7m, \\u0111\\u00e3 th\\u1eed nghi\\u1ec7m c\\u00e1c quy tr\\u00ecnh \\u0111\\u0103ng t\\u1ea3i k\\u1ebf ho\\u1ea1ch, qu\\u1ea3n l\\u00fd \\u0111\\u1ec1 t\\u00e0i, theo d\\u00f5i ti\\u1ebfn \\u0111\\u1ed9 v\\u00e0 qu\\u1ea3n l\\u00fd b\\u1ea3o v\\u1ec7.\",\"kind\":\"reported_work\",\"source_ids\":[\"AI-025:0001\",\"AI-028:0002\"],\"source_pages\":[151,153],\"evidence\":\"Nh\\u1eefng ch\\u1ee9c n\\u0103ng c\\u00f3 d\\u1eef li\\u1ec7u ki\\u1ec3m \\ntra v\\u00e0 \\u0111\\u00e1p \\u1ee9ng k\\u1ebft qu\\u1ea3 mong \\u0111\\u1ee3i \\u0111\\u01b0\\u1ee3c ghi nh\\u1eadn l\\u00e0 ho\\u00e0n th\\u00e0nh trong ph\\u1ea1m vi th\\u1eed \\nnghi\\u1ec7m.\",\"source_references\":[{\"source_id\":\"AI-025:0001\",\"page\":151,\"end_page\":151,\"quote\":\"Nh\\u1eefng ch\\u1ee9c n\\u0103ng c\\u00f3 d\\u1eef li\\u1ec7u ki\\u1ec3m \\ntra v\\u00e0 \\u0111\\u00e1p \\u1ee9ng k\\u1ebft qu\\u1ea3 mong \\u0111\\u1ee3i \\u0111\\u01b0\\u1ee3c ghi nh\\u1eadn l\\u00e0 ho\\u00e0n th\\u00e0nh trong ph\\u1ea1m vi th\\u1eed \\nnghi\\u1ec7m.\",\"start\":180266,\"end\":180385,\"quote_verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"source_id\":\"AI-028:0002\",\"page\":153,\"end_page\":153,\"quote\":\"\\u0110\\u1ed1i v\\u1edbi c\\u00e1c ch\\u1ee9c n\\u0103ng qu\\u1ea3n l\\u00fd, ch\\u01b0\\u01a1ng tr\\u00ecnh b\\u00e0y c\\u00e1c tr\\u01b0\\u1eddng h\\u1ee3p th\\u1eed nghi\\u1ec7m thu\\u1ed9c quy tr\\u00ecnh \\u0111\\u0103ng t\\u1ea3i v\\u00e0 c\\u00f4ng b\\u1ed1 k\\u1ebf ho\\u1ea1ch kh\\u00f3a lu\\u1eadn, qu\\u1ea3n l\\u00fd v\\u00e0 \\u0111\\u0103ng k\\u00fd \\u0111\\u1ec1 t\\u00e0i, theo d\\u00f5i ti\\u1ebfn \\u0111\\u1ed9 v\\u00e0 qu\\u1ea3n l\\u00fd b\\u1ea3o v\\u1ec7.\",\"start\":182715,\"end\":182909,\"quote_verified\":true,\"semantic_support\":\"NOT_VERIFIED\"}],\"verified\":true,\"relevance_verified\":false,\"semantic_support\":\"NOT_VERIFIED\"},{\"content\":\"X\\u00e2y d\\u1ef1ng ch\\u1ee9c n\\u0103ng t\\u00f3m t\\u1eaft b\\u00e1o c\\u00e1o b\\u1eb1ng AI d\\u00f9ng PyMuPDF, Gemini API v\\u1edbi Map-Reduce, \\u0111\\u1ed1i chi\\u1ebfu cho th\\u1ea5y c\\u00f2n h\\u1ea1n ch\\u1ebf v\\u1ec1 m\\u1ee9c \\u0111\\u1ed9 bao qu\\u00e1t v\\u00e0 nh\\u1eadn di\\u1ec7n c\\u1ea5u tr\\u00fac; kh\\u1ea3o s\\u00e1t nghi\\u1ec7p v\\u1ee5, ph\\u00e2n t\\u00edch y\\u00eau c\\u1ea7u, thi\\u1ebft k\\u1ebf c\\u01a1 s\\u1edf d\\u1eef li\\u1ec7u v\\u00e0 x\\u00e2y d\\u1ef1ng ph\\u1ea7n m\\u1ec1m, ki\\u1ec3m th\\u1eed ghi nh\\u1eadn \\u0111\\u00e1p \\u1ee9ng ph\\u1ea7n l\\u1edbn y\\u00eau c\\u1ea7u ch\\u1ee9c n\\u0103ng.\",\"kind\":\"reported_work\",\"source_ids\":[\"AI-028:0003\",\"AI-028:0004\",\"AI-029:0001\",\"AI-029:0002\"],\"source_pages\":[153,154],\"evidence\":\"\\u0110\\u1ed1i v\\u1edbi ch\\u1ee9c n\\u0103ng t\\u00f3m t\\u1eaft b\\u00e1o c\\u00e1o b\\u1eb1ng AI, ch\\u01b0\\u01a1ng m\\u00f4 t\\u1ea3 quy tr\\u00ecnh tr\\u00edch xu\\u1ea5t v\\u0103n b\\u1ea3n t\\u1eeb PDF b\\u1eb1ng PyMuPDF, nh\\u1eadn di\\u1ec7n c\\u1ea5u tr\\u00fac ch\\u01b0\\u01a1ng\\/m\\u1ee5c, chia n\\u1ed9i dung th\\u00e0nh c\\u00e1c \\u0111o\\u1ea1n ph\\u00f9 h\\u1ee3p v\\u00e0 x\\u1eed l\\u00fd b\\u1eb1ng ph\\u01b0\\u01a1ng ph\\u00e1p Map\\u2013Reduce th\\u00f4ng qua Gemini API.\",\"source_references\":[{\"source_id\":\"AI-028:0003\",\"page\":153,\"end_page\":153,\"quote\":\"\\u0110\\u1ed1i v\\u1edbi ch\\u1ee9c n\\u0103ng t\\u00f3m t\\u1eaft b\\u00e1o c\\u00e1o b\\u1eb1ng AI, ch\\u01b0\\u01a1ng m\\u00f4 t\\u1ea3 quy tr\\u00ecnh tr\\u00edch xu\\u1ea5t v\\u0103n b\\u1ea3n t\\u1eeb PDF b\\u1eb1ng PyMuPDF, nh\\u1eadn di\\u1ec7n c\\u1ea5u tr\\u00fac ch\\u01b0\\u01a1ng\\/m\\u1ee5c, chia n\\u1ed9i dung th\\u00e0nh c\\u00e1c \\u0111o\\u1ea1n ph\\u00f9 h\\u1ee3p v\\u00e0 x\\u1eed l\\u00fd b\\u1eb1ng ph\\u01b0\\u01a1ng ph\\u00e1p Map\\u2013Reduce th\\u00f4ng qua Gemini API.\",\"start\":183186,\"end\":183421,\"quote_verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"source_id\":\"AI-028:0004\",\"page\":153,\"end_page\":153,\"quote\":\"Vi\\u1ec7c \\u0111\\u1ed1i chi\\u1ebfu m\\u1eabu t\\u00f3m t\\u1eaft v\\u1edbi t\\u00e0i li\\u1ec7u g\\u1ed1c cho th\\u1ea5y h\\u1ec7 th\\u1ed1ng c\\u00f3 th\\u1ec3 h\\u1ed7 tr\\u1ee3 n\\u1eafm b\\u1eaft n\\u1ed9i dung v\\u00e0 t\\u00ecm l\\u1ea1i ngu\\u1ed3n, nh\\u01b0ng v\\u1eabn c\\u00f2n h\\u1ea1n ch\\u1ebf v\\u1ec1 m\\u1ee9c \\u0111\\u1ed9 bao qu\\u00e1t, nh\\u1eadn di\\u1ec7n c\\u1ea5u tr\\u00fac v\\u00e0 ph\\u00e2n bi\\u1ec7t n\\u1ed9i dung \\u0111\\u00e3 th\\u1ef1c hi\\u1ec7n v\\u1edbi ph\\u1ea7n \\u0111\\u1ec1 c\\u01b0\\u01a1ng ho\\u1eb7c h\\u01b0\\u1edbng d\\u1eabn.\",\"start\":183627,\"end\":183870,\"quote_verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"source_id\":\"AI-029:0001\",\"page\":154,\"end_page\":154,\"quote\":\"\\u0110\\u1ec1 t\\u00e0i \\u0111\\u00e3 th\\u1ef1c hi\\u1ec7n kh\\u1ea3o s\\u00e1t nghi\\u1ec7p v\\u1ee5, ph\\u00e2n t\\u00edch y\\u00eau c\\u1ea7u, thi\\u1ebft \\nk\\u1ebf c\\u01a1 s\\u1edf d\\u1eef li\\u1ec7u v\\u00e0 x\\u00e2y d\\u1ef1ng ph\\u1ea7n m\\u1ec1m qu\\u1ea3n l\\u00fd c\\u00f4ng t\\u00e1c kh\\u00f3a lu\\u1eadn t\\u1ed1t nghi\\u1ec7p.\",\"start\":184334,\"end\":184476,\"quote_verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"source_id\":\"AI-029:0002\",\"page\":154,\"end_page\":154,\"quote\":\"So v\\u1edbi m\\u1ee5c ti\\u00eau ban \\u0111\\u1ea7u, ph\\u1ea7n m\\u1ec1m \\u0111\\u00e3 \\u0111\\u00e1p \\u1ee9ng ph\\u1ea7n l\\u1edbn c\\u00e1c \\nnh\\u00f3m y\\u00eau c\\u1ea7u ch\\u1ee9c n\\u0103ng ph\\u1ee5c v\\u1ee5 quy tr\\u00ecnh qu\\u1ea3n l\\u00fd kh\\u00f3a lu\\u1eadn.\",\"start\":184957,\"end\":185075,\"quote_verified\":true,\"semantic_support\":\"NOT_VERIFIED\"}],\"verified\":true,\"relevance_verified\":false,\"semantic_support\":\"NOT_VERIFIED\"}],\"citations\":[{\"page\":19,\"snippet\":\"Trong b\\u1ed1i c\\u1ea3nh chuy\\u1ec3n \\u0111\\u1ed5i s\\u1ed1 ng\\u00e0y c\\u00e0ng \\u0111\\u01b0\\u1ee3c ch\\u00fa tr\\u1ecdng trong l\\u0129nh v\\u1ef1c gi\\u00e1o d\\u1ee5c \\u0111\\u1ea1i h\\u1ecdc, vi\\u1ec7c \\u1ee9ng d\\u1ee5ng c\\u00f4ng ngh\\u1ec7 th\\u00f4ng tin v\\u00e0o c\\u00f4ng t\\u00e1c qu\\u1ea3n l\\u00fd \\u0111\\u00f3ng vai tr\\u00f2 quan tr\\u1ecdng trong vi\\u1ec7c n\\u00e2ng cao hi\\u1ec7u qu\\u1ea3 v\\u1eadn h\\u00e0nh v\\u00e0 ch\\u1ea5t l\\u01b0\\u1ee3ng \\u0111\\u00e0o t\\u1ea1o.\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":19,\"snippet\":\"Tuy nhi\\u00ean, tr\\u00ean th\\u1ef1c t\\u1ebf, vi\\u1ec7c qu\\u1ea3n l\\u00fd kh\\u00f3a lu\\u1eadn t\\u1ed1t nghi\\u1ec7p c\\u00f3 th\\u1ec3 li\\u00ean quan \\u0111\\u1ebfn nhi\\u1ec1u c\\u00f4ng c\\u1ee5 v\\u00e0 ph\\u01b0\\u01a1ng th\\u1ee9c l\\u00e0m vi\\u1ec7c kh\\u00e1c nhau.\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":19,\"snippet\":\"Xu\\u1ea5t ph\\u00e1t t\\u1eeb nh\\u1eefng y\\u00eau c\\u1ea7u th\\u1ef1c ti\\u1ec5n \\u0111\\u00f3, nh\\u00f3m l\\u1ef1a ch\\u1ecdn \\u0111\\u1ec1 t\\u00e0i \\u201cX\\u00e2y d\\u1ef1ng h\\u1ec7 th\\u1ed1ng qu\\u1ea3n l\\u00fd c\\u00f4ng t\\u00e1c kh\\u00f3a lu\\u1eadn t\\u1ed1t nghi\\u1ec7p t\\u1ea1i Tr\\u01b0\\u1eddng \\u0110\\u1ea1i h\\u1ecdc C\\u00f4ng Th\\u01b0\\u01a1ng Th\\u00e0nh ph\\u1ed1 H\\u1ed3 Ch\\u00ed Minh\\u201d.\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":21,\"snippet\":\"C\\u00e1c \\u0111\\u1ed1i t\\u01b0\\u1ee3ng s\\u1eed d\\u1ee5ng ch\\u00ednh c\\u1ee7a h\\u1ec7 th\\u1ed1ng bao g\\u1ed3m: \\n\\u2022 \\nGi\\u00e1o v\\u1ee5 \\n\\u2022 \\nGi\\u1ea3ng vi\\u00ean \\n\\u2022 \\nSinh vi\\u00ean \\n\\u2022 \\nTr\\u01b0\\u1edfng b\\u00f4 m\\u00f4n \\n\\u2022 \\nTr\\u01b0\\u1edfng khoa\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":24,\"snippet\":\"\\u0110\\u1ed1i t\\u01b0\\u1ee3ng nghi\\u00ean c\\u1ee9u: Quy tr\\u00ecnh nghi\\u1ec7p v\\u1ee5 qu\\u1ea3n l\\u00fd c\\u00f4ng t\\u00e1c kh\\u00f3a lu\\u1eadn t\\u1ed1t nghi\\u1ec7p t\\u1ea1i Khoa C\\u00f4ng ngh\\u1ec7 Th\\u00f4ng tin, Tr\\u01b0\\u1eddng \\u0110\\u1ea1i h\\u1ecdc C\\u00f4ng Th\\u01b0\\u01a1ng Th\\u00e0nh ph\\u1ed1 H\\u1ed3 Ch\\u00ed Minh v\\u00e0 c\\u00e1c c\\u00f4ng ngh\\u1ec7, n\\u1ec1n t\\u1ea3ng \\u0111\\u01b0\\u1ee3c \\u1ee9ng d\\u1ee5ng trong vi\\u1ec7c ph\\u00e2n t\\u00edch, thi\\u1ebft k\\u1ebf v\\u00e0 x\\u00e2y d\\u1ef1ng h\\u1ec7 th\\u1ed1ng website qu\\u1ea3n l\\u00fd kh\\u00f3a lu\\u1eadn t\\u1ed1t nghi\\u1ec7p.\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":24,\"snippet\":\"C\\u00e1c m\\u1ee5c ti\\u00eau c\\u1ee5 th\\u1ec3 c\\u1ee7a \\u0111\\u1ec1 t\\u00e0i bao g\\u1ed3m: \\n\\u2022 \\nNghi\\u00ean c\\u1ee9u c\\u01a1 s\\u1edf l\\u00fd thuy\\u1ebft v\\u00e0 c\\u00f4ng ngh\\u1ec7: T\\u00ecm hi\\u1ec3u quy tr\\u00ecnh nghi\\u1ec7p v\\u1ee5 qu\\u1ea3n l\\u00fd kh\\u00f3a lu\\u1eadn t\\u1ed1t nghi\\u1ec7p, c\\u00e1c ph\\u01b0\\u01a1ng ph\\u00e1p ph\\u00e2n t\\u00edch v\\u00e0 thi\\u1ebft k\\u1ebf h\\u1ec7 th\\u1ed1ng th\\u00f4ng tin, \\u0111\\u1ed3ng th\\u1eddi nghi\\u00ean c\\u1ee9u c\\u00e1c c\\u00f4ng ngh\\u1ec7 s\\u1eed d\\u1ee5ng trong qu\\u00e1 tr\\u00ecnh x\\u00e2y d\\u1ef1ng \\u1ee9ng d\\u1ee5ng web.\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":25,\"snippet\":\"\\u0110\\u1ec1 t\\u00e0i \\u0111\\u01b0\\u1ee3c th\\u1ef1c hi\\u1ec7n trong ph\\u1ea1m vi Khoa C\\u00f4ng ngh\\u1ec7 Th\\u00f4ng tin - Tr\\u01b0\\u1eddng \\n\\u0110\\u1ea1i h\\u1ecdc C\\u00f4ng Th\\u01b0\\u01a1ng Th\\u00e0nh ph\\u1ed1 H\\u1ed3 Ch\\u00ed Minh v\\u00e0 ch\\u1ec9 ph\\u1ee5c v\\u1ee5 c\\u00f4ng t\\u00e1c qu\\u1ea3n l\\u00fd \\nkh\\u00f3a lu\\u1eadn t\\u1ed1t nghi\\u1ec7p c\\u1ee7a khoa.\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":26,\"snippet\":\"H\\u1ec7 th\\u1ed1ng \\u0111\\u01b0\\u1ee3c \\u0111\\u1ecbnh h\\u01b0\\u1edbng \\u00e1p d\\u1ee5ng t\\u1ea1i Khoa C\\u00f4ng ngh\\u1ec7 Th\\u00f4ng tin, \\nTr\\u01b0\\u1eddng \\u0110\\u1ea1i h\\u1ecdc C\\u00f4ng Th\\u01b0\\u01a1ng Th\\u00e0nh ph\\u1ed1 H\\u1ed3 Ch\\u00ed Minh, ph\\u1ee5c v\\u1ee5 c\\u00f4ng \\nt\\u00e1c qu\\u1ea3n l\\u00fd v\\u00e0 th\\u1ef1c hi\\u1ec7n kh\\u00f3a lu\\u1eadn t\\u1ed1t nghi\\u1ec7p. C\\u00e1c nh\\u00f3m ng\\u01b0\\u1eddi d\\u00f9ng bao \\ng\\u1ed3m Gi\\u00e1o v\\u1ee5, Tr\\u01b0\\u1edfng khoa, Tr\\u01b0\\u1edfng b\\u1ed9 m\\u00f4n, Gi\\u1ea3ng vi\\u00ean v\\u00e0 Sinh vi\\u00ean.\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":26,\"snippet\":\"H\\u1ec7 th\\u1ed1ng \\u0111\\u01b0\\u1ee3c ph\\u00e1t tri\\u1ec3n d\\u01b0\\u1edbi d\\u1ea1ng \\u1ee9ng d\\u1ee5ng web, s\\u1eed d\\u1ee5ng Laravel \\nl\\u00e0m n\\u1ec1n t\\u1ea3ng ph\\u00e1t tri\\u1ec3n ph\\u00eda m\\u00e1y ch\\u1ee7, PHP \\u0111\\u1ec3 x\\u1eed l\\u00fd nghi\\u1ec7p v\\u1ee5 v\\u00e0 \\nMySQL\\/MariaDB \\u0111\\u1ec3 qu\\u1ea3n l\\u00fd d\\u1eef li\\u1ec7u.\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":26,\"snippet\":\"\\u2013 \\nGi\\u1edbi h\\u1ea1n v\\u1ec1 ph\\u1ea1m vi tri\\u1ec3n khai: H\\u1ec7 th\\u1ed1ng \\u0111\\u01b0\\u1ee3c x\\u00e2y d\\u1ef1ng \\nph\\u1ee5c v\\u1ee5 c\\u00f4ng t\\u00e1c qu\\u1ea3n l\\u00fd kh\\u00f3a lu\\u1eadn t\\u1ed1t nghi\\u1ec7p t\\u1ea1i Khoa \\nC\\u00f4ng ngh\\u1ec7 Th\\u00f4ng tin, ch\\u01b0a m\\u1edf r\\u1ed9ng tri\\u1ec3n khai cho c\\u00e1c \\nkhoa kh\\u00e1c trong tr\\u01b0\\u1eddng.\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":28,\"snippet\":\"H\\u1ec7 th\\u1ed1ng qu\\u1ea3n l\\u00fd c\\u00f4ng t\\u00e1c kh\\u00f3a lu\\u1eadn t\\u1ed1t nghi\\u1ec7p \\u0111\\u01b0\\u1ee3c tri\\u1ec3n khai t\\u1ea1i Khoa C\\u00f4ng \\nngh\\u1ec7 Th\\u00f4ng tin - Tr\\u01b0\\u1eddng \\u0110\\u1ea1i h\\u1ecdc C\\u00f4ng Th\\u01b0\\u01a1ng Th\\u00e0nh ph\\u1ed1 H\\u1ed3 Ch\\u00ed Minh, v\\u1edbi ba \\nnh\\u00f3m ng\\u01b0\\u1eddi d\\u00f9ng ch\\u00ednh: \\n\\u2022 \\nGi\\u00e1o v\\u1ee5: Qu\\u1ea3n l\\u00fd k\\u1ebf ho\\u1ea1ch kh\\u00f3a lu\\u1eadn, \\u0111\\u1ec1 t\\u00e0i, ph\\u00e2n c\\u00f4ng gi\\u1ea3ng vi\\u00ean \\nh\\u01b0\\u1edbng d\\u1eabn, th\\u00e0nh l\\u1eadp h\\u1ed9i \\u0111\\u1ed3ng b\\u1ea3o v\\u1ec7, qu\\u1ea3n l\\u00fd k\\u1ebft qu\\u1ea3 v\\u00e0 th\\u1ed1ng k\\u00ea b\\u00e1o \\nc\\u00e1o. \\n\\u2022 \\nGi\\u1ea3ng vi\\u00ean: \\u0110\\u1ec1 xu\\u1ea5t v\\u00e0 h\\u01b0\\u1edbng d\\u1eabn \\u0111\\u1ec1 t\\u00e0i, theo d\\u00f5i ti\\u1ebfn \\u0111\\u1ed9 th\\u1ef1c hi\\u1ec7n, \\n\\u0111\\u00e1nh gi\\u00e1 kh\\u00f3a lu\\u1eadn v\\u00e0 tham gia h\\u1ed9i \\u0111\\u1ed3ng b\\u1ea3o v\\u1ec7. \\n\\u2022 \\nSinh vi\\u00ean: \\u0110\\u0103ng k\\u00fd \\u0111\\u1ec1 t\\u00e0i, th\\u1ef1c hi\\u1ec7n kh\\u00f3a lu\\u1eadn, n\\u1ed9p b\\u00e1o c\\u00e1o v\\u00e0 h\\u1ed3 s\\u01a1 \\nb\\u1ea3o v\\u1ec7, \\u0111\\u1ed3ng th\\u1eddi theo d\\u00f5i k\\u1ebft qu\\u1ea3  tr\\u00ean h\\u1ec7 th\\u1ed1ng.\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":28,\"snippet\":\"\\u2022 \\nTr\\u01b0\\u1edfng b\\u1ed9 m\\u00f4n: Qu\\u1ea3n l\\u00fd danh s\\u00e1ch \\u0111\\u1ec1 t\\u00e0i theo gi\\u1ea3ng vi\\u00ean thu\\u1ed9c b\\u1ed9 m\\u00f4n, \\nxem x\\u00e9t v\\u00e0 ph\\u00ea duy\\u1ec7t \\u0111\\u1ec1 xu\\u1ea5t \\u0111\\u1ec1 t\\u00e0i theo ph\\u1ea1m vi \\u0111\\u01b0\\u1ee3c ph\\u00e2n quy\\u1ec1n, \\n\\u0111\\u1ed3ng th\\u1eddi theo d\\u00f5i t\\u00ecnh h\\u00ecnh h\\u01b0\\u1edbng d\\u1eabn kh\\u00f3a lu\\u1eadn c\\u1ee7a gi\\u1ea3ng vi\\u00ean thu\\u1ed9c \\nb\\u1ed9 m\\u00f4n. \\n\\u2022 \\nTr\\u01b0\\u1edfng khoa: Qu\\u1ea3n l\\u00fd v\\u00e0 theo d\\u00f5i c\\u00f4ng t\\u00e1c kh\\u00f3a lu\\u1eadn \\u1edf ph\\u1ea1m vi to\\u00e0n \\nkhoa, gi\\u00e1m s\\u00e1t t\\u00ecnh h\\u00ecnh \\u0111\\u1ec1 t\\u00e0i theo c\\u00e1c b\\u1ed9 m\\u00f4n, theo d\\u00f5i vi\\u1ec7c ph\\u00e2n c\\u00f4ng \\ngi\\u1ea3ng vi\\u00ean h\\u01b0\\u1edbng d\\u1eabn v\\u00e0 xem x\\u00e9t c\\u00e1c v\\u1ea5n \\u0111\\u1ec1 thu\\u1ed9c th\\u1ea9m quy\\u1ec1n qu\\u1ea3n l\\u00fd.\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":28,\"snippet\":\"H\\u1ec7 th\\u1ed1ng qu\\u1ea3n l\\u00fd c\\u00f4ng t\\u00e1c kh\\u00f3a lu\\u1eadn t\\u1ed1t nghi\\u1ec7p bao g\\u1ed3m 08 quy tr\\u00ecnh nghi\\u1ec7p \\nv\\u1ee5 ch\\u00ednh. C\\u00e1c quy tr\\u00ecnh n\\u00e0y \\u0111\\u01b0\\u1ee3c m\\u00f4 t\\u1ea3 chi ti\\u1ebft nh\\u01b0 sau:\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":28,\"snippet\":\"Quy tr\\u00ecnh n\\u00e0y b\\u1eaft \\u0111\\u1ea7u khi Gi\\u00e1o v\\u1ee5 ti\\u1ebfn h\\u00e0nh x\\u00e2y d\\u1ef1ng k\\u1ebf ho\\u1ea1ch tri\\u1ec3n khai \\nkh\\u00f3a lu\\u1eadn cho m\\u1ed9t h\\u1ecdc k\\u1ef3 m\\u1edbi. K\\u1ebf ho\\u1ea1ch bao g\\u1ed3m c\\u00e1c th\\u00f4ng tin nh\\u01b0 h\\u1ecdc k\\u1ef3, t\\u00ean \\nk\\u1ebf ho\\u1ea1ch, th\\u1eddi gian b\\u1eaft \\u0111\\u1ea7u v\\u00e0 k\\u1ebft th\\u00fac, c\\u00e1c m\\u1ed1c th\\u1eddi gian quan tr\\u1ecdng, quy \\u0111\\u1ecbnh \\nth\\u1ef1c hi\\u1ec7n v\\u00e0 bi\\u1ec3u m\\u1eabu s\\u1eed d\\u1ee5ng. Sau khi \\u0111\\u01b0\\u1ee3c Ban Ch\\u1ee7 nhi\\u1ec7m Khoa ph\\u00ea duy\\u1ec7t, k\\u1ebf \\nho\\u1ea1ch s\\u1ebd \\u0111\\u01b0\\u1ee3c c\\u00f4ng b\\u1ed1 \\u0111\\u1ec3 gi\\u1ea3ng vi\\u00ean v\\u00e0 sinh vi\\u00ean th\\u1ef1c hi\\u1ec7n theo \\u0111\\u00fang ti\\u1ebfn \\u0111\\u1ed9.\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":29,\"snippet\":\"Gi\\u00e1o v\\u1ee5 r\\u00e0 so\\u00e1t d\\u1eef li\\u1ec7u sinh vi\\u00ean d\\u1ef1a tr\\u00ean c\\u00e1c ti\\u00eau ch\\u00ed nh\\u01b0 s\\u1ed1 t\\u00edn ch\\u1ec9 t\\u00edch l\\u0169y, \\n\\u0111i\\u1ec3m trung b\\u00ecnh (GPA) v\\u00e0 t\\u00ecnh tr\\u1ea1ng h\\u1ecdc t\\u1eadp. Danh s\\u00e1ch sinh vi\\u00ean \\u0111\\u1ee7 \\u0111i\\u1ec1u ki\\u1ec7n \\n\\u0111\\u01b0\\u1ee3c c\\u00f4ng b\\u1ed1 ch\\u00ednh th\\u1ee9c tr\\u00ean h\\u1ec7 th\\u1ed1ng, gi\\u00fap minh b\\u1ea1ch h\\u00f3a th\\u00f4ng tin v\\u00e0 \\u0111\\u1ea3m b\\u1ea3o \\nch\\u1ec9 nh\\u1eefng sinh vi\\u00ean \\u0111\\u00e1p \\u1ee9ng y\\u00eau c\\u1ea7u m\\u1edbi \\u0111\\u01b0\\u1ee3c tham gia kh\\u00f3a lu\\u1eadn. \\u0110\\u1ed3ng th\\u1eddi, \\nGi\\u00e1o v\\u1ee5 x\\u00e1c \\u0111\\u1ecbnh ch\\u1ec9 ti\\u00eau h\\u01b0\\u1edbng d\\u1eabn c\\u1ee7a t\\u1eebng gi\\u1ea3ng vi\\u00ean \\u0111\\u1ec3 \\u0111\\u1ea3m b\\u1ea3o vi\\u1ec7c ph\\u00e2n \\nc\\u00f4ng h\\u1ee3p l\\u00fd, tr\\u00e1nh t\\u00ecnh tr\\u1ea1ng qu\\u00e1 t\\u1ea3i ho\\u1eb7c thi\\u1ebfu c\\u00e2n \\u0111\\u1ed1i trong c\\u00f4ng t\\u00e1c h\\u01b0\\u1edbng d\\u1eabn.\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":30,\"snippet\":\"Gi\\u1ea3ng vi\\u00ean \\u0111\\u1ec1 xu\\u1ea5t c\\u00e1c \\u0111\\u1ec1 t\\u00e0i kh\\u00f3a lu\\u1eadn thu\\u1ed9c l\\u0129nh v\\u1ef1c chuy\\u00ean m\\u00f4n c\\u1ee7a m\\u00ecnh. \\nM\\u1ed7i \\u0111\\u1ec1 t\\u00e0i c\\u00f3 th\\u00f4ng tin chi ti\\u1ebft g\\u1ed3m m\\u00e3 \\u0111\\u1ec1 t\\u00e0i, t\\u00ean \\u0111\\u1ec1 t\\u00e0i, l\\u0129nh v\\u1ef1c nghi\\u00ean c\\u1ee9u, m\\u00f4 \\nt\\u1ea3, y\\u00eau c\\u1ea7u, s\\u1ed1 l\\u01b0\\u1ee3ng sinh vi\\u00ean t\\u1ed1i \\u0111a v\\u00e0 tr\\u1ea1ng th\\u00e1i x\\u00e9t duy\\u1ec7t. Gi\\u00e1o v\\u1ee5 ti\\u1ebfp nh\\u1eadn, \\nki\\u1ec3m tra t\\u00ednh h\\u1ee3p l\\u1ec7 v\\u00e0 tr\\u00ecnh l\\u00e3nh \\u0111\\u1ea1o khoa ph\\u00ea duy\\u1ec7t tr\\u01b0\\u1edbc khi c\\u00f4ng b\\u1ed1 cho sinh \\nvi\\u00ean \\u0111\\u0103ng k\\u00fd.\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":30,\"snippet\":\"Sinh vi\\u00ean c\\u0103n c\\u1ee9 v\\u00e0o danh s\\u00e1ch \\u0111\\u1ec1 t\\u00e0i \\u0111\\u00e3 c\\u00f4ng b\\u1ed1 \\u0111\\u1ec3 \\u0111\\u0103ng k\\u00fd c\\u00e1 nh\\u00e2n ho\\u1eb7c \\ntheo nh\\u00f3m. Th\\u00f4ng tin \\u0111\\u0103ng k\\u00fd bao g\\u1ed3m m\\u00e3 nh\\u00f3m, tr\\u01b0\\u1edfng nh\\u00f3m, danh s\\u00e1ch th\\u00e0nh \\nvi\\u00ean, \\u0111\\u1ec1 t\\u00e0i \\u0111\\u0103ng k\\u00fd, gi\\u1ea3ng vi\\u00ean h\\u01b0\\u1edbng d\\u1eabn v\\u00e0 ng\\u00e0y \\u0111\\u0103ng k\\u00fd. Gi\\u00e1o v\\u1ee5 ki\\u1ec3m tra \\u0111i\\u1ec1u \\nki\\u1ec7n \\u0111\\u0103ng k\\u00fd, s\\u1ed1 l\\u01b0\\u1ee3ng th\\u00e0nh vi\\u00ean v\\u00e0 ch\\u1ec9 ti\\u00eau h\\u01b0\\u1edbng d\\u1eabn tr\\u01b0\\u1edbc khi ph\\u00ea duy\\u1ec7t ch\\u00ednh \\nth\\u1ee9c.\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":31,\"snippet\":\"Trong qu\\u00e1 tr\\u00ecnh th\\u1ef1c hi\\u1ec7n, sinh vi\\u00ean ph\\u1ea3i n\\u1ed9p b\\u00e1o c\\u00e1o ti\\u1ebfn \\u0111\\u1ed9 theo c\\u00e1c m\\u1ed1c \\nth\\u1eddi gian quy \\u0111\\u1ecbnh. B\\u00e1o c\\u00e1o g\\u1ed3m n\\u1ed9i dung th\\u1ef1c hi\\u1ec7n, t\\u1ec7p \\u0111\\u00ednh k\\u00e8m, th\\u1eddi gian n\\u1ed9p \\nv\\u00e0 nh\\u1eadn x\\u00e9t c\\u1ee7a gi\\u1ea3ng vi\\u00ean. Gi\\u1ea3ng vi\\u00ean theo d\\u00f5i ti\\u1ebfn \\u0111\\u1ed9, \\u0111\\u01b0a ra nh\\u1eadn x\\u00e9t, \\u0111\\u00e1nh gi\\u00e1 \\nv\\u00e0 y\\u00eau c\\u1ea7u ch\\u1ec9nh s\\u1eeda \\u0111\\u1ec3 \\u0111\\u1ea3m b\\u1ea3o kh\\u00f3a lu\\u1eadn \\u0111i \\u0111\\u00fang k\\u1ebf ho\\u1ea1ch.\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":32,\"snippet\":\"Khi ho\\u00e0n th\\u00e0nh, sinh vi\\u00ean n\\u1ed9p h\\u1ed3 s\\u01a1 b\\u1ea3o v\\u1ec7 g\\u1ed3m b\\u00e1o c\\u00e1o kh\\u00f3a lu\\u1eadn, t\\u00e0i li\\u1ec7u \\nminh ch\\u1ee9ng v\\u00e0 x\\u00e1c nh\\u1eadn c\\u1ee7a gi\\u1ea3ng vi\\u00ean h\\u01b0\\u1edbng d\\u1eabn. Gi\\u1ea3ng vi\\u00ean ki\\u1ec3m tra t\\u00ednh \\u0111\\u1ea7y \\n\\u0111\\u1ee7 c\\u1ee7a h\\u1ed3 s\\u01a1 v\\u00e0 gi\\u00e1o v\\u1ee5 ph\\u00e2n c\\u00f4ng gi\\u1ea3ng vi\\u00ean ph\\u1ea3n bi\\u1ec7n, th\\u00e0nh l\\u1eadp h\\u1ed9i \\u0111\\u1ed3ng b\\u1ea3o \\nv\\u1ec7 v\\u00e0 x\\u00e2y d\\u1ef1ng l\\u1ecbch b\\u1ea3o v\\u1ec7 cho t\\u1eebng nh\\u00f3m sinh vi\\u00ean.\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":32,\"snippet\":\"Quy tr\\u00ecnh t\\u1ed5 ch\\u1ee9c b\\u1ea3o v\\u1ec7 kh\\u00f3a lu\\u1eadn b\\u1eaft \\u0111\\u1ea7u khi Gi\\u00e1o v\\u1ee5 l\\u1eadp danh s\\u00e1ch sinh vi\\u00ean \\n\\u0111\\u1ee7 \\u0111i\\u1ec1u ki\\u1ec7n b\\u1ea3o v\\u1ec7 v\\u00e0 th\\u1ef1c hi\\u1ec7n ph\\u00e2n c\\u00f4ng Gi\\u1ea3ng vi\\u00ean ph\\u1ea3n bi\\u1ec7n. Sau khi c\\u00f3 k\\u1ebft \\nqu\\u1ea3 ph\\u1ea3n bi\\u1ec7n, Gi\\u00e1o v\\u1ee5 t\\u1ed5ng h\\u1ee3p v\\u00e0 x\\u00e1c \\u0111\\u1ecbnh danh s\\u00e1ch sinh vi\\u00ean \\u0111\\u01b0\\u1ee3c ph\\u00e9p b\\u1ea3o \\nv\\u1ec7.\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":36,\"snippet\":\"Sau khi k\\u1ebft th\\u00fac \\u0111\\u1ee3t b\\u1ea3o v\\u1ec7, to\\u00e0n b\\u1ed9 d\\u1eef li\\u1ec7u v\\u1ec1 k\\u1ebf ho\\u1ea1ch, sinh vi\\u00ean, gi\\u1ea3ng \\nvi\\u00ean, \\u0111\\u1ec1 t\\u00e0i, nh\\u00f3m th\\u1ef1c hi\\u1ec7n, b\\u00e1o c\\u00e1o ti\\u1ebfn \\u0111\\u1ed9, h\\u1ed3 s\\u01a1 b\\u1ea3o v\\u1ec7, h\\u1ed9i \\u0111\\u1ed3ng v\\u00e0 k\\u1ebft qu\\u1ea3 \\n\\u0111\\u01b0\\u1ee3c l\\u01b0u tr\\u1eef trong h\\u1ec7 th\\u1ed1ng. C\\u00e1c d\\u1eef li\\u1ec7u n\\u00e0y ph\\u1ee5c v\\u1ee5 cho vi\\u1ec7c tra c\\u1ee9u, th\\u1ed1ng k\\u00ea, \\nl\\u1eadp b\\u00e1o c\\u00e1o v\\u00e0 h\\u1ed7 tr\\u1ee3 x\\u00e2y d\\u1ef1ng k\\u1ebf ho\\u1ea1ch cho c\\u00e1c h\\u1ecdc k\\u1ef3 ti\\u1ebfp theo.\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":36,\"snippet\":\"\\u0110\\u1ec1 t\\u00e0i \\u0111\\u01b0\\u1ee3c tr\\u00ecnh b\\u00e0y theo c\\u1ea5u tr\\u00fac g\\u1ed3m ph\\u1ea7n M\\u1edf \\u0111\\u1ea7u v\\u00e0 6 ch\\u01b0\\u01a1ng ch\\u00ednh, c\\u1ee5 \\nth\\u1ec3 nh\\u01b0 sau: \\nCh\\u01b0\\u01a1ng 1 \\u2013 Kh\\u1ea3o s\\u00e1t h\\u1ec7 th\\u1ed1ng: Kh\\u1ea3o s\\u00e1t v\\u00e0 ph\\u00e2n t\\u00edch th\\u1ef1c tr\\u1ea1ng c\\u00f4ng t\\u00e1c \\nqu\\u1ea3n l\\u00fd kh\\u00f3a lu\\u1eadn t\\u1ea1i Khoa C\\u00f4ng ngh\\u1ec7 Th\\u00f4ng tin, x\\u00e1c \\u0111\\u1ecbnh c\\u00e1c \\u0111\\u1ed1i t\\u01b0\\u1ee3ng tham gia, \\nquy tr\\u00ecnh nghi\\u1ec7p v\\u1ee5 hi\\u1ec7n t\\u1ea1i, \\u0111\\u1ed3ng th\\u1eddi \\u0111\\u00e1nh gi\\u00e1 nh\\u1eefng h\\u1ea1n ch\\u1ebf c\\u1ee7a ph\\u01b0\\u01a1ng ph\\u00e1p \\nqu\\u1ea3n l\\u00fd hi\\u1ec7n c\\u00f3.\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":36,\"snippet\":\"Ch\\u01b0\\u01a1ng 1 \\u0111\\u00e3 tr\\u00ecnh b\\u00e0y t\\u1ed5ng quan v\\u1ec1 \\u0111\\u1ec1 t\\u00e0i \\\"X\\u00e2y d\\u1ef1ng h\\u1ec7 th\\u1ed1ng qu\\u1ea3n l\\u00fd c\\u00f4ng t\\u00e1c kh\\u00f3a lu\\u1eadn t\\u1ed1t nghi\\u1ec7p t\\u1ea1i Tr\\u01b0\\u1eddng \\u0110\\u1ea1i h\\u1ecdc C\\u00f4ng Th\\u01b0\\u01a1ng Th\\u00e0nh ph\\u1ed1 H\\u1ed3 Ch\\u00ed Minh\\\", bao g\\u1ed3m l\\u00fd do l\\u1ef1a ch\\u1ecdn \\u0111\\u1ec1 t\\u00e0i, gi\\u1edbi thi\\u1ec7u h\\u1ec7 th\\u1ed1ng, m\\u1ee5c ti\\u00eau v\\u00e0 ph\\u1ea1m vi nghi\\u00ean c\\u1ee9u.\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":37,\"snippet\":\"Th\\u00f4ng qua qu\\u00e1 tr\\u00ecnh kh\\u1ea3o s\\u00e1t, c\\u00f3 th\\u1ec3 th\\u1ea5y vi\\u1ec7c \\u1ee9ng d\\u1ee5ng m\\u1ed9t h\\u1ec7 th\\u1ed1ng qu\\u1ea3n l\\u00fd t\\u1eadp trung s\\u1ebd g\\u00f3p ph\\u1ea7n n\\u00e2ng cao hi\\u1ec7u qu\\u1ea3 qu\\u1ea3n l\\u00fd, gi\\u1ea3m thi\\u1ec3u c\\u00e1c thao t\\u00e1c th\\u1ee7 c\\u00f4ng, t\\u0103ng t\\u00ednh ch\\u00ednh x\\u00e1c, minh b\\u1ea1ch v\\u00e0 h\\u1ed7 tr\\u1ee3 chuy\\u1ec3n \\u0111\\u1ed5i s\\u1ed1 trong c\\u00f4ng t\\u00e1c qu\\u1ea3n l\\u00fd kh\\u00f3a lu\\u1eadn t\\u1ed1t nghi\\u1ec7p.\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":38,\"snippet\":\"M\\u00f4 h\\u00ecnh Client - Server (Kh\\u00e1ch - Ch\\u1ee7) \\u0111\\u00f3ng vai tr\\u00f2 n\\u1ec1n t\\u1ea3ng trong thi\\u1ebft k\\u1ebf m\\u1ea1ng ph\\u00e2n t\\u00e1n hi\\u1ec7n \\u0111\\u1ea1i.\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":38,\"snippet\":\"Nguy\\u00ean l\\u00fd ho\\u1ea1t \\u0111\\u1ed9ng c\\u1ee7a m\\u00f4 h\\u00ecnh Client\\u2013Server \\u0111\\u01b0\\u1ee3c th\\u1ef1c hi\\u1ec7n theo c\\u01a1 ch\\u1ebf y\\u00eau c\\u1ea7u v\\u00e0 ph\\u1ea3n h\\u1ed3i.\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":39,\"snippet\":\"X\\u1eed l\\u00fd nghi\\u1ec7p v\\u1ee5 qu\\u1ea3n l\\u00fd kh\\u00f3a lu\\u1eadn, x\\u00e1c th\\u1ef1c ng\\u01b0\\u1eddi d\\u00f9ng, k\\u1ebft n\\u1ed1i v\\u00e0 thao t\\u00e1c v\\u1edbi c\\u01a1 s\\u1edf d\\u1eef li\\u1ec7u MySQL, \\u0111\\u1ed3ng th\\u1eddi t\\u00edch h\\u1ee3p d\\u1ecbch h\\u1ec7 th\\u1ed1ng AI.\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":40,\"snippet\":\"Ch\\u1ee9c n\\u0103ng ch\\u00ednh c\\u1ee7a MVC l\\u00e0 ph\\u00e2n t\\u00e1ch r\\u00f5 r\\u00e0ng gi\\u1eefa giao di\\u1ec7n ng\\u01b0\\u1eddi d\\u00f9ng (Front-end) v\\u00e0 logic nghi\\u1ec7p v\\u1ee5, qu\\u1ea3n l\\u00fd d\\u1eef li\\u1ec7u (Back-end) th\\u00e0nh ba th\\u00e0nh ph\\u1ea7n \\u0111\\u1ed9c l\\u1eadp:\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":40,\"snippet\":\"Quy tr\\u00ecnh giao ti\\u1ebfp gi\\u1eefa Client v\\u00e0 Server \\u0111\\u01b0\\u1ee3c th\\u1ef1c hi\\u1ec7n th\\u00f4ng qua c\\u01a1 ch\\u1ebf Request \\u2013 Response.\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":41,\"snippet\":\"Trong \\u0111\\u1ec1 t\\u00e0i, MySQL \\u0111\\u01b0\\u1ee3c s\\u1eed d\\u1ee5ng \\u0111\\u1ec3 l\\u01b0u tr\\u1eef v\\u00e0 qu\\u1ea3n l\\u00fd c\\u00e1c d\\u1eef li\\u1ec7u li\\u00ean quan \\u0111\\u1ebfn h\\u1ec7 th\\u1ed1ng qu\\u1ea3n l\\u00fd kh\\u00f3a lu\\u1eadn, bao g\\u1ed3m th\\u00f4ng tin sinh vi\\u00ean, gi\\u1ea3ng vi\\u00ean, \\u0111\\u1ec1 t\\u00e0i, kh\\u00f3a lu\\u1eadn, ti\\u1ebfn \\u0111\\u1ed9 th\\u1ef1c hi\\u1ec7n v\\u00e0 c\\u00e1c b\\u00e1o c\\u00e1o \\u0111\\u01b0\\u1ee3c n\\u1ed9p.\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":42,\"snippet\":\"SQL (Structured Query Language) l\\u00e0 ng\\u00f4n ng\\u1eef \\u0111\\u01b0\\u1ee3c s\\u1eed d\\u1ee5ng \\u0111\\u1ec3 giao ti\\u1ebfp v\\u00e0 \\nl\\u00e0m vi\\u1ec7c v\\u1edbi c\\u00e1c h\\u1ec7 qu\\u1ea3n tr\\u1ecb c\\u01a1 s\\u1edf d\\u1eef li\\u1ec7u quan h\\u1ec7. SQL cho ph\\u00e9p ng\\u01b0\\u1eddi ph\\u00e1t tri\\u1ec3n \\nth\\u1ef1c hi\\u1ec7n c\\u00e1c thao t\\u00e1c nh\\u01b0 t\\u1ea1o c\\u01a1 s\\u1edf d\\u1eef li\\u1ec7u, x\\u00e2y d\\u1ef1ng b\\u1ea3ng, th\\u00eam d\\u1eef li\\u1ec7u, c\\u1eadp nh\\u1eadt, \\nx\\u00f3a v\\u00e0 truy v\\u1ea5n th\\u00f4ng tin.\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":42,\"snippet\":\"Trong h\\u1ec7 th\\u1ed1ng, SQL \\u0111\\u01b0\\u1ee3c s\\u1eed d\\u1ee5ng \\u0111\\u1ec3 thao t\\u00e1c v\\u1edbi d\\u1eef li\\u1ec7u \\u0111\\u01b0\\u1ee3c l\\u01b0u tr\\u1eef trong \\nMySQL, ph\\u1ee5c v\\u1ee5 cho c\\u00e1c ch\\u1ee9c n\\u0103ng qu\\u1ea3n l\\u00fd v\\u00e0 khai th\\u00e1c th\\u00f4ng tin.\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":43,\"snippet\":\"X\\u1eed l\\u00fd ng\\u00f4n ng\\u1eef t\\u1ef1 nhi\\u00ean (Natural Language Processing \\u2013 NLP) l\\u00e0 m\\u1ed9t l\\u0129nh \\nv\\u1ef1c thu\\u1ed9c Tr\\u00ed tu\\u1ec7 nh\\u00e2n t\\u1ea1o v\\u00e0 Khoa h\\u1ecdc m\\u00e1y t\\u00ednh, nghi\\u00ean c\\u1ee9u c\\u00e1c ph\\u01b0\\u01a1ng ph\\u00e1p \\ngi\\u00fap m\\u00e1y t\\u00ednh c\\u00f3 kh\\u1ea3 n\\u0103ng x\\u1eed l\\u00fd, ph\\u00e2n t\\u00edch v\\u00e0 hi\\u1ec3u ng\\u00f4n ng\\u1eef t\\u1ef1 nhi\\u00ean c\\u1ee7a con \\nng\\u01b0\\u1eddi.\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":43,\"snippet\":\"Th\\u00f4ng qua c\\u00e1c k\\u1ef9 thu\\u1eadt NLP, m\\u00e1y t\\u00ednh c\\u00f3 th\\u1ec3 x\\u00e1c \\u0111\\u1ecbnh n\\u1ed9i \\ndung, ph\\u00e2n t\\u00edch ng\\u1eef ngh\\u0129a, tr\\u00edch xu\\u1ea5t th\\u00f4ng tin v\\u00e0 chuy\\u1ec3n \\u0111\\u1ed5i d\\u1eef li\\u1ec7u v\\u0103n b\\u1ea3n th\\u00e0nh \\nc\\u00e1c th\\u00f4ng tin ph\\u00f9 h\\u1ee3p cho qu\\u00e1 tr\\u00ecnh x\\u1eed l\\u00fd ti\\u1ebfp theo.\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":43,\"snippet\":\"M\\u1ed9t s\\u1ed1 \\nb\\u00e0i to\\u00e1n ph\\u1ed5 bi\\u1ebfn g\\u1ed3m: \\n\\u2022 \\nPh\\u00e2n lo\\u1ea1i v\\u0103n b\\u1ea3n: Ph\\u00e2n lo\\u1ea1i t\\u00e0i li\\u1ec7u v\\u00e0o c\\u00e1c nh\\u00f3m d\\u1ef1a tr\\u00ean n\\u1ed9i dung. \\n\\u2022 \\nPh\\u00e2n t\\u00edch c\\u1ea3m x\\u00fac: X\\u00e1c \\u0111\\u1ecbnh tr\\u1ea1ng th\\u00e1i ho\\u1eb7c c\\u1ea3m x\\u00fac \\u0111\\u01b0\\u1ee3c th\\u1ec3 hi\\u1ec7n trong \\nv\\u0103n b\\u1ea3n. \\n\\u2022 \\nNh\\u1eadn d\\u1ea1ng th\\u1ef1c th\\u1ec3 c\\u00f3 t\\u00ean: X\\u00e1c \\u0111\\u1ecbnh c\\u00e1c th\\u1ef1c th\\u1ec3 nh\\u01b0 ng\\u01b0\\u1eddi, t\\u1ed5 ch\\u1ee9c, \\u0111\\u1ecba \\n\\u0111i\\u1ec3m v\\u00e0 th\\u1eddi gian. \\n\\u2022 \\nTr\\u00edch xu\\u1ea5t th\\u00f4ng tin: X\\u00e1c \\u0111\\u1ecbnh v\\u00e0 thu th\\u1eadp c\\u00e1c th\\u00f4ng tin quan tr\\u1ecdng t\\u1eeb v\\u0103n \\nb\\u1ea3n. \\n\\u2022 \\nD\\u1ecbch m\\u00e1y: Chuy\\u1ec3n \\u0111\\u1ed5i n\\u1ed9i dung t\\u1eeb ng\\u00f4n ng\\u1eef n\\u00e0y sang ng\\u00f4n ng\\u1eef kh\\u00e1c. \\n\\u2022 \\nTr\\u1ea3 l\\u1eddi c\\u00e2u h\\u1ecfi: Ph\\u00e2n t\\u00edch c\\u00e2u h\\u1ecfi v\\u00e0 cung c\\u1ea5p c\\u00e2u tr\\u1ea3 l\\u1eddi d\\u1ef1a tr\\u00ean n\\u1ed9i \\ndung \\u0111\\u01b0\\u1ee3c cung c\\u1ea5p. \\n\\u2022 \\nT\\u00f3m t\\u1eaft v\\u0103n b\\u1ea3n: T\\u1ea1o ra n\\u1ed9i dung ng\\u1eafn g\\u1ecdn t\\u1eeb m\\u1ed9t v\\u0103n b\\u1ea3n ho\\u1eb7c t\\u00e0i li\\u1ec7u \\nc\\u00f3 \\u0111\\u1ed9 d\\u00e0i l\\u1edbn.\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":44,\"snippet\":\"Trong \\u0111\\u1ec1 t\\u00e0i X\\u00e2y d\\u1ef1ng H\\u1ec7 th\\u1ed1ng qu\\u1ea3n l\\u00fd kh\\u00f3a lu\\u1eadn t\\u1ed1t nghi\\u1ec7p t\\u00edch h\\u1ee3p tr\\u00ed tu\\u1ec7 \\nnh\\u00e2n t\\u1ea1o (AI), NLP \\u0111\\u01b0\\u1ee3c \\u1ee9ng d\\u1ee5ng ch\\u1ee7 y\\u1ebfu v\\u00e0o vi\\u1ec7c \\u0111\\u1ecdc v\\u00e0 t\\u00f3m t\\u1eaft b\\u00e1o c\\u00e1o kh\\u00f3a \\nlu\\u1eadn do sinh vi\\u00ean n\\u1ed9p.\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":44,\"snippet\":\"M\\u00f4 h\\u00ecnh ng\\u00f4n ng\\u1eef l\\u1edbn (Large Language Model \\u2013 LLM) l\\u00e0 m\\u1ed9t lo\\u1ea1i m\\u00f4 h\\u00ecnh \\ntr\\u00ed tu\\u1ec7 nh\\u00e2n t\\u1ea1o \\u0111\\u01b0\\u1ee3c x\\u00e2y d\\u1ef1ng nh\\u1eb1m x\\u1eed l\\u00fd v\\u00e0 t\\u1ea1o ra ng\\u00f4n ng\\u1eef t\\u1ef1 nhi\\u00ean. LLM \\nth\\u01b0\\u1eddng \\u0111\\u01b0\\u1ee3c ph\\u00e1t tri\\u1ec3n d\\u1ef1a tr\\u00ean ki\\u1ebfn tr\\u00fac Transformer v\\u00e0 \\u0111\\u01b0\\u1ee3c hu\\u1ea5n luy\\u1ec7n tr\\u00ean \\nkh\\u1ed1i l\\u01b0\\u1ee3ng l\\u1edbn d\\u1eef li\\u1ec7u v\\u0103n b\\u1ea3n\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":44,\"snippet\":\"LLM c\\u00f3 kh\\u1ea3 n\\u0103ng ph\\u00e2n t\\u00edch n\\u1ed9i dung \\u0111\\u1ea7u v\\u00e0o d\\u1ef1a tr\\u00ean ng\\u1eef c\\u1ea3nh v\\u00e0 m\\u1ed1i quan \\nh\\u1ec7 gi\\u1eefa c\\u00e1c th\\u00e0nh ph\\u1ea7n trong v\\u0103n b\\u1ea3n. T\\u1eeb n\\u1ed9i dung \\u0111\\u01b0\\u1ee3c cung c\\u1ea5p, m\\u00f4 h\\u00ecnh c\\u00f3 th\\u1ec3 \\nt\\u1ea1o ra v\\u0103n b\\u1ea3n m\\u1edbi ph\\u00f9 h\\u1ee3p v\\u1edbi y\\u00eau c\\u1ea7u nh\\u01b0 tr\\u1ea3 l\\u1eddi c\\u00e2u h\\u1ecfi, gi\\u1ea3i th\\u00edch n\\u1ed9i dung, \\nvi\\u1ebft l\\u1ea1i v\\u0103n b\\u1ea3n ho\\u1eb7c t\\u1ea1o b\\u00e1o c\\u00e1o.\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":45,\"snippet\":\"Trong h\\u1ec7 th\\u1ed1ng c\\u1ee7a nh\\u00f3m, LLM \\u0111\\u01b0\\u1ee3c s\\u1eed d\\u1ee5ng nh\\u01b0 m\\u1ed9t d\\u1ecbch v\\u1ee5 \\u0111\\u00e3 hu\\u1ea5n luy\\u1ec7n \\ns\\u1eb5n \\u0111\\u1ec3 h\\u1ed7 tr\\u1ee3 \\u0111\\u1ecdc b\\u00e1o c\\u00e1o. Nh\\u00f3m kh\\u00f4ng t\\u1ef1 hu\\u1ea5n luy\\u1ec7n hay tinh ch\\u1ec9nh c\\u00e1c tham s\\u1ed1 \\nc\\u1ee7a m\\u00f4 h\\u00ecnh.\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":45,\"snippet\":\"\\u0110\\u1ed1i v\\u1edbi \\u0111\\u1ec1 t\\u00e0i c\\u1ee7a nh\\u00f3m, c\\u00e1ch t\\u00edch h\\u1ee3p n\\u00e0y \\u0111\\u01b0\\u1ee3c s\\u1eed d\\u1ee5ng \\u0111\\u1ec3 g\\u1eedi n\\u1ed9i dung \\ntr\\u00edch xu\\u1ea5t t\\u1eeb b\\u00e1o c\\u00e1o PDF \\u0111\\u1ebfn Gemini v\\u00e0 nh\\u1eadn k\\u1ebft qu\\u1ea3 t\\u00f3m t\\u1eaft.\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":45,\"snippet\":\"T\\u00f3m t\\u1eaft v\\u0103n b\\u1ea3n t\\u1ef1 \\u0111\\u1ed9ng (Automatic Text Summarization) l\\u00e0 qu\\u00e1 tr\\u00ecnh s\\u1eed \\nd\\u1ee5ng c\\u00e1c ph\\u01b0\\u01a1ng ph\\u00e1p x\\u1eed l\\u00fd ng\\u00f4n ng\\u1eef t\\u1ef1 nhi\\u00ean v\\u00e0 tr\\u00ed tu\\u1ec7 nh\\u00e2n t\\u1ea1o \\u0111\\u1ec3 t\\u1ea1o ra m\\u1ed9t \\nphi\\u00ean b\\u1ea3n ng\\u1eafn g\\u1ecdn t\\u1eeb v\\u0103n b\\u1ea3n ban \\u0111\\u1ea7u, \\u0111\\u1ed3ng th\\u1eddi gi\\u1eef l\\u1ea1i nh\\u1eefng th\\u00f4ng tin v\\u00e0 n\\u1ed9i \\ndung quan tr\\u1ecdng.\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":46,\"snippet\":\"T\\u00f3m t\\u1eaft v\\u0103n b\\u1ea3n nh\\u1eb1m gi\\u1ea3m th\\u1eddi gian \\u0111\\u1ecdc v\\u00e0 h\\u1ed7 tr\\u1ee3 ng\\u01b0\\u1eddi d\\u00f9ng nhanh ch\\u00f3ng \\nn\\u1eafm b\\u1eaft n\\u1ed9i dung ch\\u00ednh c\\u1ee7a t\\u00e0i li\\u1ec7u.\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":46,\"snippet\":\"V\\u00ec v\\u1eady, ph\\u01b0\\u01a1ng ph\\u00e1p chia t\\u00e0i li\\u1ec7u th\\u00e0nh t\\u1eebng ph\\u1ea7n nh\\u1ecf l\\u00e0 l\\u1ef1a ch\\u1ecdn ph\\u00f9 h\\u1ee3p h\\u01a1n.\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":46,\"snippet\":\"T\\u00f3m t\\u1eaft theo t\\u1eebng ph\\u1ea7n l\\u00e0 ph\\u01b0\\u01a1ng ph\\u00e1p chia t\\u00e0i li\\u1ec7u th\\u00e0nh nhi\\u1ec1u ph\\u1ea7n nh\\u1ecf \\ntr\\u01b0\\u1edbc khi \\u0111\\u01b0a v\\u00e0o m\\u00f4 h\\u00ecnh LLM. M\\u1ed7i ph\\u1ea7n \\u0111\\u01b0\\u1ee3c x\\u1eed l\\u00fd v\\u00e0 t\\u00f3m t\\u1eaft ri\\u00eang, sau \\u0111\\u00f3 c\\u00e1c \\nk\\u1ebft qu\\u1ea3 \\u0111\\u01b0\\u1ee3c t\\u1ed5ng h\\u1ee3p \\u0111\\u1ec3 t\\u1ea1o th\\u00e0nh b\\u1ea3n t\\u00f3m t\\u1eaft chung cho to\\u00e0n b\\u1ed9 t\\u00e0i li\\u1ec7u.\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":46,\"snippet\":\"Nh\\u00f3m l\\u1ef1a ch\\u1ecdn t\\u00f3m t\\u1eaft theo t\\u1eebng ph\\u1ea7n, \\u01b0u ti\\u00ean chia b\\u00e1o c\\u00e1o theo ch\\u01b0\\u01a1ng v\\u00e0 \\nm\\u1ee5c tr\\u01b0\\u1edbc khi chia nh\\u1ecf ti\\u1ebfp.\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":47,\"snippet\":\"C\\u00e1c k\\u1ef9 thu\\u1eadt li\\u00ean quan \\u0111\\u1ebfn b\\u00e0i to\\u00e1n g\\u1ed3m ph\\u00e2n \\u0111o\\u1ea1n v\\u0103n b\\u1ea3n, ch\\u1ed3ng l\\u1ea5n gi\\u1eefa \\nc\\u00e1c \\u0111o\\u1ea1n, t\\u00f3m t\\u1eaft sinh, Map\\u2013Reduce, thi\\u1ebft k\\u1ebf c\\u00e2u l\\u1ec7nh v\\u00e0 sinh JSON.\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":47,\"snippet\":\"Ph\\u00e2n \\u0111o\\u1ea1n v\\u0103n b\\u1ea3n (Chunking) l\\u00e0 k\\u1ef9 thu\\u1eadt chia m\\u1ed9t t\\u00e0i li\\u1ec7u c\\u00f3 k\\u00edch th\\u01b0\\u1edbc l\\u1edbn \\nth\\u00e0nh nhi\\u1ec1u \\u0111o\\u1ea1n v\\u0103n b\\u1ea3n nh\\u1ecf h\\u01a1n nh\\u1eb1m ph\\u00f9 h\\u1ee3p v\\u1edbi kh\\u1ea3 n\\u0103ng x\\u1eed l\\u00fd c\\u1ee7a m\\u00f4 h\\u00ecnh \\nng\\u00f4n ng\\u1eef l\\u1edbn (LLM).\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":47,\"snippet\":\"Character Splitting l\\u00e0 ph\\u01b0\\u01a1ng ph\\u00e1p ph\\u00e2n \\u0111o\\u1ea1n d\\u1ef1a tr\\u00ean s\\u1ed1 l\\u01b0\\u1ee3ng k\\u00fd t\\u1ef1 c\\u1ed1 \\n\\u0111\\u1ecbnh.\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":48,\"snippet\":\"Token Splitting th\\u1ef1c hi\\u1ec7n ph\\u00e2n \\u0111o\\u1ea1n d\\u1ef1a tr\\u00ean s\\u1ed1 l\\u01b0\\u1ee3ng token thay v\\u00ec s\\u1ed1 l\\u01b0\\u1ee3ng \\nk\\u00fd t\\u1ef1.\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":48,\"snippet\":\"Recursive Character Splitting l\\u00e0 ph\\u01b0\\u01a1ng ph\\u00e1p ph\\u00e2n \\u0111o\\u1ea1n \\u0111\\u01b0\\u1ee3c s\\u1eed d\\u1ee5ng ph\\u1ed5 \\nbi\\u1ebfn \\u0111\\u1ed1i v\\u1edbi c\\u00e1c t\\u00e0i li\\u1ec7u v\\u0103n b\\u1ea3n c\\u00f3 c\\u1ea5u tr\\u00fac t\\u01b0\\u01a1ng \\u0111\\u1ed1i r\\u00f5 r\\u00e0ng. Thay v\\u00ec c\\u1eaft v\\u0103n b\\u1ea3n \\nm\\u1ed9t c\\u00e1ch c\\u01a1 h\\u1ecdc, ph\\u01b0\\u01a1ng ph\\u00e1p n\\u00e0y s\\u1eed d\\u1ee5ng nhi\\u1ec1u m\\u1ee9c ph\\u00e2n t\\u00e1ch theo th\\u1ee9 t\\u1ef1 \\u01b0u \\nti\\u00ean.\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":49,\"snippet\":\"Chunk Overlap cho ph\\u00e9p m\\u1ed9t ph\\u1ea7n n\\u1ed9i dung \\u1edf cu\\u1ed1i chunk tr\\u01b0\\u1edbc \\u0111\\u01b0\\u1ee3c l\\u1eb7p l\\u1ea1i \\n\\u1edf \\u0111\\u1ea7u chunk ti\\u1ebfp theo.\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":49,\"snippet\":\"T\\u00f3m t\\u1eaft sinh (Abstractive Summarization) l\\u00e0 c\\u00e1ch m\\u00f4 h\\u00ecnh di\\u1ec5n \\u0111\\u1ea1t l\\u1ea1i nh\\u1eefng \\n\\u00fd ch\\u00ednh b\\u1eb1ng c\\u00e2u m\\u1edbi, thay v\\u00ec ch\\u1ec9 sao ch\\u00e9p c\\u00e1c c\\u00e2u c\\u00f3 s\\u1eb5n.\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":49,\"snippet\":\"Map\\u2013Reduce l\\u00e0 c\\u00e1ch chia b\\u00e0i to\\u00e1n t\\u00f3m t\\u1eaft t\\u00e0i li\\u1ec7u d\\u00e0i th\\u00e0nh hai nh\\u00f3m c\\u00f4ng \\nvi\\u1ec7c: t\\u00f3m t\\u1eaft t\\u1eebng ph\\u1ea7n v\\u00e0 t\\u1ed5ng h\\u1ee3p c\\u00e1c b\\u1ea3n t\\u00f3m t\\u1eaft \\u0111\\u00f3.\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":50,\"snippet\":\"Prompt Engineering l\\u00e0 vi\\u1ec7c vi\\u1ebft c\\u00e2u l\\u1ec7nh \\u0111\\u1ee7 r\\u00f5 \\u0111\\u1ec3 h\\u01b0\\u1edbng d\\u1eabn m\\u00f4 h\\u00ecnh th\\u1ef1c \\nhi\\u1ec7n m\\u1ed9t nhi\\u1ec7m v\\u1ee5.\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":50,\"snippet\":\"\\u0110\\u1ec3 d\\u1ec5 x\\u1eed l\\u00fd k\\u1ebft qu\\u1ea3, h\\u1ec7 th\\u1ed1ng y\\u00eau c\\u1ea7u LLM tr\\u1ea3 d\\u1eef li\\u1ec7u d\\u01b0\\u1edbi d\\u1ea1ng JSON \\n(JavaScript Object Notation).\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":51,\"snippet\":\"Trong ph\\u1ea1m vi x\\u1eed l\\u00fd hi\\u1ec7n t\\u1ea1i, nh\\u00f3m s\\u1eed d\\u1ee5ng PyMuPDF \\u0111\\u1ec3 tr\\u00edch xu\\u1ea5t v\\u0103n b\\u1ea3n v\\u00e0 \\nth\\u00f4ng tin trang t\\u1eeb PDF c\\u00f3 l\\u1edbp v\\u0103n b\\u1ea3n.\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":51,\"snippet\":\"V\\u00ec v\\u1eady, tr\\u01b0\\u1edbc ti\\u00ean t\\u00e0i li\\u1ec7u \\u0111\\u01b0\\u1ee3c nh\\u1eadn di\\u1ec7n theo c\\u00e1c \\u0111\\u1ec1 m\\u1ee5c \\nnh\\u01b0 1.1, 1.2 ho\\u1eb7c 2.3; ch\\u1ec9 nh\\u1eefng m\\u1ee5c qu\\u00e1 d\\u00e0i m\\u1edbi ti\\u1ebfp t\\u1ee5c chia th\\u00e0nh c\\u00e1c chunk \\nnh\\u1ecf h\\u01a1n.\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":52,\"snippet\":\"Sau khi nh\\u1eadn b\\u00e1o c\\u00e1o PDF, ch\\u01b0\\u01a1ng tr\\u00ecnh tr\\u00edch xu\\u1ea5t v\\u0103n b\\u1ea3n r\\u1ed3i t\\u00ecm c\\u00e1c d\\u1ea5u \\nhi\\u1ec7u nh\\u1eadn di\\u1ec7n ch\\u01b0\\u01a1ng, m\\u1ee5c nh\\u01b0 s\\u1ed1 \\u0111\\u1ec1 m\\u1ee5c, ti\\u00eau \\u0111\\u1ec1 ho\\u1eb7c c\\u00e1ch tr\\u00ecnh b\\u00e0y.\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":54,\"snippet\":\"\\u0110\\u1ec3 h\\u1ea1n ch\\u1ebf v\\u1ea5n \\u0111\\u1ec1 n\\u00e0y, h\\u1ec7 th\\u1ed1ng s\\u1eed d\\u1ee5ng Chunk Overlap, t\\u1ee9c l\\u00e0 cho ph\\u00e9p \\nm\\u1ed9t ph\\u1ea7n n\\u1ed9i dung c\\u1ee7a chunk tr\\u01b0\\u1edbc \\u0111\\u01b0\\u1ee3c l\\u1eb7p l\\u1ea1i \\u1edf \\u0111\\u1ea7u chunk k\\u1ebf ti\\u1ebfp.\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":54,\"snippet\":\"PHP \\u0111\\u01b0\\u1ee3c s\\u1eed d\\u1ee5ng l\\u00e0m ng\\u00f4n ng\\u1eef l\\u1eadp tr\\u00ecnh ch\\u00ednh cho ph\\u00eda Back-end c\\u1ee7a h\\u1ec7 \\nth\\u1ed1ng.\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":55,\"snippet\":\"Laravel l\\u00e0 Web Framework m\\u00e3 ngu\\u1ed3n m\\u1edf \\u0111\\u01b0\\u1ee3c x\\u00e2y d\\u1ef1ng tr\\u00ean n\\u1ec1n t\\u1ea3ng PHP \\nv\\