ea3 mong \\u0111\\u1ee3i \\nTh\\u1ef1c t\\u1ebf \\nBV01 \\nN\\u1ed9p h\\u1ed3 s\\u01a1 h\\u1ee3p l\\u1ec7 \\nGhi nh\\u1eadn h\\u1ed3 s\\u01a1 ch\\u1edd \\nduy\\u1ec7t \\nH\\u1ed3 s\\u01a1 \\u0111\\u01b0\\u1ee3c chuy\\u1ec3n \\nsang tr\\u1ea1ng th\\u00e1i ch\\u1edd \\nduy\\u1ec7t b\\u1edfi GVHD \\nBV02 \\nH\\u1ed3 s\\u01a1 thi\\u1ebfu t\\u00e0i li\\u1ec7u \\nb\\u1eaft bu\\u1ed9c \\nTh\\u00f4ng b\\u00e1o b\\u1ed5 sung \\nHi\\u1ec3n th\\u1ecb th\\u00f4ng b\\u00e1o \\nthi\\u1ebfu th\\u00f4ng tin tr\\u1ecf \\nv\\u1ec1 m\\u1ee5c b\\u1ecb thi\\u1ebfu \\nBV03 \\nY\\u00eau c\\u1ea7u sinh vi\\u00ean \\nch\\u1ec9nh s\\u1eeda h\\u1ed3 s\\u01a1 \\nC\\u1eadp nh\\u1eadt tr\\u1ea1ng th\\u00e1i \\nv\\u00e0 l\\u00fd do \\nC\\u1eadp nh\\u1eadt tr\\u1ea1ng th\\u00e1i \\nh\\u1ed3 s\\u01a1 c\\u1ea7n ch\\u1ec9nh s\\u1eeda \\nv\\u00e0 l\\u00fd do c\\u1ee7a \\nGVHD \\nBV04 \\nPh\\u00e2n c\\u00f4ng h\\u1ed9i \\n\\u0111\\u1ed3ng b\\u1ecb tr\\u00f9ng l\\u1ecbch \\nC\\u1ea3nh b\\u00e1o ho\\u1eb7c t\\u1eeb \\nch\\u1ed1i theo quy \\u0111\\u1ecbnh \\nKh\\u00f4ng \\u0111\\u01b0\\u1ee3c ph\\u00e9p \\nph\\u00e2n c\\u00f4ng v\\u00ec kh\\u00f4ng \\nth\\u1ec3 ch\\u1ecdn tr\\u00f9ng l\\u1ecbch \\nBV05 \\nCh\\u01b0a \\u0111\\u1ee7 phi\\u1ebfu \\nch\\u1ea5m \\nKh\\u00f4ng ho\\u00e0n t\\u1ea5t \\nc\\u00f4ng b\\u1ed1 k\\u1ebft qu\\u1ea3 \\nKh\\u00f4ng hi\\u1ec3n th\\u1ecb \\n\\u0111\\u01b0\\u1ee3c k\\u1ebft qu\\u1ea3 kh\\u00f3a \\nlu\\u1eadn v\\u00ec ch\\u01b0a \\u0111\\u1ee7 \\nphi\\u1ebfu ch\\u1ea5m \\n 1\\n\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":135,\"snippet\":\"M\\u00e3 \\nThao t\\u00e1c th\\u1eed \\nnghi\\u1ec7m \\nK\\u1ebft qu\\u1ea3 mong \\u0111\\u1ee3i \\nTh\\u1ef1c t\\u1ebf \\nBV06 \\nT\\u1eeb ch\\u1ed1i thao t\\u00e1c v\\u00e0 \\ngi\\u1eef nguy\\u00ean d\\u1eef li\\u1ec7u \\nT\\u00e0i kho\\u1ea3n kh\\u00f4ng \\nc\\u00f3 quy\\u1ec1n th\\u1ef1c hi\\u1ec7n \\nx\\u00e9t duy\\u1ec7t  \\nKh\\u00f4ng th\\u1ec3 truy c\\u1eadp \\nkhi kh\\u00f4ng \\u0111\\u01b0\\u1ee3c c\\u1ea5p \\nquy\\u1ec1n \\nHi\\u0300nh 6.10 K\\u1ebft qu\\u1ea3 ph\\u00ea duy\\u1ec7t h\\u1ed3 s\\u01a1 b\\u1ea3o v\\u1ec7 \\nHi\\u0300nh 6.11 K\\u1ebft qu\\u1ea3 sinh vi\\u00ean sau khi ch\\u1ea5m \\u0111i\\u1ec3m \\n 1\\n\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":136,\"snippet\":\"Hi\\u0300nh 6.12 K\\u1ebft qu\\u1ea3 ghi nh\\u1eadn \\u0111i\\u1ec3m v\\u00e0 t\\u1ed5ng h\\u1ee3p k\\u1ebft qu\\u1ea3 b\\u1ea3o v\\u1ec7 \\nHi\\u0300nh 6.13 K\\u1ebft qu\\u1ea3 th\\u00e0nh l\\u1eadp h\\u1ed9i \\u0111\\u1ed3ng b\\u1ea3o v\\u1ec7 cho nh\\u00f3m \\u0111\\u1ec1 t\\u00e0i \\n6.4.5.  Th\\u1eed nghi\\u1ec7m th\\u1ed1ng k\\u00ea \\nCh\\u1ee9c n\\u0103ng th\\u1ed1ng k\\u00ea \\u0111\\u01b0\\u1ee3c th\\u1eed nghi\\u1ec7m b\\u1eb1ng c\\u00e1ch l\\u1ef1a ch\\u1ecdn h\\u1ecdc k\\u1ef3 v\\u00e0 c\\u00e1c \\n\\u0111i\\u1ec1u ki\\u1ec7n l\\u1ecdc ph\\u00f9 h\\u1ee3p. H\\u1ec7 th\\u1ed1ng c\\u1ea7n hi\\u1ec3n th\\u1ecb s\\u1ed1 li\\u1ec7u v\\u1ec1 sinh vi\\u00ean, \\u0111\\u1ec1 t\\u00e0i, gi\\u1ea3ng vi\\u00ean \\nh\\u01b0\\u1edbng d\\u1eabn ho\\u1eb7c k\\u1ebft qu\\u1ea3 b\\u1ea3o v\\u1ec7 d\\u1ef1a tr\\u00ean d\\u1eef li\\u1ec7u hi\\u1ec7n c\\u00f3. S\\u1ed1 li\\u1ec7u th\\u1ed1ng k\\u00ea \\u0111\\u01b0\\u1ee3c \\u0111\\u1ed1i \\nchi\\u1ebfu v\\u1edbi d\\u1eef li\\u1ec7u g\\u1ed1c \\u0111\\u1ec3 ki\\u1ec3m tra \\u0111\\u1ed9 ch\\u00ednh x\\u00e1c. \\nNgo\\u00e0i tr\\u01b0\\u1eddng h\\u1ee3p c\\u00f3 d\\u1eef li\\u1ec7u, c\\u1ea7n ki\\u1ec3m tra tr\\u01b0\\u1eddng h\\u1ee3p kh\\u00f4ng c\\u00f3 k\\u1ebft qu\\u1ea3 ph\\u00f9 \\nh\\u1ee3p. N\\u1ebfu phi\\u00ean b\\u1ea3n h\\u1ec7 th\\u1ed1ng \\u0111\\u00e3 c\\u00f3 ch\\u1ee9c n\\u0103ng xu\\u1ea5t b\\u00e1o c\\u00e1o Excel ho\\u1eb7c PDF, nh\\u00f3m \\nth\\u1eed nghi\\u1ec7m th\\u00eam t\\u00ednh ch\\u00ednh x\\u00e1c c\\u1ee7a t\\u1ec7p xu\\u1ea5t so v\\u1edbi k\\u1ebft qu\\u1ea3 tr\\u00ean giao di\\u1ec7n. \\n 1\\n\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":137,\"snippet\":\"Hi\\u0300nh 6.14 K\\u1ebft qu\\u1ea3 th\\u1ed1ng k\\u00ea c\\u00e1c th\\u00f4ng tin kh\\u00f3a lu\\u1eadn \\n6.5.  PH\\u00c1T TRI\\u1ec2N CH\\u1ee8C N\\u0102NG T\\u00d3M T\\u1eaeT B\\u00c1O C\\u00c1O  \\n6.5.1.  B\\u00e0i to\\u00e1n t\\u00f3m t\\u1eaft b\\u00e1o c\\u00e1o \\nTrong qu\\u00e1 tr\\u00ecnh th\\u1ef1c hi\\u1ec7n kh\\u00f3a lu\\u1eadn t\\u1ed1t nghi\\u1ec7p, sinh vi\\u00ean ph\\u1ea3i n\\u1ed9p b\\u00e1o c\\u00e1o \\nti\\u1ebfn \\u0111\\u1ed9 theo c\\u00e1c \\u0111\\u1ee3t do gi\\u1ea3ng vi\\u00ean quy \\u0111\\u1ecbnh. N\\u1ed9i dung b\\u00e1o c\\u00e1o c\\u00f3 th\\u1ec3 bao g\\u1ed3m \\nnhi\\u1ec1u ch\\u01b0\\u01a1ng, m\\u1ee5c v\\u00e0 c\\u00f3 \\u0111\\u1ed9 d\\u00e0i t\\u1eeb v\\u00e0i ch\\u1ee5c \\u0111\\u1ebfn h\\u00e0ng tr\\u0103m trang. Vi\\u1ec7c \\u0111\\u1ecdc to\\u00e0n b\\u1ed9 \\n 1\\n\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":138,\"snippet\":\"b\\u00e1o c\\u00e1o \\u0111\\u1ec3 x\\u00e1c \\u0111\\u1ecbnh nh\\u1eefng n\\u1ed9i dung sinh vi\\u00ean \\u0111\\u00e3 th\\u1ef1c hi\\u1ec7n c\\u00f3 th\\u1ec3 m\\u1ea5t nhi\\u1ec1u th\\u1eddi \\ngian, \\u0111\\u1eb7c bi\\u1ec7t khi gi\\u1ea3ng vi\\u00ean ph\\u1ee5 tr\\u00e1ch nhi\\u1ec1u nh\\u00f3m kh\\u00f3a lu\\u1eadn. \\n\\u0110\\u1ec3 h\\u1ed7 tr\\u1ee3 qu\\u00e1 tr\\u00ecnh theo d\\u00f5i ti\\u1ebfn \\u0111\\u1ed9, nh\\u00f3m ph\\u00e1t tri\\u1ec3n ch\\u1ee9c n\\u0103ng t\\u1ef1 \\u0111\\u1ed9ng t\\u00f3m \\nt\\u1eaft b\\u00e1o c\\u00e1o kh\\u00f3a lu\\u1eadn b\\u1eb1ng m\\u00f4 h\\u00ecnh ng\\u00f4n ng\\u1eef l\\u1edbn. Ch\\u1ee9c n\\u0103ng ti\\u1ebfp nh\\u1eadn t\\u1ec7p b\\u00e1o \\nc\\u00e1o PDF, tr\\u00edch xu\\u1ea5t n\\u1ed9i dung v\\u0103n b\\u1ea3n v\\u00e0 t\\u1ea1o b\\u1ea3n t\\u00f3m t\\u1eaft nh\\u1eefng c\\u00f4ng vi\\u1ec7c \\u0111\\u00e3 \\u0111\\u01b0\\u1ee3c \\ntr\\u00ecnh b\\u00e0y trong b\\u00e1o c\\u00e1o. \\nDo b\\u00e1o c\\u00e1o c\\u00f3 th\\u1ec3 ch\\u1ee9a l\\u01b0\\u1ee3ng l\\u1edbn n\\u1ed9i dung, h\\u1ec7 th\\u1ed1ng kh\\u00f4ng x\\u1eed l\\u00fd to\\u00e0n b\\u1ed9 \\nt\\u00e0i li\\u1ec7u trong m\\u1ed9t l\\u1ea7n g\\u1ecdi m\\u00f4 h\\u00ecnh. Thay v\\u00e0o \\u0111\\u00f3, n\\u1ed9i dung \\u0111\\u01b0\\u1ee3c ph\\u00e2n \\u0111o\\u1ea1n theo c\\u1ea5u \\ntr\\u00fac ch\\u01b0\\u01a1ng, m\\u1ee5c v\\u00e0 chia nh\\u1ecf khi c\\u1ea7n thi\\u1ebft. C\\u00e1c \\u0111o\\u1ea1n v\\u0103n b\\u1ea3n \\u0111\\u01b0\\u1ee3c t\\u00f3m t\\u1eaft b\\u1eb1ng \\nLLM, sau \\u0111\\u00f3 t\\u1ed5ng h\\u1ee3p theo ph\\u01b0\\u01a1ng ph\\u00e1p Map\\u2013Reduce. \\nK\\u1ebft qu\\u1ea3 t\\u00f3m t\\u1eaft \\u0111\\u01b0\\u1ee3c t\\u1ed5 ch\\u1ee9c theo c\\u00e1c ch\\u01b0\\u01a1ng, m\\u1ee5c t\\u01b0\\u01a1ng \\u1ee9ng v\\u1edbi b\\u00e1o c\\u00e1o \\ng\\u1ed1c nh\\u1eb1m h\\u1ed7 tr\\u1ee3 gi\\u1ea3ng vi\\u00ean theo d\\u00f5i v\\u00e0 \\u0111\\u1ed1i chi\\u1ebfu n\\u1ed9i dung. Nh\\u1eefng th\\u00f4ng tin kh\\u00f4ng \\nc\\u00f3 c\\u0103n c\\u1ee9 trong t\\u00e0i li\\u1ec7u kh\\u00f4ng \\u0111\\u01b0\\u1ee3c s\\u1eed d\\u1ee5ng l\\u00e0m n\\u1ed9i dung t\\u00f3m t\\u1eaft. \\n6.5.2.  S\\u01a1 \\u0111\\u1ed3 ho\\u1ea1t \\u0111\\u1ed9ng ch\\u1ee9c n\\u0103ng t\\u00f3m t\\u1eaft b\\u00e1o c\\u00e1o \\nS\\u01a1 \\u0111\\u1ed3 ho\\u1ea1t \\u0111\\u1ed9ng m\\u00f4 t\\u1ea3 c\\u00e1c b\\u01b0\\u1edbc t\\u1eeb khi sinh vi\\u00ean t\\u1ea3i l\\u00ean b\\u00e1o c\\u00e1o \\u0111\\u1ebfn khi \\ngi\\u1ea3ng vi\\u00ean xem k\\u1ebft qu\\u1ea3. H\\u1ec7 th\\u1ed1ng ki\\u1ec3m tra t\\u1ec7p \\u0111\\u1ea7u v\\u00e0o, tr\\u00edch xu\\u1ea5t n\\u1ed9i dung, nh\\u1eadn \\ndi\\u1ec7n ch\\u01b0\\u01a1ng, m\\u1ee5c v\\u00e0 chia chunk. Ti\\u1ebfp theo, c\\u00e1c \\u0111o\\u1ea1n v\\u0103n b\\u1ea3n \\u0111\\u01b0\\u1ee3c g\\u1eedi \\u0111\\u1ebfn LLM \\n\\u0111\\u1ec3 t\\u00f3m t\\u1eaft, sau \\u0111\\u00f3 \\u0111\\u01b0\\u1ee3c t\\u1ed5ng h\\u1ee3p v\\u00e0 ki\\u1ec3m tra tr\\u01b0\\u1edbc khi l\\u01b0u l\\u1ea1i. \\n 1\\n\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":139,\"snippet\":\"Hi\\u0300nh 6.15 S\\u01a1 \\u0111\\u1ed3 ho\\u1ea1t \\u0111\\u1ed9ng ch\\u1ee9c n\\u0103ng t\\u00f3m t\\u1eaft b\\u00e1o c\\u00e1o \\n6.5.3.  Quy tr\\u00ecnh x\\u1eed l\\u00fd b\\u00e1o c\\u00e1o \\nQuy tr\\u00ecnh \\u0111\\u01b0\\u1ee3c th\\u1ef1c hi\\u1ec7n sau khi sinh vi\\u00ean n\\u1ed9p v\\u00e0 h\\u1ec7 th\\u1ed1ng ti\\u1ebfp nh\\u1eadn t\\u1ec7p \\nPDF. N\\u1ed9i dung t\\u1eebng trang \\u0111\\u01b0\\u1ee3c tr\\u00edch xu\\u1ea5t th\\u00e0nh v\\u0103n b\\u1ea3n, sau \\u0111\\u00f3 h\\u1ec7 th\\u1ed1ng t\\u00ecm c\\u00e1c \\nti\\u00eau \\u0111\\u1ec1 ch\\u01b0\\u01a1ng, m\\u1ee5c \\u0111\\u1ec3 x\\u00e1c \\u0111\\u1ecbnh ranh gi\\u1edbi n\\u1ed9i dung. C\\u00e1c m\\u1ee5c d\\u00e0i ti\\u1ebfp t\\u1ee5c \\u0111\\u01b0\\u1ee3c \\nchia th\\u00e0nh nh\\u1eefng chunk nh\\u1ecf c\\u00f3 \\u0111\\u1ed9 d\\u00e0i ph\\u00f9 h\\u1ee3p v\\u1edbi gi\\u1edbi h\\u1ea1n x\\u1eed l\\u00fd c\\u1ee7a m\\u00f4 h\\u00ecnh. \\n\\u1ede giai \\u0111o\\u1ea1n Map, LLM t\\u00f3m t\\u1eaft t\\u1eebng chunk v\\u00e0 tr\\u1ea3 v\\u1ec1 d\\u1eef li\\u1ec7u c\\u00f3 c\\u1ea5u tr\\u00fac. \\u1ede \\ngiai \\u0111o\\u1ea1n Reduce, k\\u1ebft qu\\u1ea3 \\u0111\\u01b0\\u1ee3c t\\u1ed5ng h\\u1ee3p theo c\\u00e1c c\\u1ea5p t\\u1eeb chunk \\u0111\\u1ebfn m\\u1ee5c, ch\\u01b0\\u01a1ng \\nv\\u00e0 t\\u00e0i li\\u1ec7u. Tr\\u01b0\\u1edbc khi l\\u01b0u tr\\u1eef, h\\u1ec7 th\\u1ed1ng c\\u1ea7n ki\\u1ec3m tra JSON v\\u00e0 \\u0111\\u1ed1i chi\\u1ebfu n\\u1ed9i dung \\nv\\u1edbi ngu\\u1ed3n nh\\u1eb1m h\\u1ea1n ch\\u1ebf vi\\u1ec7c t\\u1ea1o c\\u00e1c \\u00fd kh\\u00f4ng c\\u00f3 trong b\\u00e1o c\\u00e1o. \\n 1\\n\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":140,\"snippet\":\"Hi\\u0300nh 6.16 Quy tr\\u00ecnh x\\u1eed l\\u00fd b\\u00e1o c\\u00e1o PDF b\\u1eb1ng Map\\u2013Reduce \\nQuy tr\\u00ecnh tr\\u00ean m\\u00f4 t\\u1ea3 ri\\u00eang ch\\u1ee9c n\\u0103ng t\\u00f3m t\\u1eaft b\\u00e1o c\\u00e1o. Vi\\u1ec7c so s\\u00e1nh b\\u00e1o c\\u00e1o \\nv\\u1edbi danh s\\u00e1ch y\\u00eau c\\u1ea7u c\\u1ee7a gi\\u1ea3ng vi\\u00ean l\\u00e0 ch\\u1ee9c n\\u0103ng kh\\u00e1c, kh\\u00f4ng n\\u00ean g\\u1ed9p th\\u00e0nh m\\u1ed9t \\nk\\u1ebft qu\\u1ea3 AI n\\u1ebfu h\\u1ec7 th\\u1ed1ng tri\\u1ec3n khai ch\\u00fang \\u0111\\u1ed9c l\\u1eadp. \\n6.5.4.  Ph\\u00e2n \\u0111o\\u1ea1n v\\u0103n b\\u1ea3n b\\u1eb1ng Chunking \\nH\\u1ec7 th\\u1ed1ng \\u01b0u ti\\u00ean chia t\\u00e0i li\\u1ec7u d\\u1ef1a theo c\\u1ea5u tr\\u00fac ch\\u01b0\\u01a1ng, m\\u1ee5c nh\\u01b0 1, 1.1, 2.3 \\nthay v\\u00ec c\\u1eaft to\\u00e0n b\\u1ed9 v\\u0103n b\\u1ea3n th\\u00e0nh nh\\u1eefng \\u0111o\\u1ea1n c\\u00f3 k\\u00edch th\\u01b0\\u1edbc c\\u1ed1 \\u0111\\u1ecbnh ngay t\\u1eeb \\u0111\\u1ea7u. \\nC\\u00e1ch n\\u00e0y gi\\u1eef \\u0111\\u01b0\\u1ee3c n\\u1ed9i dung thu\\u1ed9c c\\u00f9ng m\\u1ed9t m\\u1ee5c v\\u00e0 gi\\u00fap b\\u1ea3n t\\u00f3m t\\u1eaft c\\u00f3 th\\u1ec3 hi\\u1ec3n \\nth\\u1ecb theo s\\u1ed1 th\\u1ee9 t\\u1ef1 t\\u01b0\\u01a1ng \\u1ee9ng v\\u1edbi t\\u00e0i li\\u1ec7u g\\u1ed1c. \\n\\u0110\\u1ed1i v\\u1edbi nh\\u1eefng m\\u1ee5c c\\u00f3 n\\u1ed9i dung v\\u01b0\\u1ee3t qu\\u00e1 k\\u00edch th\\u01b0\\u1edbc cho ph\\u00e9p, h\\u1ec7 th\\u1ed1ng \\nti\\u1ebfp t\\u1ee5c t\\u1ea1o nhi\\u1ec1u chunk. M\\u1ed9t l\\u01b0\\u1ee3ng v\\u0103n b\\u1ea3n nh\\u1ecf \\u1edf cu\\u1ed1i chunk tr\\u01b0\\u1edbc c\\u00f3 th\\u1ec3 \\u0111\\u01b0\\u1ee3c \\ngi\\u1eef l\\u1ea1i \\u1edf \\u0111\\u1ea7u chunk sau \\u0111\\u1ec3 gi\\u1ea3m nguy c\\u01a1 m\\u1ea5t ng\\u1eef c\\u1ea3nh. K\\u00edch th\\u01b0\\u1edbc chunk v\\u00e0 \\nkho\\u1ea3ng ch\\u1ed3ng l\\u1ea5n c\\u1ea7n \\u0111\\u01b0\\u1ee3c c\\u1ea5u h\\u00ecnh d\\u1ef1a tr\\u00ean gi\\u1edbi h\\u1ea1n token c\\u1ee7a m\\u00f4 h\\u00ecnh \\u0111\\u01b0\\u1ee3c s\\u1eed \\nd\\u1ee5ng. \\nM\\u1ed7i chunk c\\u1ea7n g\\u1eafn th\\u00f4ng tin nh\\u1eadn di\\u1ec7n t\\u00e0i li\\u1ec7u, ch\\u01b0\\u01a1ng, m\\u1ee5c, s\\u1ed1 trang v\\u00e0 th\\u1ee9 t\\u1ef1 \\nx\\u1eed l\\u00fd. Ch\\u1eb3ng h\\u1ea1n, n\\u1ebfu m\\u1ee5c 3.2 \\u0111\\u01b0\\u1ee3c chia th\\u00e0nh n\\u0103m chunk, c\\u1ea3 n\\u0103m ph\\u1ea3i \\u0111\\u01b0\\u1ee3c t\\u1ed5ng \\nh\\u1ee3p tr\\u1edf l\\u1ea1i th\\u00e0nh m\\u1ed9t b\\u1ea3n t\\u00f3m t\\u1eaft c\\u1ee7a m\\u1ee5c 3.2 tr\\u01b0\\u1edbc khi chuy\\u1ec3n sang b\\u01b0\\u1edbc t\\u1ed5ng \\nh\\u1ee3p ch\\u01b0\\u01a1ng. \\n 1\\n\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":141,\"snippet\":\"B\\u1ea3ng 6.7 Th\\u00f4ng tin c\\u1ea7n l\\u01b0u k\\u00e8m chunk \\nThu\\u1ed9c t\\u00ednh \\nVai tr\\u00f2 \\nV\\u00ed d\\u1ee5 t\\u1eeb b\\u1ea3n ch\\u1ea1y \\ndocument_id \\/ \\ndocument_version_id \\n\\u0110\\u1ecbnh danh b\\u00e1o c\\u00e1o v\\u00e0 phi\\u00ean \\nb\\u1ea3n n\\u1ed9p \\nBC_DOT_135 \\/ \\nKHOI_D135_V5_6163be \\nsection_id \\/ \\nsection_number \\nM\\u00e3 n\\u1ed9i b\\u1ed9 v\\u00e0 s\\u1ed1 m\\u1ee5c trong t\\u00e0i \\nli\\u1ec7u \\ns00081 \\/ 3.2.2.2 \\nchunk_index \\nTh\\u1ee9 t\\u1ef1 chunk trong m\\u1ee5c \\n1 \\nstart_page \\/ end_page \\nTrang PDF v\\u1eadt l\\u00fd ch\\u1ee9a ngu\\u1ed3n 61 \\/ 61 \\ncontent \\nV\\u0103n b\\u1ea3n ngu\\u1ed3n c\\u1ee7a chunk \\nN\\u1ed9i dung m\\u1ee5c Quy tr\\u00ecnh \\nqu\\u1ea3n l\\u00fd danh s\\u00e1ch sinh vi\\u00ean \\n\\u0111\\u1ee7 \\u0111i\\u1ec1u ki\\u1ec7n \\nB\\u1ea3n tri\\u1ec3n khai s\\u1eed d\\u1ee5ng PyMuPDF 1.28.2 tr\\u00ean Python 3.10.6 \\u0111\\u1ec3 tr\\u00edch xu\\u1ea5t v\\u0103n b\\u1ea3n, \\nc\\u1ee1 ch\\u1eef v\\u00e0 v\\u1ecb tr\\u00ed ngu\\u1ed3n. B\\u1ed9 nh\\u1eadn di\\u1ec7n ti\\u00eau \\u0111\\u1ec1 k\\u1ebft h\\u1ee3p \\u0111\\u00e1nh s\\u1ed1, \\u0111\\u1ecbnh d\\u1ea1ng v\\u00e0 v\\u1ecb tr\\u00ed \\n\\u0111\\u1ec3 d\\u1ef1ng c\\u00e2y ch\\u01b0\\u01a1ng\\/m\\u1ee5c, ph\\u00e2n bi\\u1ec7t m\\u1ee5c l\\u1ee5c v\\u00e0 ph\\u1ea7n th\\u00e2n. Chunk c\\u1ea5u tr\\u00fac c\\u00f3 m\\u1ee5c \\nti\\u00eau 2.500, t\\u1ed1i \\u0111a 3.000 token \\u01b0\\u1edbc t\\u00ednh v\\u00e0 overlap c\\u1ea5u h\\u00ecnh 200 token. B\\u01b0\\u1edbc \\u0111\\u00f3ng \\ng\\u00f3i AI ri\\u00eang c\\u00f3 m\\u1ee5c ti\\u00eau n\\u1ed9i dung 2.500 token, overlap c\\u1ea5u h\\u00ecnh 80 token v\\u00e0 bi\\u00ean \\nan to\\u00e0n ng\\u00e2n s\\u00e1ch. Token local ch\\u1ec9 l\\u00e0 \\u01b0\\u1edbc t\\u00ednh, kh\\u00f4ng ph\\u1ea3i s\\u1ed1 token thanh to\\u00e1n c\\u1ee7a \\nAPI. \\nCh\\u1ea1y l\\u1ea1i ph\\u00e2n \\u0111o\\u1ea1n c\\u1ee5c b\\u1ed9 tr\\u00ean PDF 124 trang nh\\u1eadn di\\u1ec7n 234 m\\u1ee5c\\/v\\u00f9ng c\\u1ea5u \\ntr\\u00fac, t\\u1ea1o 240 chunk v\\u00e0 \\u0111\\u00f3ng th\\u00e0nh 23 g\\u00f3i Map. C\\u00e1c ki\\u1ec3m tra to\\u00e0n v\\u1eb9n kh\\u00f4ng c\\u00f3 \\nFAIL, v\\u1eabn c\\u00f3 c\\u1ea3nh b\\u00e1o \\u1ea3nh ch\\u01b0a \\u0111\\u1ecdc, v\\u00f9ng d\\u1ef1 ph\\u00f2ng v\\u00e0 m\\u1ee5c ch\\u1ec9 c\\u00f3 ti\\u00eau \\u0111\\u1ec1. \\u0110\\u1ed9 \\nbao ph\\u1ee7 100% ch\\u1ec9 \\u00e1p d\\u1ee5ng cho v\\u0103n b\\u1ea3n \\u0111\\u00e3 tr\\u00edch xu\\u1ea5t, kh\\u00f4ng ch\\u1ee9ng minh nh\\u1eadn di\\u1ec7n \\nc\\u1ea5u tr\\u00fac ho\\u1eb7c ng\\u1eef ngh\\u0129a ho\\u00e0n to\\u00e0n ch\\u00ednh x\\u00e1c. \\n6.5.5.  X\\u1eed l\\u00fd t\\u00f3m t\\u1eaft b\\u1eb1ng LLM \\nT\\u1ea1i b\\u01b0\\u1edbc Map, h\\u1ec7 th\\u1ed1ng l\\u1ea7n l\\u01b0\\u1ee3t g\\u1eedi t\\u1eebng chunk \\u0111\\u1ebfn API LLM c\\u00f9ng v\\u1edbi \\nprompt quy \\u0111\\u1ecbnh n\\u1ed9i dung c\\u1ea7n tr\\u00edch xu\\u1ea5t v\\u00e0 c\\u1ea5u tr\\u00fac \\u0111\\u1ea7u ra. Prompt y\\u00eau c\\u1ea7u m\\u00f4 \\nh\\u00ecnh t\\u1eadp trung v\\u00e0o nh\\u1eefng ph\\u1ea7n \\u0111\\u00e3 \\u0111\\u01b0\\u1ee3c tr\\u00ecnh b\\u00e0y trong chunk v\\u00e0 h\\u1ea1n ch\\u1ebf \\u0111\\u01b0a ra \\nnh\\u1eadn \\u0111\\u1ecbnh kh\\u00f4ng c\\u00f3 c\\u0103n c\\u1ee9 trong v\\u0103n b\\u1ea3n \\u0111\\u1ea7u v\\u00e0o. \\nK\\u1ebft qu\\u1ea3 t\\u1eeb API \\u0111\\u01b0\\u1ee3c y\\u00eau c\\u1ea7u \\u1edf d\\u1ea1ng JSON v\\u00e0 g\\u1eafn v\\u1edbi m\\u00e3 t\\u00e0i li\\u1ec7u, ch\\u01b0\\u01a1ng, \\nm\\u1ee5c, chunk t\\u01b0\\u01a1ng \\u1ee9ng. H\\u1ec7 th\\u1ed1ng ki\\u1ec3m tra c\\u1ea5u tr\\u00fac ph\\u1ea3n h\\u1ed3i tr\\u01b0\\u1edbc khi s\\u1eed d\\u1ee5ng \\ntrong nh\\u1eefng b\\u01b0\\u1edbc t\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":141,\"snippet\":\"k \\u0111\\u1ebfn API LLM c\\u00f9ng v\\u1edbi \\nprompt quy \\u0111\\u1ecbnh n\\u1ed9i dung c\\u1ea7n tr\\u00edch xu\\u1ea5t v\\u00e0 c\\u1ea5u tr\\u00fac \\u0111\\u1ea7u ra. Prompt y\\u00eau c\\u1ea7u m\\u00f4 \\nh\\u00ecnh t\\u1eadp trung v\\u00e0o nh\\u1eefng ph\\u1ea7n \\u0111\\u00e3 \\u0111\\u01b0\\u1ee3c tr\\u00ecnh b\\u00e0y trong chunk v\\u00e0 h\\u1ea1n ch\\u1ebf \\u0111\\u01b0a ra \\nnh\\u1eadn \\u0111\\u1ecbnh kh\\u00f4ng c\\u00f3 c\\u0103n c\\u1ee9 trong v\\u0103n b\\u1ea3n \\u0111\\u1ea7u v\\u00e0o. \\nK\\u1ebft qu\\u1ea3 t\\u1eeb API \\u0111\\u01b0\\u1ee3c y\\u00eau c\\u1ea7u \\u1edf d\\u1ea1ng JSON v\\u00e0 g\\u1eafn v\\u1edbi m\\u00e3 t\\u00e0i li\\u1ec7u, ch\\u01b0\\u01a1ng, \\nm\\u1ee5c, chunk t\\u01b0\\u01a1ng \\u1ee9ng. H\\u1ec7 th\\u1ed1ng ki\\u1ec3m tra c\\u1ea5u tr\\u00fac ph\\u1ea3n h\\u1ed3i tr\\u01b0\\u1edbc khi s\\u1eed d\\u1ee5ng \\ntrong nh\\u1eefng b\\u01b0\\u1edbc ti\\u1ebfp theo. Tr\\u01b0\\u1eddng h\\u1ee3p API tr\\u1ea3 v\\u1ec1 l\\u1ed7i, JSON kh\\u00f4ng h\\u1ee3p l\\u1ec7 ho\\u1eb7c \\nd\\u1eef li\\u1ec7u r\\u1ed7ng c\\u1ea7n \\u0111\\u01b0\\u1ee3c nh\\u1eadn di\\u1ec7n l\\u00e0 l\\u1ed7i x\\u1eed l\\u00fd, kh\\u00f4ng xem nh\\u01b0 m\\u1ed9t b\\u1ea3n t\\u00f3m t\\u1eaft th\\u00e0nh \\nc\\u00f4ng. \\nTh\\u00f4ng s\\u1ed1 c\\u1ea5u h\\u00ecnh nh\\u01b0 m\\u00e3 m\\u00f4 h\\u00ecnh, s\\u1ed1 token t\\u1ed1i \\u0111a, th\\u1eddi gian ch\\u1edd v\\u00e0 c\\u00e1ch \\ng\\u1ecdi API c\\u1ea7n \\u0111\\u01b0\\u1ee3c \\u0111\\u1ed1i chi\\u1ebfu v\\u1edbi m\\u00e3 ngu\\u1ed3n c\\u1ee7a b\\u1ea3n \\u0111ang ch\\u1ea1y. T\\u00e0i li\\u1ec7u b\\u00e1o c\\u00e1o ch\\u1ec9 \\ntr\\u00ecnh b\\u00e0y c\\u00e1c th\\u00f4ng s\\u1ed1 th\\u1ef1c s\\u1ef1 \\u0111\\u01b0\\u1ee3c s\\u1eed d\\u1ee5ng trong th\\u1eed nghi\\u1ec7m. \\n 1\\n\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":142,\"snippet\":\"6.5.6.   T\\u1ed5ng h\\u1ee3p k\\u1ebft qu\\u1ea3 b\\u1eb1ng Map\\u2013Reduce \\nSau khi c\\u00f3 c\\u00e1c b\\u1ea3n t\\u00f3m t\\u1eaft c\\u1ee5c b\\u1ed9, h\\u1ec7 th\\u1ed1ng gom c\\u00e1c k\\u1ebft qu\\u1ea3 thu\\u1ed9c c\\u00f9ng \\nm\\u1ed9t m\\u1ee5c v\\u00e0 th\\u1ef1c hi\\u1ec7n Reduce \\u0111\\u1ec3 lo\\u1ea1i b\\u1ecf c\\u00e1c \\u00fd tr\\u00f9ng l\\u1eb7p, \\u0111\\u1ed3ng th\\u1eddi t\\u1ea1o b\\u1ea3n t\\u00f3m t\\u1eaft \\nth\\u1ed1ng nh\\u1ea5t cho m\\u1ee5c \\u0111\\u00f3. C\\u00e1c b\\u1ea3n t\\u00f3m t\\u1eaft m\\u1ee5c \\u0111\\u01b0\\u1ee3c ti\\u1ebfp t\\u1ee5c t\\u1ed5ng h\\u1ee3p th\\u00e0nh ch\\u01b0\\u01a1ng. \\nCu\\u1ed1i c\\u00f9ng, nh\\u1eefng b\\u1ea3n t\\u00f3m t\\u1eaft ch\\u01b0\\u01a1ng \\u0111\\u01b0\\u1ee3c d\\u00f9ng \\u0111\\u1ec3 t\\u1ea1o n\\u1ed9i dung t\\u1ed5ng h\\u1ee3p cho \\nto\\u00e0n b\\u1ed9 b\\u00e1o c\\u00e1o. \\nHi\\u0300nh 6.17 Qu\\u00e1 tr\\u00ecnh t\\u1ed5ng h\\u1ee3p ph\\u00e2n c\\u1ea5p trong Reduce \\nTrong t\\u1eebng v\\u00f2ng Reduce, th\\u00f4ng tin v\\u1ec1 v\\u1ecb tr\\u00ed ch\\u01b0\\u01a1ng, m\\u1ee5c v\\u00e0 trang ngu\\u1ed3n \\nc\\u1ea7n \\u0111\\u01b0\\u1ee3c gi\\u1eef l\\u1ea1i \\u0111\\u1ec3 h\\u1ea1n ch\\u1ebf gh\\u00e9p nh\\u1ea7m n\\u1ed9i dung. N\\u1ebfu d\\u1eef li\\u1ec7u c\\u1ee7a m\\u1ed9t v\\u00f2ng v\\u1eabn \\nd\\u00e0i so v\\u1edbi gi\\u1edbi h\\u1ea1n \\u0111\\u1ea7u v\\u00e0o, h\\u1ec7 th\\u1ed1ng c\\u00f3 th\\u1ec3 chia th\\u00e0nh c\\u00e1c l\\u01b0\\u1ee3t t\\u1ed5ng h\\u1ee3p nh\\u1ecf h\\u01a1n. \\nK\\u1ebft qu\\u1ea3 cu\\u1ed1i c\\u00f9ng ch\\u1ec9 tr\\u00ecnh b\\u00e0y n\\u1ed9i dung \\u0111\\u01b0\\u1ee3c h\\u1ed7 tr\\u1ee3 b\\u1edfi t\\u00e0i li\\u1ec7u g\\u1ed1c. \\n6.5.7.   T\\u00edch h\\u1ee3p AI v\\u00e0o h\\u1ec7 th\\u1ed1ng \\nCh\\u1ee9c n\\u0103ng AI \\u0111\\u01b0\\u1ee3c t\\u00edch h\\u1ee3p v\\u1edbi quy tr\\u00ecnh n\\u1ed9p b\\u00e1o c\\u00e1o ti\\u1ebfn \\u0111\\u1ed9. K\\u1ebft qu\\u1ea3 x\\u1eed \\nl\\u00fd c\\u1ea7n g\\u1eafn v\\u1edbi \\u0111\\u00fang b\\u00e1o c\\u00e1o v\\u00e0 \\u0111\\u00fang phi\\u00ean b\\u1ea3n n\\u1ed9p, tr\\u00e1nh s\\u1eed d\\u1ee5ng b\\u1ea3n t\\u00f3m t\\u1eaft c\\u1ee7a \\nt\\u1ec7p c\\u0169 khi sinh vi\\u00ean \\u0111\\u00e3 c\\u1eadp nh\\u1eadt n\\u1ed9i dung. Tr\\u00ean giao di\\u1ec7n gi\\u1ea3ng vi\\u00ean, h\\u1ec7 th\\u1ed1ng hi\\u1ec3n \\nth\\u1ecb tr\\u1ea1ng th\\u00e1i \\u0111ang x\\u1eed l\\u00fd, \\u0111\\u00e3 ho\\u00e0n th\\u00e0nh ho\\u1eb7c l\\u1ed7i t\\u00f9y theo k\\u1ebft qu\\u1ea3 th\\u1ef1c t\\u1ebf. \\nGi\\u1ea3ng vi\\u00ean c\\u00f3 th\\u1ec3 \\u0111\\u1ecdc b\\u1ea3n t\\u00f3m t\\u1eaft \\u0111\\u1ec3 n\\u1eafm nh\\u1eefng \\u00fd ch\\u00ednh, sau \\u0111\\u00f3 m\\u1edf b\\u00e1o \\nc\\u00e1o g\\u1ed1c khi c\\u1ea7n \\u0111\\u1ed1i chi\\u1ebfu. Quy\\u1ec1n truy c\\u1eadp t\\u1ec7p v\\u00e0 k\\u1ebft qu\\u1ea3 t\\u00f3m t\\u1eaft ph\\u1ea3i tu\\u00e2n theo \\nph\\u00e2n quy\\u1ec1n c\\u1ee7a h\\u1ec7 th\\u1ed1ng. C\\u00e1c tr\\u01b0\\u1eddng d\\u1eef li\\u1ec7u d\\u00f9ng \\u0111\\u1ec3 l\\u01b0u k\\u1ebft qu\\u1ea3 c\\u1ea7n \\u0111\\u01b0\\u1ee3c ki\\u1ec3m \\ntra l\\u1ea1i so v\\u1edbi thi\\u1ebft k\\u1ebf c\\u01a1 s\\u1edf d\\u1eef li\\u1ec7u \\u1edf Ch\\u01b0\\u01a1ng 5, \\u0111\\u1eb7c bi\\u1ec7t khi y\\u00eau c\\u1ea7u \\u0111\\u1ea7u ra AI \\u0111\\u00e3 \\nthay \\u0111\\u1ed5i. \\n 1\\n\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":143,\"snippet\":\"Laravel \\u0111\\u01b0a t\\u00e1c v\\u1ee5 v\\u00e0o h\\u00e0ng \\u0111\\u1ee3i ai-reports, worker php artisan ai:work g\\u1ecdi \\nPython \\u0111\\u1ec3 x\\u1eed l\\u00fd PDF. Checkpoint v\\u00e0 k\\u1ebft qu\\u1ea3 trung gian \\u0111\\u01b0\\u1ee3c l\\u01b0u \\u0111\\u1ec3 ti\\u1ebfp t\\u1ee5c khi \\nl\\u01b0\\u1ee3t x\\u1eed l\\u00fd ph\\u1ea3i ch\\u1edd ho\\u1eb7c h\\u1ebft ng\\u00e2n s\\u00e1ch. K\\u1ebft qu\\u1ea3 h\\u1ee3p l\\u1ec7 \\u0111\\u01b0\\u1ee3c l\\u01b0u v\\u00e0o \\nkhoibaocaotiendo.TomTatJson v\\u00e0 ph\\u1ea7n t\\u1ed5ng quan v\\u00e0o TomTatAI, g\\u1eafn v\\u1edbi hash \\nfile v\\u00e0 phi\\u00ean b\\u1ea3n b\\u00e0i n\\u1ed9p. Tr\\u00ecnh duy\\u1ec7t ki\\u1ec3m tra tr\\u1ea1ng th\\u00e1i kho\\u1ea3ng 5 gi\\u00e2y khi t\\u00e1c v\\u1ee5 \\nc\\u00f2n ho\\u1ea1t \\u0111\\u1ed9ng v\\u00e0 c\\u1eadp nh\\u1eadt n\\u1ed9i dung m\\u1edbi, t\\u00f3m t\\u1eaft c\\u00f3 th\\u1ec3 ho\\u00e0n t\\u1ea5t tr\\u01b0\\u1edbc ph\\u1ea7n \\u0111\\u1ed1i \\nchi\\u1ebfu y\\u00eau c\\u1ea7u. \\nMinh ch\\u1ee9ng giao di\\u1ec7n \\u0111\\u01b0\\u1ee3c ch\\u1ee5p ng\\u00e0y 28\\/10\\/2026 b\\u1eb1ng t\\u00e0i kho\\u1ea3n gi\\u1ea3ng \\nvi\\u00ean h\\u01b0\\u1edbng d\\u1eabn v\\u00e0 sinh vi\\u00ean c\\u1ee7a nh\\u00f3m N13. Ch\\u1ec9 m\\u1edf c\\u00e1c k\\u1ebft qu\\u1ea3 \\u0111\\u00e3 l\\u01b0u \\u0111\\u1ec3 ki\\u1ec3m \\ntra quy\\u1ec1n xem, phi\\u00ean b\\u1ea3n v\\u00e0 d\\u1eabn ch\\u1ee9ng, kh\\u00f4ng thay nh\\u1eadn x\\u00e9t, tr\\u1ea1ng th\\u00e1i nghi\\u1ec7m \\nthu ho\\u1eb7c ch\\u1ea1y sinh AI m\\u1edbi trong b\\u01b0\\u1edbc ch\\u1ee5p \\u1ea3nh. \\nHi\\u0300nh 6.18 Gi\\u1ea3ng vi\\u00ean \\u0111\\u1ecdc t\\u00f3m t\\u1eaft ch\\u01b0\\u01a1ng v\\u00e0 m\\u1edf danh s\\u00e1ch d\\u1eabn ch\\u1ee9ng \\n 1\\n\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":144,\"snippet\":\"Hi\\u0300nh 6.19 M\\u1edf trang xem chi ti\\u1ebft d\\u1eabn ch\\u1ee9ng \\nHi\\u0300nh 6.20 Sinh vi\\u00ean xem l\\u1ecbch s\\u1eed phi\\u00ean b\\u1ea3n n\\u1ed9p v\\u00e0 k\\u1ebft qu\\u1ea3 \\u0111\\u00e3 l\\u01b0u \\n6.6.  TH\\u1eec NGHI\\u1ec6M V\\u00c0 \\u0110\\u00c1NH GI\\u00c1 K\\u1ebeT QU\\u1ea2 T\\u00d3M T\\u1eaeT \\n6.6.1. Thi\\u1ebft l\\u1eadp th\\u1eed nghi\\u1ec7m \\n\\u0110\\u1ec3 \\u0111\\u00e1nh gi\\u00e1 ch\\u1ee9c n\\u0103ng t\\u00f3m t\\u1eaft, nh\\u00f3m c\\u1ea7n l\\u1ef1a ch\\u1ecdn c\\u00e1c b\\u00e1o c\\u00e1o PDF c\\u00f3 \\u0111\\u1ed9 \\nd\\u00e0i v\\u00e0 c\\u00e1ch tr\\u00ecnh b\\u00e0y kh\\u00e1c nhau. T\\u00e0i li\\u1ec7u ng\\u1eafn \\u0111\\u01b0\\u1ee3c s\\u1eed d\\u1ee5ng \\u0111\\u1ec3 ki\\u1ec3m tra ho\\u1ea1t \\u0111\\u1ed9ng \\nc\\u01a1 b\\u1ea3n; t\\u00e0i li\\u1ec7u c\\u00f3 nhi\\u1ec1u ch\\u01b0\\u01a1ng, m\\u1ee5c d\\u00f9ng \\u0111\\u1ec3 ki\\u1ec3m tra kh\\u1ea3 n\\u0103ng nh\\u1eadn di\\u1ec7n c\\u1ea5u \\ntr\\u00fac; c\\u00f2n t\\u00e0i li\\u1ec7u d\\u00e0i d\\u00f9ng \\u0111\\u1ec3 ki\\u1ec3m tra qu\\u00e1 tr\\u00ecnh chia chunk v\\u00e0 t\\u1ed5ng h\\u1ee3p nhi\\u1ec1u c\\u1ea5p. \\n\\u0110\\u1ed1i v\\u1edbi m\\u1ed7i b\\u00e1o c\\u00e1o, ng\\u01b0\\u1eddi th\\u1eed nghi\\u1ec7m ghi nh\\u1eadn t\\u00ean ho\\u1eb7c m\\u00e3 t\\u1ec7p, s\\u1ed1 trang, \\ns\\u1ed1 m\\u1ee5c nh\\u1eadn di\\u1ec7n, s\\u1ed1 chunk, tr\\u1ea1ng th\\u00e1i x\\u1eed l\\u00fd v\\u00e0 th\\u1eddi gian ho\\u00e0n th\\u00e0nh. C\\u1ea7n th\\u1ed1ng \\n 1\\n\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":145,\"snippet\":\"nh\\u1ea5t th\\u1eddi \\u0111i\\u1ec3m b\\u1eaft \\u0111\\u1ea7u v\\u00e0 k\\u1ebft th\\u00fac ph\\u00e9p \\u0111o \\u0111\\u1ec3 c\\u00f3 th\\u1ec3 so s\\u00e1nh k\\u1ebft qu\\u1ea3 gi\\u1eefa c\\u00e1c l\\u1ea7n \\nch\\u1ea1y. T\\u1ec7p PDF d\\u1ea1ng scan \\u1ea3nh, n\\u1ebfu kh\\u00f4ng \\u0111\\u01b0\\u1ee3c h\\u1ed7 tr\\u1ee3 OCR, c\\u1ea7n \\u0111\\u01b0\\u1ee3c ghi nh\\u1eadn \\nnh\\u01b0 tr\\u01b0\\u1eddng h\\u1ee3p ri\\u00eang. \\nB\\u1ea3ng 6.8 Danh s\\u00e1ch t\\u00e0i li\\u1ec7u PDF d\\u00f9ng th\\u1eed nghi\\u1ec7m \\nS\\u1ed1 \\nChunk \\/ g\\u00f3i \\nM\\u00e3 PDF \\n\\u0110\\u1eb7c \\u0111i\\u1ec3m v\\u00e0 t\\u00ean t\\u00e0i li\\u1ec7u \\nS\\u1ed1 trang \\nm\\u1ee5c\\/v\\u00f9ng \\nMap \\nB\\u1ea3n th\\u1ea3o c\\u00f3 nhi\\u1ec1u m\\u1ee5c \\nPDF01 \\nch\\u01b0a \\u0111i\\u1ec1n n\\u1ed9i dung; \\n62 \\n61 \\n65 \\/ 15 \\nBaoCaoKhoaLuan.pdf \\nB\\u00e1o c\\u00e1o website qu\\u1ea3n l\\u00fd \\nkh\\u00f3a lu\\u1eadn, c\\u00f3 5 ch\\u01b0\\u01a1ng; \\nPDF02 \\nxay-dung-website-quan-\\n72 \\n72 \\n75 \\/ 9 \\nly-khoa-luan-tot-\\nnghiep\\u2026pdf \\nB\\u00e1o c\\u00e1o d\\u00e0i, nhi\\u1ec1u \\nPDF03 \\nch\\u01b0\\u01a1ng\\/m\\u1ee5c; 01_Quan \\n124 \\n234 \\n240 \\/ 23 \\nly do an_v4.pdf \\n6.6.2. K\\u1ebft qu\\u1ea3 x\\u1eed l\\u00fd \\nK\\u1ebft qu\\u1ea3 th\\u1ef1c nghi\\u1ec7m c\\u1ea7n \\u0111\\u01b0\\u1ee3c l\\u1ea5y t\\u1eeb c\\u00e1c l\\u1ea7n ch\\u1ea1y tr\\u00ean h\\u1ec7 th\\u1ed1ng. Th\\u1eddi gian \\nx\\u1eed l\\u00fd \\u0111\\u01b0\\u1ee3c t\\u00ednh theo c\\u00f9ng m\\u1ed9t m\\u1ed1c \\u0111o gi\\u1eefa c\\u00e1c t\\u00e0i li\\u1ec7u. Trong tr\\u01b0\\u1eddng h\\u1ee3p c\\u00f3 l\\u01b0u \\nth\\u1eddi gian cho t\\u1eebng giai \\u0111o\\u1ea1n, nh\\u00f3m c\\u00f3 th\\u1ec3 tr\\u00ecnh b\\u00e0y th\\u00eam th\\u1eddi gian tr\\u00edch xu\\u1ea5t, Map \\nv\\u00e0 Reduce \\u0111\\u1ec3 x\\u00e1c \\u0111\\u1ecbnh b\\u01b0\\u1edbc x\\u1eed l\\u00fd t\\u1ed1n nhi\\u1ec1u th\\u1eddi gian nh\\u1ea5t. \\nB\\u1ea3ng 6.9 K\\u1ebft qu\\u1ea3 x\\u1eed l\\u00fd c\\u00e1c b\\u00e1o c\\u00e1o PDF \\nM\\u00e3 PDF \\nTr\\u1ea1ng th\\u00e1i k\\u1ef9 thu\\u1eadt \\nTh\\u1eddi gian to\\u00e0n t\\u00e1c v\\u1ee5 \\n(gi\\u00e2y) \\nPh\\u1ea1m vi ph\\u00e9p \\u0111o \\nPDF01 \\nT\\u00f3m t\\u1eaft v\\u00e0 \\u0111\\u1ed1i chi\\u1ebfu \\u0111\\u00e3 ho\\u00e0n \\nt\\u1ea5t \\n382 \\n15\\/15 g\\u00f3i Map, 7 l\\u01b0\\u1ee3t \\nx\\u1eed l\\u00fd n\\u1ec1n, g\\u1ed3m th\\u1eddi \\ngian ch\\u1edd\\/ti\\u1ebfp t\\u1ee5c \\nPDF02 \\nT\\u00f3m t\\u1eaft v\\u00e0 \\u0111\\u1ed1i chi\\u1ebfu \\u0111\\u00e3 ho\\u00e0n \\nt\\u1ea5t \\n448 \\n9\\/9 g\\u00f3i Map, 5 l\\u01b0\\u1ee3t x\\u1eed \\nl\\u00fd n\\u1ec1n, g\\u1ed3m th\\u1eddi gian \\nch\\u1edd\\/ti\\u1ebfp t\\u1ee5c \\nPDF03 \\nT\\u00f3m t\\u1eaft v\\u00e0 \\u0111\\u1ed1i chi\\u1ebfu \\u0111\\u00e3 ho\\u00e0n \\nt\\u1ea5t \\n901 \\n23\\/23 g\\u00f3i Map, 11 \\nl\\u01b0\\u1ee3t x\\u1eed l\\u00fd n\\u1ec1n, g\\u1ed3m \\nth\\u1eddi gian ch\\u1edd\\/ti\\u1ebfp t\\u1ee5c \\n 1\\n\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":146,\"snippet\":\"Vi\\u1ec7c API ph\\u1ea3n h\\u1ed3i th\\u00e0nh c\\u00f4ng ch\\u1ec9 ch\\u1ee9ng minh t\\u00e1c v\\u1ee5 \\u0111\\u00e3 nh\\u1eadn \\u0111\\u01b0\\u1ee3c k\\u1ebft qu\\u1ea3 \\nk\\u1ef9 thu\\u1eadt, ch\\u01b0a \\u0111\\u1ee7 \\u0111\\u1ec3 k\\u1ebft lu\\u1eadn b\\u1ea3n t\\u00f3m t\\u1eaft ch\\u00ednh x\\u00e1c. Ch\\u1ea5t l\\u01b0\\u1ee3ng n\\u1ed9i dung c\\u1ea7n \\u0111\\u01b0\\u1ee3c \\nki\\u1ec3m tra b\\u1eb1ng c\\u00e1ch \\u0111\\u1ed1i chi\\u1ebfu v\\u1edbi b\\u00e1o c\\u00e1o g\\u1ed1c \\u1edf c\\u00e1c m\\u1ee5c ti\\u1ebfp theo. Nh\\u1eefng l\\u1ea7n ch\\u1ea1y \\nkh\\u00f4ng th\\u00e0nh c\\u00f4ng c\\u0169ng ph\\u1ea3i \\u0111\\u01b0\\u1ee3c ghi l\\u1ea1i k\\u00e8m b\\u01b0\\u1edbc ph\\u00e1t sinh l\\u1ed7i. \\nTh\\u1eddi gian quan s\\u00e1t l\\u1ea7n l\\u01b0\\u1ee3t l\\u00e0 382 gi\\u00e2y (6 ph\\u00fat 22 gi\\u00e2y), 448 gi\\u00e2y (7 ph\\u00fat \\n28 gi\\u00e2y) v\\u00e0 901 gi\\u00e2y (15 ph\\u00fat 01 gi\\u00e2y). Tr\\u01b0\\u1eddng processing_time_seconds trong \\nJSON ch\\u1ec9 ph\\u1ea3n \\u00e1nh l\\u01b0\\u1ee3t ti\\u1ebfn tr\\u00ecnh cu\\u1ed1i, n\\u00ean kh\\u00f4ng d\\u00f9ng thay cho t\\u1ed5ng th\\u1eddi gian \\nch\\u1edd. Ch\\u1ea1y l\\u1ea1i ri\\u00eang ph\\u00e2n \\u0111o\\u1ea1n v\\u00e0 \\u0111\\u00f3ng g\\u00f3i tr\\u00ean ba PDF m\\u1ea5t l\\u1ea7n l\\u01b0\\u1ee3t 1,079 v\\u00e0 1,060 \\nv\\u00e0 3,592 gi\\u00e2y trong m\\u1ed9t l\\u1ea7n \\u0111o, ch\\u01b0a \\u0111\\u1ea1i di\\u1ec7n cho hi\\u1ec7u n\\u0103ng trung b\\u00ecnh. Kh\\u00f4ng c\\u00f3 \\ns\\u1ed1 \\u0111o ri\\u00eang Map\\/Reduce \\u0111\\u00e1ng tin c\\u1eady cho c\\u00e1c l\\u01b0\\u1ee3t l\\u1ecbch s\\u1eed n\\u00e0y, n\\u00ean kh\\u00f4ng t\\u00e1ch gi\\u1ea3 \\nc\\u00e1c giai \\u0111o\\u1ea1n. \\n6.6.3. \\u0110\\u00e1nh gi\\u00e1 ch\\u1ea5t l\\u01b0\\u1ee3ng b\\u1ea3n t\\u00f3m t\\u1eaft \\nCh\\u1ea5t l\\u01b0\\u1ee3ng b\\u1ea3n t\\u00f3m t\\u1eaft \\u0111\\u01b0\\u1ee3c \\u0111\\u00e1nh gi\\u00e1 qua vi\\u1ec7c so s\\u00e1nh t\\u1eebng \\u00fd v\\u1edbi t\\u00e0i li\\u1ec7u \\nPDF. Ngo\\u00e0i y\\u00eau c\\u1ea7u n\\u1ed9i dung ng\\u1eafn g\\u1ecdn, nh\\u00f3m xem x\\u00e9t b\\u1ea3n t\\u00f3m t\\u1eaft c\\u00f3 \\u0111\\u00fang th\\u00f4ng \\ntin, ph\\u1ea3n \\u00e1nh \\u0111\\u01b0\\u1ee3c c\\u00e1c n\\u1ed9i dung ch\\u00ednh v\\u00e0 gi\\u1eef \\u0111\\u00fang c\\u1ea5u tr\\u00fac ch\\u01b0\\u01a1ng, m\\u1ee5c c\\u1ee7a b\\u00e1o \\nc\\u00e1o hay kh\\u00f4ng. \\n- T\\u00ednh ch\\u00ednh x\\u00e1c: \\u00fd \\u0111\\u01b0\\u1ee3c t\\u00f3m t\\u1eaft c\\u00f3 xu\\u1ea5t hi\\u1ec7n trong t\\u00e0i li\\u1ec7u g\\u1ed1c v\\u00e0 \\nkh\\u00f4ng l\\u00e0m thay \\u0111\\u1ed5i \\u00fd ngh\\u0129a. \\n- M\\u1ee9c \\u0111\\u1ed9 bao qu\\u00e1t: c\\u00e1c n\\u1ed9i dung quan tr\\u1ecdng c\\u1ee7a m\\u1ed9t m\\u1ee5c c\\u00f3 \\u0111\\u01b0\\u1ee3c \\nth\\u1ec3 hi\\u1ec7n \\u0111\\u1ea7y \\u0111\\u1ee7. \\n- \\u0110\\u00fang c\\u1ea5u tr\\u00fac: k\\u1ebft qu\\u1ea3 kh\\u00f4ng g\\u00e1n n\\u1ed9i dung sang sai ch\\u01b0\\u01a1ng ho\\u1eb7c \\nm\\u1ee5c. \\n- Kh\\u1ea3 n\\u0103ng \\u0111\\u1ed1i chi\\u1ebfu: ng\\u01b0\\u1eddi \\u0111\\u1ecdc c\\u00f3 th\\u1ec3 t\\u00ecm l\\u1ea1i n\\u1ed9i dung ngu\\u1ed3n \\ntrong PDF. \\n- T\\u00ednh d\\u1ec5 \\u0111\\u1ecdc: c\\u00e2u v\\u0103n r\\u00f5 r\\u00e0ng, tr\\u00e1nh l\\u1eb7p th\\u00f4ng tin v\\u00e0 kh\\u00f4ng l\\u1eabn \\nchu\\u1ed7i l\\u1ed7i ho\\u1eb7c JSON ch\\u01b0a x\\u1eed l\\u00fd \\nB\\u1ea3ng 6.10 Phi\\u1ebfu \\u0111\\u00e1nh gi\\u00e1 ch\\u1ea5t l\\u01b0\\u1ee3ng b\\u1ea3n t\\u00f3m t\\u1eaft \\nTi\\u00eau ch\\u00ed \\nC\\u00e1ch \\u0111\\u00e1nh gi\\u00e1 \\nK\\u1ebft qu\\u1ea3 tr\\u00ean ph\\u1ea1m vi \\u0111\\u00e3 ki\\u1ec3m tra \\nCh\\u00ednh x\\u00e1c \\n\\u0110\\u1ecdc 12 \\u0111o\\u1ea1n v\\u00e0 ng\\u1eef c\\u1ea3nh \\nngu\\u1ed3n t\\u01b0\\u01a1ng \\u1ee9ng \\n9 \\u0111o\\u1ea1n h\\u1ed7 tr\\u1ee3 r\\u00f5, 3 \\u0111o\\u1ea1n c\\u1ea7n di\\u1ec5n \\u0111\\u1ea1t \\nth\\u1eadn tr\\u1ecdng v\\u00ec ngu\\u1ed3n ch\\u1ec9 c\\u00f3 ti\\u00eau \\u0111\\u1ec1\\/l\\u1eddi