\u1eadn \\nt\\u1ed1t nghi\\u1ec7p t\\u1eeb vi\\u1ec7c thi\\u1ebft l\\u1eadp m\\u00f4i tr\\u01b0\\u1eddng ph\\u00e1t tri\\u1ec3n, c\\u1ea5u h\\u00ecnh ph\\u1ea7n c\\u1ee9ng v\\u00e0 ph\\u1ea7n \\nm\\u1ec1m \\u0111\\u1ebfn tri\\u1ec3n khai c\\u01a1 s\\u1edf d\\u1eef li\\u1ec7u v\\u00e0 x\\u00e2y d\\u1ef1ng c\\u00e1c ch\\u1ee9c n\\u0103ng ch\\u00ednh. H\\u1ec7 th\\u1ed1ng \\n\\u0111\\u01b0\\u1ee3c ph\\u00e1t tri\\u1ec3n tr\\u00ean n\\u1ec1n t\\u1ea3ng PHP v\\u00e0 Laravel Framework, s\\u1eed d\\u1ee5ng MySQL \\u0111\\u1ec3 \\nqu\\u1ea3n l\\u00fd d\\u1eef li\\u1ec7u, k\\u1ebft h\\u1ee3p Blade, HTML, CSS v\\u00e0 JavaScript \\u0111\\u1ec3 x\\u00e2y d\\u1ef1ng giao di\\u1ec7n \\nng\\u01b0\\u1eddi d\\u00f9ng. \\nB\\u00ean c\\u1ea1nh vi\\u1ec7c tri\\u1ec3n khai c\\u01a1 s\\u1edf d\\u1eef li\\u1ec7u v\\u1edbi c\\u00e1c b\\u1ea3ng, kh\\u00f3a ch\\u00ednh, kh\\u00f3a ngo\\u1ea1i \\nv\\u00e0 d\\u1eef li\\u1ec7u m\\u1eabu, ch\\u01b0\\u01a1ng \\u0111\\u00e3 th\\u1ef1c hi\\u1ec7n x\\u00e2y d\\u1ef1ng c\\u00e1c ch\\u1ee9c n\\u0103ng ch\\u00ednh nh\\u01b0 \\u0111\\u0103ng \\nnh\\u1eadp, l\\u1eadp k\\u1ebf ho\\u1ea1ch kh\\u00f3a lu\\u1eadn, qu\\u1ea3n l\\u00fd \\u0111\\u1ec1 t\\u00e0i, \\u0111\\u0103ng k\\u00fd \\u0111\\u1ec1 t\\u00e0i, qu\\u1ea3n l\\u00fd ti\\u1ebfn \\u0111\\u1ed9, qu\\u1ea3n \\nl\\u00fd b\\u1ea3o v\\u1ec7 v\\u00e0 th\\u1ed1ng k\\u00ea. C\\u00e1c ch\\u1ee9c n\\u0103ng \\u0111\\u01b0\\u1ee3c tri\\u1ec3n khai d\\u1ef1a tr\\u00ean thi\\u1ebft k\\u1ebf \\u0111\\u00e3 tr\\u00ecnh \\nb\\u00e0y \\u1edf ch\\u01b0\\u01a1ng tr\\u01b0\\u1edbc, b\\u1ea3o \\u0111\\u1ea3m s\\u1ef1 li\\u00ean k\\u1ebft gi\\u1eefa d\\u1eef li\\u1ec7u v\\u00e0 c\\u00e1c quy tr\\u00ecnh nghi\\u1ec7p v\\u1ee5 \\nc\\u1ee7a h\\u1ec7 th\\u1ed1ng. \\n 1\\n\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":121,\"snippet\":\"CH\\u01af\\u01a0NG 6:  TH\\u1eec NGHI\\u1ec6M V\\u00c0 TRI\\u1ec2N KHAI \\n6.1. GI\\u1edaI THI\\u1ec6U \\nSau khi ho\\u00e0n th\\u00e0nh qu\\u00e1 tr\\u00ecnh ph\\u00e2n t\\u00edch, thi\\u1ebft k\\u1ebf v\\u00e0 c\\u00e0i \\u0111\\u1eb7t, h\\u1ec7 th\\u1ed1ng qu\\u1ea3n l\\u00fd \\nc\\u00f4ng t\\u00e1c kh\\u00f3a lu\\u1eadn t\\u1ed1t nghi\\u1ec7p \\u0111\\u01b0\\u1ee3c ti\\u1ebfn h\\u00e0nh th\\u1eed nghi\\u1ec7m nh\\u1eb1m \\u0111\\u00e1nh gi\\u00e1 m\\u1ee9c \\u0111\\u1ed9 \\n\\u0111\\u00e1p \\u1ee9ng c\\u00e1c y\\u00eau c\\u1ea7u nghi\\u1ec7p v\\u1ee5 v\\u00e0 m\\u1ee5c ti\\u00eau \\u0111\\u00e3 \\u0111\\u1ec1 ra. N\\u1ed9i dung th\\u1eed nghi\\u1ec7m t\\u1eadp \\ntrung v\\u00e0o c\\u00e1c ch\\u1ee9c n\\u0103ng ch\\u00ednh c\\u1ee7a h\\u1ec7 th\\u1ed1ng d\\u00e0nh cho ba nh\\u00f3m ng\\u01b0\\u1eddi d\\u00f9ng g\\u1ed3m \\nGi\\u00e1o v\\u1ee5, Gi\\u1ea3ng vi\\u00ean v\\u00e0 Sinh vi\\u00ean. \\nB\\u00ean c\\u1ea1nh vi\\u1ec7c ki\\u1ec3m tra ho\\u1ea1t \\u0111\\u1ed9ng c\\u1ee7a c\\u00e1c ch\\u1ee9c n\\u0103ng qu\\u1ea3n l\\u00fd, qu\\u00e1 tr\\u00ecnh th\\u1eed \\nnghi\\u1ec7m c\\u0169ng xem x\\u00e9t kh\\u1ea3 n\\u0103ng ph\\u1ed1i h\\u1ee3p gi\\u1eefa c\\u00e1c nghi\\u1ec7p v\\u1ee5 nh\\u01b0 l\\u1eadp k\\u1ebf ho\\u1ea1ch \\nkh\\u00f3a lu\\u1eadn, qu\\u1ea3n l\\u00fd danh s\\u00e1ch sinh vi\\u00ean \\u0111\\u1ee7 \\u0111i\\u1ec1u ki\\u1ec7n, qu\\u1ea3n l\\u00fd v\\u00e0 \\u0111\\u0103ng k\\u00fd \\u0111\\u1ec1 t\\u00e0i, \\ntheo d\\u00f5i ti\\u1ebfn \\u0111\\u1ed9, qu\\u1ea3n l\\u00fd h\\u1ed3 s\\u01a1 b\\u1ea3o v\\u1ec7, t\\u1ed5 ch\\u1ee9c h\\u1ed9i \\u0111\\u1ed3ng, ch\\u1ea5m \\u0111i\\u1ec3m v\\u00e0 th\\u1ed1ng k\\u00ea \\nk\\u1ebft qu\\u1ea3. \\u0110\\u00e2y l\\u00e0 c\\u00e1c quy tr\\u00ecnh \\u0111\\u00e3 \\u0111\\u01b0\\u1ee3c x\\u00e1c \\u0111\\u1ecbnh trong qu\\u00e1 tr\\u00ecnh kh\\u1ea3o s\\u00e1t v\\u00e0 ph\\u00e2n \\nt\\u00edch h\\u1ec7 th\\u1ed1ng. \\nNgo\\u00e0i c\\u00e1c ch\\u1ee9c n\\u0103ng qu\\u1ea3n l\\u00fd truy\\u1ec1n th\\u1ed1ng, h\\u1ec7 th\\u1ed1ng c\\u00f2n t\\u00edch h\\u1ee3p ch\\u1ee9c n\\u0103ng \\nh\\u1ed7 tr\\u1ee3 x\\u1eed l\\u00fd b\\u00e1o c\\u00e1o ti\\u1ebfn \\u0111\\u1ed9 b\\u1eb1ng m\\u00f4 h\\u00ecnh ng\\u00f4n ng\\u1eef l\\u1edbn (LLM). Khi sinh vi\\u00ean \\nn\\u1ed9p b\\u00e1o c\\u00e1o, h\\u1ec7 th\\u1ed1ng c\\u00f3 th\\u1ec3 x\\u1eed l\\u00fd n\\u1ed9i dung b\\u00e1o c\\u00e1o v\\u00e0 t\\u1ea1o b\\u1ea3n t\\u00f3m t\\u1eaft nh\\u1eb1m h\\u1ed7 \\ntr\\u1ee3 gi\\u1ea3ng vi\\u00ean nhanh ch\\u00f3ng n\\u1eafm b\\u1eaft t\\u00ecnh h\\u00ecnh th\\u1ef1c hi\\u1ec7n kh\\u00f3a lu\\u1eadn. \\n6.2. M\\u1ee4C TI\\u00caU TH\\u1eec NGHI\\u1ec6M V\\u00c0 TRI\\u1ec2N KHAI \\n6.2.1.   M\\u1ee5c ti\\u00eau th\\u1eed nghi\\u1ec7m h\\u1ec7 th\\u1ed1ng \\nM\\u1ee5c ti\\u00eau th\\u1eed nghi\\u1ec7m h\\u1ec7 th\\u1ed1ng l\\u00e0 x\\u00e1c \\u0111\\u1ecbnh c\\u00e1c ch\\u1ee9c n\\u0103ng \\u0111\\u00e3 x\\u00e2y d\\u1ef1ng c\\u00f3 \\nx\\u1eed l\\u00fd \\u0111\\u00fang d\\u1eef li\\u1ec7u \\u0111\\u1ea7u v\\u00e0o, tu\\u00e2n th\\u1ee7 \\u0111i\\u1ec1u ki\\u1ec7n nghi\\u1ec7p v\\u1ee5 v\\u00e0 tr\\u1ea3 v\\u1ec1 k\\u1ebft qu\\u1ea3 ph\\u00f9 \\nh\\u1ee3p v\\u1edbi t\\u1eebng nh\\u00f3m ng\\u01b0\\u1eddi d\\u00f9ng hay kh\\u00f4ng. C\\u00e1c tr\\u01b0\\u1eddng h\\u1ee3p th\\u1eed nghi\\u1ec7m \\u0111\\u01b0\\u1ee3c l\\u1ef1a \\nch\\u1ecdn t\\u1eeb lu\\u1ed3ng ch\\u00ednh, lu\\u1ed3ng ph\\u1ee5 v\\u00e0 nh\\u1eefng \\u0111i\\u1ec1u ki\\u1ec7n r\\u00e0ng bu\\u1ed9c trong b\\u1ea3n \\u0111\\u1eb7c t\\u1ea3 \\nUse Case. \\n- Ki\\u1ec3m tra \\u0111\\u0103ng nh\\u1eadp, ph\\u00e2n quy\\u1ec1n v\\u00e0 c\\u00e1c thao t\\u00e1c theo vai tr\\u00f2 \\nng\\u01b0\\u1eddi d\\u00f9ng. \\n- Ki\\u1ec3m tra quy tr\\u00ecnh l\\u1eadp k\\u1ebf ho\\u1ea1ch, qu\\u1ea3n l\\u00fd \\u0111\\u1ec1 t\\u00e0i, \\u0111\\u0103ng k\\u00fd \\u0111\\u1ec1 t\\u00e0i \\nv\\u00e0 theo d\\u00f5i ti\\u1ebfn \\u0111\\u1ed9. \\n- Ki\\u1ec3m tra c\\u00e1c tr\\u01b0\\u1eddng h\\u1ee3p d\\u1eef li\\u1ec7u kh\\u00f4ng h\\u1ee3p l\\u1ec7, \\u0111\\u1ec1 t\\u00e0i h\\u1ebft ch\\u1ec9 \\nti\\u00eau ho\\u1eb7c thao t\\u00e1c ngo\\u00e0i \\u0111i\\u1ec1u ki\\u1ec7n cho ph\\u00e9p. \\n- Ki\\u1ec3m tra vi\\u1ec7c ti\\u1ebfp nh\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":121,\"snippet\":\"\\u1ec7m \\u0111\\u01b0\\u1ee3c l\\u1ef1a \\nch\\u1ecdn t\\u1eeb lu\\u1ed3ng ch\\u00ednh, lu\\u1ed3ng ph\\u1ee5 v\\u00e0 nh\\u1eefng \\u0111i\\u1ec1u ki\\u1ec7n r\\u00e0ng bu\\u1ed9c trong b\\u1ea3n \\u0111\\u1eb7c t\\u1ea3 \\nUse Case. \\n- Ki\\u1ec3m tra \\u0111\\u0103ng nh\\u1eadp, ph\\u00e2n quy\\u1ec1n v\\u00e0 c\\u00e1c thao t\\u00e1c theo vai tr\\u00f2 \\nng\\u01b0\\u1eddi d\\u00f9ng. \\n- Ki\\u1ec3m tra quy tr\\u00ecnh l\\u1eadp k\\u1ebf ho\\u1ea1ch, qu\\u1ea3n l\\u00fd \\u0111\\u1ec1 t\\u00e0i, \\u0111\\u0103ng k\\u00fd \\u0111\\u1ec1 t\\u00e0i \\nv\\u00e0 theo d\\u00f5i ti\\u1ebfn \\u0111\\u1ed9. \\n- Ki\\u1ec3m tra c\\u00e1c tr\\u01b0\\u1eddng h\\u1ee3p d\\u1eef li\\u1ec7u kh\\u00f4ng h\\u1ee3p l\\u1ec7, \\u0111\\u1ec1 t\\u00e0i h\\u1ebft ch\\u1ec9 \\nti\\u00eau ho\\u1eb7c thao t\\u00e1c ngo\\u00e0i \\u0111i\\u1ec1u ki\\u1ec7n cho ph\\u00e9p. \\n- Ki\\u1ec3m tra vi\\u1ec7c ti\\u1ebfp nh\\u1eadn h\\u1ed3 s\\u01a1 b\\u1ea3o v\\u1ec7, t\\u1ed5 ch\\u1ee9c h\\u1ed9i \\u0111\\u1ed3ng, ch\\u1ea5m \\n\\u0111i\\u1ec3m v\\u00e0 th\\u1ed1ng k\\u00ea theo ph\\u1ea1m vi \\u0111\\u00e3 tri\\u1ec3n khai. \\n 1\\n\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":122,\"snippet\":\"- Ghi nh\\u1eadn k\\u1ebft qu\\u1ea3 th\\u1ef1c t\\u1ebf \\u0111\\u1ec3 x\\u00e1c \\u0111\\u1ecbnh nh\\u1eefng ch\\u1ee9c n\\u0103ng \\u0111\\u1ea1t y\\u00eau \\nc\\u1ea7u v\\u00e0 nh\\u1eefng \\u0111i\\u1ec3m c\\u1ea7n c\\u1ea3i thi\\u1ec7n. \\nM\\u1ed7i tr\\u01b0\\u1eddng h\\u1ee3p th\\u1eed nghi\\u1ec7m c\\u1ea7n c\\u00f3 \\u0111i\\u1ec1u ki\\u1ec7n \\u0111\\u1ea7u v\\u00e0o, c\\u00e1c b\\u01b0\\u1edbc thao t\\u00e1c, \\nk\\u1ebft qu\\u1ea3 mong \\u0111\\u1ee3i v\\u00e0 k\\u1ebft qu\\u1ea3 quan s\\u00e1t \\u0111\\u01b0\\u1ee3c. Ch\\u1ee9c n\\u0103ng ch\\u1ec9 \\u0111\\u01b0\\u1ee3c \\u0111\\u00e1nh gi\\u00e1 l\\u00e0 \\u0111\\u1ea1t \\nkhi k\\u1ebft qu\\u1ea3 th\\u1ef1c t\\u1ebf ph\\u00f9 h\\u1ee3p v\\u1edbi y\\u00eau c\\u1ea7u \\u0111\\u00e3 x\\u00e1c \\u0111\\u1ecbnh \\n6.2.2.   M\\u1ee5c ti\\u00eau nghi\\u00ean c\\u1ee9u v\\u00e0 th\\u1eed nghi\\u1ec7m AI \\n\\u0110\\u1ed1i v\\u1edbi ch\\u1ee9c n\\u0103ng AI, m\\u1ee5c ti\\u00eau th\\u1eed nghi\\u1ec7m l\\u00e0 \\u0111\\u00e1nh gi\\u00e1 kh\\u1ea3 n\\u0103ng tr\\u00edch \\nxu\\u1ea5t n\\u1ed9i dung t\\u1eeb b\\u00e1o c\\u00e1o PDF, ph\\u00e2n \\u0111o\\u1ea1n t\\u00e0i li\\u1ec7u theo ch\\u01b0\\u01a1ng, m\\u1ee5c v\\u00e0 t\\u1ea1o b\\u1ea3n \\nt\\u00f3m t\\u1eaft b\\u1eb1ng ph\\u01b0\\u01a1ng ph\\u00e1p Map\\u2013Reduce. Ngo\\u00e0i vi\\u1ec7c ki\\u1ec3m tra API tr\\u1ea3 v\\u1ec1 d\\u1eef li\\u1ec7u, \\nnh\\u00f3m c\\u1ea7n \\u0111\\u00e1nh gi\\u00e1 m\\u1ee9c \\u0111\\u1ed9 ch\\u00ednh x\\u00e1c v\\u00e0 kh\\u1ea3 n\\u0103ng ki\\u1ec3m ch\\u1ee9ng th\\u00f4ng tin trong \\nb\\u1ea3n t\\u00f3m t\\u1eaft. \\n- Nh\\u1eadn di\\u1ec7n c\\u1ea5u tr\\u00fac ch\\u01b0\\u01a1ng, m\\u1ee5c \\u0111\\u01b0\\u1ee3c \\u0111\\u00e1nh s\\u1ed1 X.X v\\u00e0 chia nh\\u1ecf \\nn\\u1ed9i dung d\\u00e0i th\\u00e0nh nhi\\u1ec1u chunk. \\n- Gi\\u1eef th\\u00f4ng tin v\\u1ec1 ch\\u01b0\\u01a1ng, m\\u1ee5c v\\u00e0 trang ngu\\u1ed3n c\\u1ee7a t\\u1eebng chunk. \\n- T\\u1ea1o c\\u00e1c b\\u1ea3n t\\u00f3m t\\u1eaft c\\u1ee5c b\\u1ed9 \\u1edf giai \\u0111o\\u1ea1n Map v\\u00e0 t\\u1ed5ng h\\u1ee3p theo \\nm\\u1ee5c, ch\\u01b0\\u01a1ng v\\u00e0 to\\u00e0n b\\u1ed9 t\\u00e0i li\\u1ec7u \\u1edf giai \\u0111o\\u1ea1n Reduce. \\n- Ki\\u1ec3m tra k\\u1ebft qu\\u1ea3 JSON tr\\u01b0\\u1edbc khi l\\u01b0u v\\u00e0 hi\\u1ec3n th\\u1ecb. \\n- \\u0110\\u00e1nh gi\\u00e1 t\\u00ednh ch\\u00ednh x\\u00e1c, m\\u1ee9c \\u0111\\u1ed9 bao qu\\u00e1t, c\\u1ea5u tr\\u00fac v\\u00e0 th\\u1eddi gian \\nx\\u1eed l\\u00fd c\\u1ee7a b\\u1ea3n t\\u00f3m t\\u1eaft. \\nK\\u1ebft qu\\u1ea3 AI ch\\u1ec9 \\u0111\\u00f3ng vai tr\\u00f2 h\\u1ed7 tr\\u1ee3 gi\\u1ea3ng vi\\u00ean \\u0111\\u1ecdc b\\u00e1o c\\u00e1o; vi\\u1ec7c \\u0111\\u00e1nh gi\\u00e1 \\nti\\u1ebfn \\u0111\\u1ed9 v\\u00e0 x\\u00e1c nh\\u1eadn n\\u1ed9i dung th\\u1ef1c t\\u1ebf v\\u1eabn do gi\\u1ea3ng vi\\u00ean th\\u1ef1c hi\\u1ec7n \\n6.3. TRI\\u1ec2N KHAI M\\u00d4I TR\\u01af\\u1edcNG TH\\u1eec NGHI\\u1ec6M \\n6.3.1.  M\\u00f4i tr\\u01b0\\u1eddng tri\\u1ec3n khai \\nM\\u00f4i tr\\u01b0\\u1eddng th\\u1eed nghi\\u1ec7m \\u0111\\u01b0\\u1ee3c x\\u00e2y d\\u1ef1ng d\\u1ef1a tr\\u00ean c\\u1ea5u h\\u00ecnh c\\u00e0i \\u0111\\u1eb7t \\u1edf \\nCh\\u01b0\\u01a1ng 5. Theo b\\u00e1o c\\u00e1o thi\\u1ebft k\\u1ebf, h\\u1ec7 th\\u1ed1ng s\\u1eed d\\u1ee5ng PHP v\\u00e0 Laravel \\u1edf ph\\u00eda m\\u00e1y \\nch\\u1ee7, MySQL \\u0111\\u1ec3 qu\\u1ea3n l\\u00fd d\\u1eef li\\u1ec7u, c\\u00f9ng Blade, HTML, CSS v\\u00e0 JavaScript \\u0111\\u1ec3 x\\u00e2y \\nd\\u1ef1ng giao di\\u1ec7n ng\\u01b0\\u1eddi d\\u00f9ng. Th\\u00f4ng tin phi\\u00ean b\\u1ea3n c\\u1ee5 th\\u1ec3 c\\u1ea7n \\u0111\\u01b0\\u1ee3c x\\u00e1c nh\\u1eadn theo \\nm\\u00e3 ngu\\u1ed3n v\\u00e0 m\\u00e1y th\\u1ef1c hi\\u1ec7n th\\u1eed nghi\\u1ec7m. \\n\\u0110\\u1ed1i v\\u1edbi ch\\u1ee9c n\\u0103ng AI, m\\u00f4i tr\\u01b0\\u1eddng c\\u1ea7n c\\u00f3 th\\u00e0nh ph\\u1ea7n \\u0111\\u1ecdc t\\u1ec7p PDF, kh\\u1ea3 \\nn\\u0103ng k\\u1ebft n\\u1ed1i \\u0111\\u1ebfn API c\\u1ee7a m\\u00f4 h\\u00ecnh ng\\u00f4n ng\\u1eef l\\u1edbn v\\u00e0 c\\u1ea5u h\\u00ecnh l\\u01b0u tr\\u1eef k\\u1ebft qu\\u1ea3. C\\u00e1c \\nkh\\u00f3a truy c\\u1eadp d\\u1ecbch v\\u1ee5 \\u0111\\u01b0\\u1ee3\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":122,\"snippet\":\"\\u1eed d\\u1ee5ng PHP v\\u00e0 Laravel \\u1edf ph\\u00eda m\\u00e1y \\nch\\u1ee7, MySQL \\u0111\\u1ec3 qu\\u1ea3n l\\u00fd d\\u1eef li\\u1ec7u, c\\u00f9ng Blade, HTML, CSS v\\u00e0 JavaScript \\u0111\\u1ec3 x\\u00e2y \\nd\\u1ef1ng giao di\\u1ec7n ng\\u01b0\\u1eddi d\\u00f9ng. Th\\u00f4ng tin phi\\u00ean b\\u1ea3n c\\u1ee5 th\\u1ec3 c\\u1ea7n \\u0111\\u01b0\\u1ee3c x\\u00e1c nh\\u1eadn theo \\nm\\u00e3 ngu\\u1ed3n v\\u00e0 m\\u00e1y th\\u1ef1c hi\\u1ec7n th\\u1eed nghi\\u1ec7m. \\n\\u0110\\u1ed1i v\\u1edbi ch\\u1ee9c n\\u0103ng AI, m\\u00f4i tr\\u01b0\\u1eddng c\\u1ea7n c\\u00f3 th\\u00e0nh ph\\u1ea7n \\u0111\\u1ecdc t\\u1ec7p PDF, kh\\u1ea3 \\nn\\u0103ng k\\u1ebft n\\u1ed1i \\u0111\\u1ebfn API c\\u1ee7a m\\u00f4 h\\u00ecnh ng\\u00f4n ng\\u1eef l\\u1edbn v\\u00e0 c\\u1ea5u h\\u00ecnh l\\u01b0u tr\\u1eef k\\u1ebft qu\\u1ea3. C\\u00e1c \\nkh\\u00f3a truy c\\u1eadp d\\u1ecbch v\\u1ee5 \\u0111\\u01b0\\u1ee3c qu\\u1ea3n l\\u00fd \\u1edf ph\\u00eda m\\u00e1y ch\\u1ee7, kh\\u00f4ng ghi tr\\u1ef1c ti\\u1ebfp v\\u00e0o t\\u00e0i \\nli\\u1ec7u ho\\u1eb7c \\u0111\\u01b0a ra giao di\\u1ec7n. \\n 1\\n\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":123,\"snippet\":\"B\\u1ea3ng 6.1 M\\u00f4i tr\\u01b0\\u1eddng ph\\u1ea7n m\\u1ec1m th\\u1eed nghi\\u1ec7m \\nTh\\u00e0nh ph\\u1ea7n \\nC\\u1ea5u h\\u00ecnh \\nTh\\u00f4ng tin c\\u1ea7n x\\u00e1c nh\\u1eadn \\nNg\\u00f4n ng\\u1eef, framework \\nPHP 8.3; Laravel 13.x \\nC\\u01a1 s\\u1edf d\\u1eef li\\u1ec7u \\nMySQL 8.0 \\nGiao di\\u1ec7n \\nBlade, Vite, JavaScript \\nPDF \\nTh\\u01b0 vi\\u1ec7n tr\\u00edch xu\\u1ea5t v\\u0103n \\nb\\u1ea3n \\nPyMuPDF, Python \\nLLM \\nGemini API \\nGemini-3.5-flash-lite \\n6.3.2.  D\\u1eef li\\u1ec7u th\\u1eed nghi\\u1ec7m \\nD\\u1eef li\\u1ec7u th\\u1eed nghi\\u1ec7m \\u0111\\u01b0\\u1ee3c chia th\\u00e0nh hai nh\\u00f3m. Nh\\u00f3m d\\u1eef li\\u1ec7u nghi\\u1ec7p v\\u1ee5 \\ng\\u1ed3m h\\u1ecdc k\\u1ef3, gi\\u00e1o v\\u1ee5, gi\\u1ea3ng vi\\u00ean, sinh vi\\u00ean, \\u0111\\u1ec1 t\\u00e0i, phi\\u1ebfu \\u0111\\u0103ng k\\u00fd, b\\u00e1o c\\u00e1o ti\\u1ebfn \\u0111\\u1ed9, \\nh\\u1ed3 s\\u01a1 b\\u1ea3o v\\u1ec7 v\\u00e0 k\\u1ebft qu\\u1ea3. Nh\\u00f3m d\\u1eef li\\u1ec7u AI g\\u1ed3m c\\u00e1c b\\u00e1o c\\u00e1o PDF m\\u00e0 nh\\u00f3m c\\u00f3 \\nquy\\u1ec1n s\\u1eed d\\u1ee5ng \\u0111\\u1ec3 ki\\u1ec3m tra quy tr\\u00ecnh tr\\u00edch xu\\u1ea5t v\\u00e0 t\\u00f3m t\\u1eaft n\\u1ed9i dung. \\nD\\u1eef li\\u1ec7u nghi\\u1ec7p v\\u1ee5 c\\u1ea7n bao g\\u1ed3m c\\u1ea3 tr\\u01b0\\u1eddng h\\u1ee3p h\\u1ee3p l\\u1ec7 v\\u00e0 kh\\u00f4ng h\\u1ee3p l\\u1ec7. \\u0110\\u1ed1i \\nv\\u1edbi PDF, n\\u00ean ch\\u1ecdn t\\u00e0i li\\u1ec7u ng\\u1eafn, t\\u00e0i li\\u1ec7u c\\u00f3 nhi\\u1ec1u ch\\u01b0\\u01a1ng m\\u1ee5c v\\u00e0 t\\u00e0i li\\u1ec7u d\\u00e0i \\u0111\\u1ec3 \\n\\u0111\\u00e1nh gi\\u00e1 kh\\u1ea3 n\\u0103ng chia chunk v\\u00e0 t\\u1ed5ng h\\u1ee3p k\\u1ebft qu\\u1ea3. Khi s\\u1eed d\\u1ee5ng b\\u00e1o c\\u00e1o c\\u00f3 th\\u00f4ng \\ntin c\\u00e1 nh\\u00e2n, nh\\u00f3m c\\u1ea7n ki\\u1ec3m so\\u00e1t d\\u1eef li\\u1ec7u tr\\u01b0\\u1edbc khi g\\u1eedi \\u0111\\u1ebfn d\\u1ecbch v\\u1ee5 AI \\nC\\u00f2n c\\u00e1i b\\u1ea3ng n\\u1eefa  \\n6.4. TH\\u1eec NGHI\\u1ec6M C\\u00c1C QUY TR\\u00ccNH NGHI\\u1ec6P V\\u1ee4 \\nC\\u00e1c ch\\u1ee9c n\\u0103ng nghi\\u1ec7p v\\u1ee5 \\u0111\\u01b0\\u1ee3c ki\\u1ec3m tra theo ph\\u01b0\\u01a1ng ph\\u00e1p ki\\u1ec3m th\\u1eed h\\u1ed9p \\n\\u0111en. Ng\\u01b0\\u1eddi th\\u1eed nghi\\u1ec7m thao t\\u00e1c qua giao di\\u1ec7n, s\\u1eed d\\u1ee5ng nh\\u1eefng tr\\u01b0\\u1eddng h\\u1ee3p \\u0111\\u00e3 \\n\\u0111\\u01b0\\u1ee3c x\\u00e1c \\u0111\\u1ecbnh t\\u1eeb c\\u00e1c Use Case \\u1edf Ch\\u01b0\\u01a1ng 3 v\\u00e0 quan s\\u00e1t d\\u1eef li\\u1ec7u \\u0111\\u1ea7u ra. K\\u1ebft qu\\u1ea3 \\nmong \\u0111\\u1ee3i ph\\u1ea3i \\u0111\\u01b0\\u1ee3c x\\u00e1c \\u0111\\u1ecbnh tr\\u01b0\\u1edbc khi ch\\u1ea1y th\\u1eed, c\\u00f2n k\\u1ebft qu\\u1ea3 th\\u1ef1c t\\u1ebf \\u0111\\u01b0\\u1ee3c \\u0111i\\u1ec1n \\ntheo b\\u1ea3n h\\u1ec7 th\\u1ed1ng d\\u00f9ng \\u0111\\u1ec3 nghi\\u1ec7m thu. \\n6.4.1.  Th\\u1eed nghi\\u1ec7m quy tr\\u00ecnh l\\u1eadp k\\u1ebf ho\\u1ea1ch \\nCh\\u1ee9c n\\u0103ng l\\u1eadp k\\u1ebf ho\\u1ea1ch h\\u1ecdc k\\u1ef3 kh\\u00f3a lu\\u1eadn \\u0111\\u01b0\\u1ee3c s\\u1eed d\\u1ee5ng b\\u1edfi Gi\\u00e1o v\\u1ee5. \\nTheo \\u0111\\u1eb7c t\\u1ea3 Use Case, ng\\u01b0\\u1eddi d\\u00f9ng l\\u1ef1a ch\\u1ecdn h\\u1ecdc k\\u1ef3, nh\\u1eadp th\\u00f4ng tin k\\u1ebf ho\\u1ea1ch, \\n\\u0111\\u00ednh k\\u00e8m t\\u00e0i li\\u1ec7u li\\u00ean quan, l\\u01b0u v\\u00e0 c\\u00f4ng b\\u1ed1. Nh\\u00f3m c\\u1ea7n ki\\u1ec3m tra \\u0111i\\u1ec1u ki\\u1ec7n h\\u1ecdc k\\u1ef3 \\n\\u0111\\u00e3 t\\u1ed3n t\\u1ea1i, tr\\u01b0\\u1eddng h\\u1ee3p thi\\u1ebfu d\\u1eef li\\u1ec7u b\\u1eaft bu\\u1ed9c v\\u00e0 vi\\u1ec7c x\\u1eed l\\u00fd k\\u1ebf ho\\u1ea1ch tr\\u00f9ng h\\u1ecdc k\\u1ef3. \\nC\\u00f3 c\\u00e1i b\\u1ea3ng chia case test \\nM\\u00e3 \\nThao t\\u00e1c th\\u1eed nghi\\u1ec7m \\nK\\u1ebft qu\\u1ea3 mong \\u0111\\u1ee3i \\nTh\\u1ef1c t\\u1ebf \\nKH01 \\nT\\u1ea1o k\\u1ebf ho\\u1ea1ch h\\u1ee3p l\\u1ec7 \\nL\\u01b0u k\\u1ebf ho\\u1ea1ch th\\u00e0nh \\nc\\u00f4ng \\n[B\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":123,\"snippet\":\"c s\\u1eed d\\u1ee5ng b\\u1edfi Gi\\u00e1o v\\u1ee5. \\nTheo \\u0111\\u1eb7c t\\u1ea3 Use Case, ng\\u01b0\\u1eddi d\\u00f9ng l\\u1ef1a ch\\u1ecdn h\\u1ecdc k\\u1ef3, nh\\u1eadp th\\u00f4ng tin k\\u1ebf ho\\u1ea1ch, \\n\\u0111\\u00ednh k\\u00e8m t\\u00e0i li\\u1ec7u li\\u00ean quan, l\\u01b0u v\\u00e0 c\\u00f4ng b\\u1ed1. Nh\\u00f3m c\\u1ea7n ki\\u1ec3m tra \\u0111i\\u1ec1u ki\\u1ec7n h\\u1ecdc k\\u1ef3 \\n\\u0111\\u00e3 t\\u1ed3n t\\u1ea1i, tr\\u01b0\\u1eddng h\\u1ee3p thi\\u1ebfu d\\u1eef li\\u1ec7u b\\u1eaft bu\\u1ed9c v\\u00e0 vi\\u1ec7c x\\u1eed l\\u00fd k\\u1ebf ho\\u1ea1ch tr\\u00f9ng h\\u1ecdc k\\u1ef3. \\nC\\u00f3 c\\u00e1i b\\u1ea3ng chia case test \\nM\\u00e3 \\nThao t\\u00e1c th\\u1eed nghi\\u1ec7m \\nK\\u1ebft qu\\u1ea3 mong \\u0111\\u1ee3i \\nTh\\u1ef1c t\\u1ebf \\nKH01 \\nT\\u1ea1o k\\u1ebf ho\\u1ea1ch h\\u1ee3p l\\u1ec7 \\nL\\u01b0u k\\u1ebf ho\\u1ea1ch th\\u00e0nh \\nc\\u00f4ng \\n[B\\u1ed5 sung] \\nKH02 \\nThi\\u1ebfu th\\u00f4ng tin b\\u1eaft \\nbu\\u1ed9c \\nY\\u00eau c\\u1ea7u nh\\u1eadp b\\u1ed5 sung \\n[B\\u1ed5 sung] \\n 1\\n\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":124,\"snippet\":\"M\\u00e3 \\nThao t\\u00e1c th\\u1eed nghi\\u1ec7m \\nK\\u1ebft qu\\u1ea3 mong \\u0111\\u1ee3i \\nTh\\u1ef1c t\\u1ebf \\nKH03 \\nK\\u1ebf ho\\u1ea1ch \\u0111\\u00e3 t\\u1ed3n t\\u1ea1i \\ntrong h\\u1ecdc k\\u1ef3 \\nTh\\u00f4ng b\\u00e1o v\\u00e0 x\\u1eed l\\u00fd theo \\nquy \\u0111\\u1ecbnh \\n[B\\u1ed5 sung] \\nKH04 \\nC\\u00f4ng b\\u1ed1 k\\u1ebf ho\\u1ea1ch h\\u1ee3p \\nl\\u1ec7 \\nNg\\u01b0\\u1eddi d\\u00f9ng li\\u00ean quan \\nxem \\u0111\\u01b0\\u1ee3c k\\u1ebf ho\\u1ea1ch \\n[B\\u1ed5 sung] \\nCh\\u1ee9c n\\u0103ng l\\u1eadp v\\u00e0 ch\\u1ed1t danh s\\u00e1ch sinh vi\\u00ean \\u0111\\u1ee7 \\u0111i\\u1ec1u ki\\u1ec7n c\\u00f3 th\\u1ec3 \\u0111\\u01b0\\u1ee3c ki\\u1ec3m \\ntra c\\u00f9ng quy tr\\u00ecnh n\\u00e0y. V\\u1edbi tr\\u01b0\\u1eddng h\\u1ee3p sinh vi\\u00ean kh\\u00f4ng \\u0111\\u00e1p \\u1ee9ng ti\\u00eau ch\\u00ed, h\\u1ec7 \\nth\\u1ed1ng c\\u1ea7n th\\u1ec3 hi\\u1ec7n l\\u00fd do ho\\u1eb7c tr\\u1ea1ng th\\u00e1i ph\\u00f9 h\\u1ee3p n\\u1ebfu ch\\u1ee9c n\\u0103ng \\u0111\\u00f3 \\u0111\\u00e3 \\u0111\\u01b0\\u1ee3c tri\\u1ec3n \\nkhai. \\n[C\\u1ea6N B\\u1ed4 SUNG: \\u1ea2nh giao di\\u1ec7n l\\u1eadp k\\u1ebf ho\\u1ea1ch, k\\u1ebft qu\\u1ea3 l\\u01b0u v\\u00e0 th\\u00f4ng b\\u00e1o \\u1edf tr\\u01b0\\u1eddng h\\u1ee3p d\\u1eef li\\u1ec7u kh\\u00f4ng \\nh\\u1ee3p l\\u1ec7.] \\n6.4.2.  Th\\u1eed nghi\\u1ec7m qu\\u1ea3n l\\u00fd v\\u00e0 \\u0111\\u0103ng k\\u00fd \\u0111\\u1ec1 t\\u00e0i \\nPh\\u1ea7n qu\\u1ea3n l\\u00fd \\u0111\\u1ec1 t\\u00e0i \\u0111\\u01b0\\u1ee3c th\\u1eed nghi\\u1ec7m v\\u1edbi c\\u00e1c thao t\\u00e1c \\u0111\\u1ec1 xu\\u1ea5t, c\\u1eadp nh\\u1eadt, \\nph\\u00ea duy\\u1ec7t v\\u00e0 c\\u00f4ng b\\u1ed1 \\u0111\\u1ec1 t\\u00e0i theo quy\\u1ec1n ng\\u01b0\\u1eddi d\\u00f9ng. Ph\\u1ea7n \\u0111\\u0103ng k\\u00fd \\u0111\\u1ec1 t\\u00e0i \\u0111\\u01b0\\u1ee3c \\nki\\u1ec3m tra v\\u1edbi c\\u00e1c \\u0111i\\u1ec1u ki\\u1ec7n v\\u1ec1 th\\u1eddi gian \\u0111\\u0103ng k\\u00fd, ch\\u1ec9 ti\\u00eau c\\u00f2n l\\u1ea1i v\\u00e0 tr\\u1ea1ng th\\u00e1i \\u0111\\u0103ng \\nk\\u00fd hi\\u1ec7n c\\u00f3 c\\u1ee7a sinh vi\\u00ean. \\nTheo b\\u1ea3n \\u0111\\u1eb7c t\\u1ea3 Use Case \\u1edf Ch\\u01b0\\u01a1ng 3, hai tr\\u01b0\\u1eddng h\\u1ee3p c\\u1ea7n \\u0111\\u01b0\\u1ee3c \\u01b0u ti\\u00ean l\\u00e0 \\n\\u0111\\u1ec1 t\\u00e0i \\u0111\\u00e3 h\\u1ebft ch\\u1ec9 ti\\u00eau v\\u00e0 sinh vi\\u00ean \\u0111\\u00e3 \\u0111\\u0103ng k\\u00fd \\u0111\\u1ec1 t\\u00e0i kh\\u00e1c. Sau khi th\\u1ef1c hi\\u1ec7n thao \\nt\\u00e1c, ng\\u01b0\\u1eddi th\\u1eed nghi\\u1ec7m c\\u1ea7n ki\\u1ec3m tra c\\u1ea3 th\\u00f4ng b\\u00e1o tr\\u00ean giao di\\u1ec7n l\\u1eabn d\\u1eef li\\u1ec7u \\u0111\\u01b0\\u1ee3c \\nghi nh\\u1eadn trong h\\u1ec7 th\\u1ed1ng \\n6.4.3.  Th\\u1eed nghi\\u1ec7m qu\\u1ea3n l\\u00fd ti\\u1ebfn \\u0111\\u1ed9 \\nQuy tr\\u00ecnh qu\\u1ea3n l\\u00fd ti\\u1ebfn \\u0111\\u1ed9 g\\u1ed3m sinh vi\\u00ean n\\u1ed9p b\\u00e1o c\\u00e1o theo \\u0111\\u1ee3t, gi\\u1ea3ng vi\\u00ean \\nxem b\\u00e1o c\\u00e1o, nh\\u1eadp nh\\u1eadn x\\u00e9t v\\u00e0 c\\u1eadp nh\\u1eadt tr\\u1ea1ng th\\u00e1i. Tr\\u01b0\\u1eddng h\\u1ee3p y\\u00eau c\\u1ea7u ch\\u1ec9nh \\ns\\u1eeda c\\u1ea7n \\u0111\\u01b0\\u1ee3c th\\u1eed nghi\\u1ec7m b\\u1eb1ng c\\u00e1ch cho sinh vi\\u00ean g\\u1eedi b\\u1ea3n b\\u00e1o c\\u00e1o ti\\u1ebfp theo, qua \\n\\u0111\\u00f3 ki\\u1ec3m tra vi\\u1ec7c qu\\u1ea3n l\\u00fd c\\u00e1c l\\u1ea7n n\\u1ed9p v\\u00e0 quy\\u1ec1n truy c\\u1eadp c\\u1ee7a t\\u1eebng ng\\u01b0\\u1eddi d\\u00f9ng \\n6.4.4.  Th\\u1eed nghi\\u1ec7m qu\\u1ea3n l\\u00fd b\\u1ea3o v\\u1ec7 \\nC\\u00e1c b\\u01b0\\u1edbc qu\\u1ea3n l\\u00fd b\\u1ea3o v\\u1ec7 bao g\\u1ed3m sinh vi\\u00ean n\\u1ed9p h\\u1ed3 s\\u01a1, ng\\u01b0\\u1eddi c\\u00f3 th\\u1ea9m \\nquy\\u1ec1n ki\\u1ec3m tra v\\u00e0 x\\u00e9t duy\\u1ec7t, ph\\u00e2n c\\u00f4ng h\\u1ed9i \\u0111\\u1ed3ng, b\\u1ed1 tr\\u00ed l\\u1ecbch, ch\\u1ea5m \\u0111i\\u1ec3m v\\u00e0 t\\u1ed5ng \\nh\\u1ee3p k\\u1ebft qu\\u1ea3. Qu\\u00e1 tr\\u00ecnh th\\u1eed nghi\\u1ec7m t\\u1eadp trung v\\u00e0o vi\\u1ec7c d\\u1eef li\\u1ec7u chuy\\u1ec3n \\u0111\\u00fang tr\\u1ea1ng \\nth\\u00e1i, x\\u1eed l\\u00fd h\\u1ed3 s\\u01a1 thi\\u1ebfu th\\u00e0nh ph\\u1ea7n v\\u00e0 ki\\u1ec3m so\\u00e1t quy\\u1ec1n p\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":124,\"snippet\":\"qua \\n\\u0111\\u00f3 ki\\u1ec3m tra vi\\u1ec7c qu\\u1ea3n l\\u00fd c\\u00e1c l\\u1ea7n n\\u1ed9p v\\u00e0 quy\\u1ec1n truy c\\u1eadp c\\u1ee7a t\\u1eebng ng\\u01b0\\u1eddi d\\u00f9ng \\n6.4.4.  Th\\u1eed nghi\\u1ec7m qu\\u1ea3n l\\u00fd b\\u1ea3o v\\u1ec7 \\nC\\u00e1c b\\u01b0\\u1edbc qu\\u1ea3n l\\u00fd b\\u1ea3o v\\u1ec7 bao g\\u1ed3m sinh vi\\u00ean n\\u1ed9p h\\u1ed3 s\\u01a1, ng\\u01b0\\u1eddi c\\u00f3 th\\u1ea9m \\nquy\\u1ec1n ki\\u1ec3m tra v\\u00e0 x\\u00e9t duy\\u1ec7t, ph\\u00e2n c\\u00f4ng h\\u1ed9i \\u0111\\u1ed3ng, b\\u1ed1 tr\\u00ed l\\u1ecbch, ch\\u1ea5m \\u0111i\\u1ec3m v\\u00e0 t\\u1ed5ng \\nh\\u1ee3p k\\u1ebft qu\\u1ea3. Qu\\u00e1 tr\\u00ecnh th\\u1eed nghi\\u1ec7m t\\u1eadp trung v\\u00e0o vi\\u1ec7c d\\u1eef li\\u1ec7u chuy\\u1ec3n \\u0111\\u00fang tr\\u1ea1ng \\nth\\u00e1i, x\\u1eed l\\u00fd h\\u1ed3 s\\u01a1 thi\\u1ebfu th\\u00e0nh ph\\u1ea7n v\\u00e0 ki\\u1ec3m so\\u00e1t quy\\u1ec1n ph\\u00ea duy\\u1ec7t ho\\u1eb7c ch\\u1ea5m \\u0111i\\u1ec3m \\n6.4.5.  Th\\u1eed nghi\\u1ec7m th\\u1ed1ng k\\u00ea \\nCh\\u1ee9c n\\u0103ng th\\u1ed1ng k\\u00ea \\u0111\\u01b0\\u1ee3c th\\u1eed nghi\\u1ec7m b\\u1eb1ng c\\u00e1ch l\\u1ef1a ch\\u1ecdn h\\u1ecdc k\\u1ef3 v\\u00e0 c\\u00e1c \\n\\u0111i\\u1ec1u ki\\u1ec7n l\\u1ecdc ph\\u00f9 h\\u1ee3p. H\\u1ec7 th\\u1ed1ng c\\u1ea7n hi\\u1ec3n th\\u1ecb s\\u1ed1 li\\u1ec7u v\\u1ec1 sinh vi\\u00ean, \\u0111\\u1ec1 t\\u00e0i, gi\\u1ea3ng \\nvi\\u00ean h\\u01b0\\u1edbng d\\u1eabn ho\\u1eb7c k\\u1ebft qu\\u1ea3 b\\u1ea3o v\\u1ec7 d\\u1ef1a tr\\u00ean d\\u1eef li\\u1ec7u hi\\u1ec7n c\\u00f3. S\\u1ed1 li\\u1ec7u th\\u1ed1ng k\\u00ea \\n\\u0111\\u01b0\\u1ee3c \\u0111\\u1ed1i chi\\u1ebfu v\\u1edbi d\\u1eef li\\u1ec7u g\\u1ed1c \\u0111\\u1ec3 ki\\u1ec3m tra \\u0111\\u1ed9 ch\\u00ednh x\\u00e1c. \\n 1\\n\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":125,\"snippet\":\"Ngo\\u00e0i tr\\u01b0\\u1eddng h\\u1ee3p c\\u00f3 d\\u1eef li\\u1ec7u, c\\u1ea7n ki\\u1ec3m tra tr\\u01b0\\u1eddng h\\u1ee3p kh\\u00f4ng c\\u00f3 k\\u1ebft qu\\u1ea3 \\nph\\u00f9 h\\u1ee3p. N\\u1ebfu phi\\u00ean b\\u1ea3n h\\u1ec7 th\\u1ed1ng \\u0111\\u00e3 c\\u00f3 ch\\u1ee9c n\\u0103ng xu\\u1ea5t b\\u00e1o c\\u00e1o Excel ho\\u1eb7c PDF, \\nnh\\u00f3m th\\u1eed nghi\\u1ec7m th\\u00eam t\\u00ednh ch\\u00ednh x\\u00e1c c\\u1ee7a t\\u1ec7p xu\\u1ea5t so v\\u1edbi k\\u1ebft qu\\u1ea3 tr\\u00ean giao di\\u1ec7n \\n6.5.  PH\\u00c1T TRI\\u1ec2N CH\\u1ee8C N\\u0102NG T\\u00d3M T\\u1eaeT B\\u00c1O C\\u00c1O  \\n6.5.1.  B\\u00e0i to\\u00e1n t\\u00f3m t\\u1eaft b\\u00e1o c\\u00e1o \\nTrong qu\\u00e1 tr\\u00ecnh th\\u1ef1c hi\\u1ec7n kh\\u00f3a lu\\u1eadn t\\u1ed1t nghi\\u1ec7p, sinh vi\\u00ean ph\\u1ea3i n\\u1ed9p b\\u00e1o c\\u00e1o \\nti\\u1ebfn \\u0111\\u1ed9 theo c\\u00e1c \\u0111\\u1ee3t do gi\\u1ea3ng vi\\u00ean quy \\u0111\\u1ecbnh. N\\u1ed9i dung b\\u00e1o c\\u00e1o c\\u00f3 th\\u1ec3 bao g\\u1ed3m \\nnhi\\u1ec1u ch\\u01b0\\u01a1ng, m\\u1ee5c v\\u00e0 c\\u00f3 \\u0111\\u1ed9 d\\u00e0i t\\u1eeb v\\u00e0i ch\\u1ee5c \\u0111\\u1ebfn h\\u00e0ng tr\\u0103m trang. Vi\\u1ec7c \\u0111\\u1ecdc to\\u00e0n \\nb\\u1ed9 b\\u00e1o c\\u00e1o \\u0111\\u1ec3 x\\u00e1c \\u0111\\u1ecbnh nh\\u1eefng n\\u1ed9i dung sinh vi\\u00ean \\u0111\\u00e3 th\\u1ef1c hi\\u1ec7n c\\u00f3 th\\u1ec3 m\\u1ea5t nhi\\u1ec1u \\nth\\u1eddi gian, \\u0111\\u1eb7c bi\\u1ec7t khi gi\\u1ea3ng vi\\u00ean ph\\u1ee5 tr\\u00e1ch nhi\\u1ec1u nh\\u00f3m kh\\u00f3a lu\\u1eadn. \\n\\u0110\\u1ec3 h\\u1ed7 tr\\u1ee3 qu\\u00e1 tr\\u00ecnh theo d\\u00f5i ti\\u1ebfn \\u0111\\u1ed9, nh\\u00f3m ph\\u00e1t tri\\u1ec3n ch\\u1ee9c n\\u0103ng t\\u1ef1 \\u0111\\u1ed9ng \\nt\\u00f3m t\\u1eaft b\\u00e1o c\\u00e1o kh\\u00f3a lu\\u1eadn b\\u1eb1ng m\\u00f4 h\\u00ecnh ng\\u00f4n ng\\u1eef l\\u1edbn. Ch\\u1ee9c n\\u0103ng ti\\u1ebfp nh\\u1eadn t\\u1ec7p \\nb\\u00e1o c\\u00e1o PDF, tr\\u00edch xu\\u1ea5t n\\u1ed9i dung v\\u0103n b\\u1ea3n v\\u00e0 t\\u1ea1o b\\u1ea3n t\\u00f3m t\\u1eaft nh\\u1eefng c\\u00f4ng vi\\u1ec7c \\u0111\\u00e3 \\n\\u0111\\u01b0\\u1ee3c tr\\u00ecnh b\\u00e0y trong b\\u00e1o c\\u00e1o. \\nDo b\\u00e1o c\\u00e1o c\\u00f3 th\\u1ec3 ch\\u1ee9a l\\u01b0\\u1ee3ng l\\u1edbn n\\u1ed9i dung, h\\u1ec7 th\\u1ed1ng kh\\u00f4ng x\\u1eed l\\u00fd to\\u00e0n b\\u1ed9 \\nt\\u00e0i li\\u1ec7u trong m\\u1ed9t l\\u1ea7n g\\u1ecdi m\\u00f4 h\\u00ecnh. Thay v\\u00e0o \\u0111\\u00f3, n\\u1ed9i dung \\u0111\\u01b0\\u1ee3c ph\\u00e2n \\u0111o\\u1ea1n theo \\nc\\u1ea5u tr\\u00fac ch\\u01b0\\u01a1ng, m\\u1ee5c v\\u00e0 chia nh\\u1ecf khi c\\u1ea7n thi\\u1ebft. C\\u00e1c \\u0111o\\u1ea1n v\\u0103n b\\u1ea3n \\u0111\\u01b0\\u1ee3c t\\u00f3m t\\u1eaft \\nb\\u1eb1ng LLM, sau \\u0111\\u00f3 t\\u1ed5ng h\\u1ee3p theo ph\\u01b0\\u01a1ng ph\\u00e1p Map\\u2013Reduce. \\nK\\u1ebft qu\\u1ea3 t\\u00f3m t\\u1eaft \\u0111\\u01b0\\u1ee3c t\\u1ed5 ch\\u1ee9c theo c\\u00e1c ch\\u01b0\\u01a1ng, m\\u1ee5c t\\u01b0\\u01a1ng \\u1ee9ng v\\u1edbi b\\u00e1o \\nc\\u00e1o g\\u1ed1c nh\\u1eb1m h\\u1ed7 tr\\u1ee3 gi\\u1ea3ng vi\\u00ean theo d\\u00f5i v\\u00e0 \\u0111\\u1ed1i chi\\u1ebfu n\\u1ed9i dung. Nh\\u1eefng th\\u00f4ng tin \\nkh\\u00f4ng c\\u00f3 c\\u0103n c\\u1ee9 trong t\\u00e0i li\\u1ec7u kh\\u00f4ng \\u0111\\u01b0\\u1ee3c s\\u1eed d\\u1ee5ng l\\u00e0m n\\u1ed9i dung t\\u00f3m t\\u1eaft. \\n6.5.2.  S\\u01a1 \\u0111\\u1ed3 ho\\u1ea1t \\u0111\\u1ed9ng ch\\u1ee9c n\\u0103ng t\\u00f3m t\\u1eaft b\\u00e1o c\\u00e1o \\nS\\u01a1 \\u0111\\u1ed3 ho\\u1ea1t \\u0111\\u1ed9ng m\\u00f4 t\\u1ea3 c\\u00e1c b\\u01b0\\u1edbc t\\u1eeb khi sinh vi\\u00ean t\\u1ea3i l\\u00ean b\\u00e1o c\\u00e1o \\u0111\\u1ebfn khi \\ngi\\u1ea3ng vi\\u00ean xem k\\u1ebft qu\\u1ea3. H\\u1ec7 th\\u1ed1ng ki\\u1ec3m tra t\\u1ec7p \\u0111\\u1ea7u v\\u00e0o, tr\\u00edch xu\\u1ea5t n\\u1ed9i dung, nh\\u1eadn \\ndi\\u1ec7n ch\\u01b0\\u01a1ng, m\\u1ee5c v\\u00e0 chia chunk. Ti\\u1ebfp theo, c\\u00e1c \\u0111o\\u1ea1n v\\u0103n b\\u1ea3n \\u0111\\u01b0\\u1ee3c g\\u1eedi \\u0111\\u1ebfn LLM \\n\\u0111\\u1ec3 t\\u00f3m t\\u1eaft, sau \\u0111\\u00f3 \\u0111\\u01b0\\u1ee3c t\\u1ed5ng h\\u1ee3p v\\u00e0 ki\\u1ec3m tra tr\\u01b0\\u1edbc khi l\\u01b0\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":125,\"snippet\":\"\\u1ee9 trong t\\u00e0i li\\u1ec7u kh\\u00f4ng \\u0111\\u01b0\\u1ee3c s\\u1eed d\\u1ee5ng l\\u00e0m n\\u1ed9i dung t\\u00f3m t\\u1eaft. \\n6.5.2.  S\\u01a1 \\u0111\\u1ed3 ho\\u1ea1t \\u0111\\u1ed9ng ch\\u1ee9c n\\u0103ng t\\u00f3m t\\u1eaft b\\u00e1o c\\u00e1o \\nS\\u01a1 \\u0111\\u1ed3 ho\\u1ea1t \\u0111\\u1ed9ng m\\u00f4 t\\u1ea3 c\\u00e1c b\\u01b0\\u1edbc t\\u1eeb khi sinh vi\\u00ean t\\u1ea3i l\\u00ean b\\u00e1o c\\u00e1o \\u0111\\u1ebfn khi \\ngi\\u1ea3ng vi\\u00ean xem k\\u1ebft qu\\u1ea3. H\\u1ec7 th\\u1ed1ng ki\\u1ec3m tra t\\u1ec7p \\u0111\\u1ea7u v\\u00e0o, tr\\u00edch xu\\u1ea5t n\\u1ed9i dung, nh\\u1eadn \\ndi\\u1ec7n ch\\u01b0\\u01a1ng, m\\u1ee5c v\\u00e0 chia chunk. Ti\\u1ebfp theo, c\\u00e1c \\u0111o\\u1ea1n v\\u0103n b\\u1ea3n \\u0111\\u01b0\\u1ee3c g\\u1eedi \\u0111\\u1ebfn LLM \\n\\u0111\\u1ec3 t\\u00f3m t\\u1eaft, sau \\u0111\\u00f3 \\u0111\\u01b0\\u1ee3c t\\u1ed5ng h\\u1ee3p v\\u00e0 ki\\u1ec3m tra tr\\u01b0\\u1edbc khi l\\u01b0u l\\u1ea1i. \\n 1\\n\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":126,\"snippet\":\"H\\u00ecnh 6.1. S\\u01a1 \\u0111\\u1ed3 ho\\u1ea1t \\u0111\\u1ed9ng ch\\u1ee9c n\\u0103ng t\\u00f3m t\\u1eaft b\\u00e1o c\\u00e1o \\n\\u0110\\u1ec3 t\\u1ea1m \\n6.5.3.  Quy tr\\u00ecnh x\\u1eed l\\u00fd b\\u00e1o c\\u00e1o \\nQuy tr\\u00ecnh \\u0111\\u01b0\\u1ee3c th\\u1ef1c hi\\u1ec7n sau khi sinh vi\\u00ean n\\u1ed9p v\\u00e0 h\\u1ec7 th\\u1ed1ng ti\\u1ebfp nh\\u1eadn t\\u1ec7p \\nPDF. N\\u1ed9i dung t\\u1eebng trang \\u0111\\u01b0\\u1ee3c tr\\u00edch xu\\u1ea5t th\\u00e0nh v\\u0103n b\\u1ea3n, sau \\u0111\\u00f3 h\\u1ec7 th\\u1ed1ng t\\u00ecm c\\u00e1c \\nti\\u00eau \\u0111\\u1ec1 ch\\u01b0\\u01a1ng, m\\u1ee5c \\u0111\\u1ec3 x\\u00e1c \\u0111\\u1ecbnh ranh gi\\u1edbi n\\u1ed9i dung. C\\u00e1c m\\u1ee5c d\\u00e0i ti\\u1ebfp t\\u1ee5c \\u0111\\u01b0\\u1ee3c \\nchia th\\u00e0nh nh\\u1eefng chunk nh\\u1ecf c\\u00f3 \\u0111\\u1ed9 d\\u00e0i ph\\u00f9 h\\u1ee3p v\\u1edbi gi\\u1edbi h\\u1ea1n x\\u1eed l\\u00fd c\\u1ee7a m\\u00f4 h\\u00ecnh. \\n\\u1ede giai \\u0111o\\u1ea1n Map, LLM t\\u00f3m t\\u1eaft t\\u1eebng chunk v\\u00e0 tr\\u1ea3 v\\u1ec1 d\\u1eef li\\u1ec7u c\\u00f3 c\\u1ea5u tr\\u00fac. \\u1ede \\ngiai \\u0111o\\u1ea1n Reduce, k\\u1ebft qu\\u1ea3 \\u0111\\u01b0\\u1ee3c t\\u1ed5ng h\\u1ee3p theo c\\u00e1c c\\u1ea5p t\\u1eeb chunk \\u0111\\u1ebfn m\\u1ee5c, ch\\u01b0\\u01a1ng \\n 1\\n\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":127,\"snippet\":\"v\\u00e0 t\\u00e0i li\\u1ec7u. Tr\\u01b0\\u1edbc khi l\\u01b0u tr\\u1eef, h\\u1ec7 th\\u1ed1ng c\\u1ea7n ki\\u1ec3m tra JSON v\\u00e0 \\u0111\\u1ed1i chi\\u1ebfu n\\u1ed9i dung \\nv\\u1edbi ngu\\u1ed3n nh\\u1eb1m h\\u1ea1n ch\\u1ebf vi\\u1ec7c t\\u1ea1o c\\u00e1c \\u00fd kh\\u00f4ng c\\u00f3 trong b\\u00e1o c\\u00e1o. \\nHi\\u0300nh 6.1 Quy tr\\u00ecnh x\\u1eed l\\u00fd b\\u00e1o c\\u00e1o PDF b\\u1eb1ng Map\\u2013Reduce \\nQuy tr\\u00ecnh tr\\u00ean m\\u00f4 t\\u1ea3 ri\\u00eang ch\\u1ee9c n\\u0103ng t\\u00f3m t\\u1eaft b\\u00e1o c\\u00e1o. Vi\\u1ec7c so s\\u00e1nh b\\u00e1o \\nc\\u00e1o v\\u1edbi danh s\\u00e1ch y\\u00eau c\\u1ea7u c\\u1ee7a gi\\u1ea3ng vi\\u00ean l\\u00e0 ch\\u1ee9c n\\u0103ng kh\\u00e1c, kh\\u00f4ng n\\u00ean g\\u1ed9p \\nth\\u00e0nh m\\u1ed9t k\\u1ebft qu\\u1ea3 AI n\\u1ebfu h\\u1ec7 th\\u1ed1ng tri\\u1ec3n khai ch\\u00fang \\u0111\\u1ed9c l\\u1eadp. \\n6.5.4.  Ph\\u00e2n \\u0111o\\u1ea1n v\\u0103n b\\u1ea3n b\\u1eb1ng Chunking \\nH\\u1ec7 th\\u1ed1ng \\u01b0u ti\\u00ean chia t\\u00e0i li\\u1ec7u d\\u1ef1a theo c\\u1ea5u tr\\u00fac ch\\u01b0\\u01a1ng, m\\u1ee5c nh\\u01b0 1, 1.1, \\n2.3 thay v\\u00ec c\\u1eaft to\\u00e0n b\\u1ed9 v\\u0103n b\\u1ea3n th\\u00e0nh nh\\u1eefng \\u0111o\\u1ea1n c\\u00f3 k\\u00edch th\\u01b0\\u1edbc c\\u1ed1 \\u0111\\u1ecbnh ngay t\\u1eeb \\n\\u0111\\u1ea7u. C\\u00e1ch n\\u00e0y gi\\u1eef \\u0111\\u01b0\\u1ee3c n\\u1ed9i dung thu\\u1ed9c c\\u00f9ng m\\u1ed9t m\\u1ee5c v\\u00e0 gi\\u00fap b\\u1ea3n t\\u00f3m t\\u1eaft c\\u00f3 th\\u1ec3 \\nhi\\u1ec3n th\\u1ecb theo s\\u1ed1 th\\u1ee9 t\\u1ef1 t\\u01b0\\u01a1ng \\u1ee9ng v\\u1edbi t\\u00e0i li\\u1ec7u g\\u1ed1c. \\n\\u0110\\u1ed1i v\\u1edbi nh\\u1eefng m\\u1ee5c c\\u00f3 n\\u1ed9i dung v\\u01b0\\u1ee3t qu\\u00e1 k\\u00edch th\\u01b0\\u1edbc cho ph\\u00e9p, h\\u1ec7 th\\u1ed1ng \\nti\\u1ebfp t\\u1ee5c t\\u1ea1o nhi\\u1ec1u chunk. M\\u1ed9t l\\u01b0\\u1ee3ng v\\u0103n b\\u1ea3n nh\\u1ecf \\u1edf cu\\u1ed1i chunk tr\\u01b0\\u1edbc c\\u00f3 th\\u1ec3 \\u0111\\u01b0\\u1ee3c \\ngi\\u1eef l\\u1ea1i \\u1edf \\u0111\\u1ea7u chunk sau \\u0111\\u1ec3 gi\\u1ea3m nguy c\\u01a1 m\\u1ea5t ng\\u1eef c\\u1ea3nh. K\\u00edch th\\u01b0\\u1edbc chunk v\\u00e0 \\nkho\\u1ea3ng ch\\u1ed3ng l\\u1ea5n c\\u1ea7n \\u0111\\u01b0\\u1ee3c c\\u1ea5u h\\u00ecnh d\\u1ef1a tr\\u00ean gi\\u1edbi h\\u1ea1n token c\\u1ee7a m\\u00f4 h\\u00ecnh \\u0111\\u01b0\\u1ee3c \\ns\\u1eed d\\u1ee5ng. \\nM\\u1ed7i chunk c\\u1ea7n g\\u1eafn th\\u00f4ng tin nh\\u1eadn di\\u1ec7n t\\u00e0i li\\u1ec7u, ch\\u01b0\\u01a1ng, m\\u1ee5c, s\\u1ed1 trang v\\u00e0 \\nth\\u1ee9 t\\u1ef1 x\\u1eed l\\u00fd. Ch\\u1eb3ng h\\u1ea1n, n\\u1ebfu m\\u1ee5c 3.2 \\u0111\\u01b0\\u1ee3c chia th\\u00e0nh n\\u0103m chunk, c\\u1ea3 n\\u0103m ph\\u1ea3i \\n\\u0111\\u01b0\\u1ee3c t\\u1ed5ng h\\u1ee3p tr\\u1edf l\\u1ea1i th\\u00e0nh m\\u1ed9t b\\u1ea3n t\\u00f3m t\\u1eaft c\\u1ee7a m\\u1ee5c 3.2 tr\\u01b0\\u1edbc khi chuy\\u1ec3n sang \\nb\\u01b0\\u1edbc t\\u1ed5ng h\\u1ee3p ch\\u01b0\\u01a1ng. \\nB\\u1ea3ng 6.2 Th\\u00f4ng tin c\\u1ea7n l\\u01b0u k\\u00e8m chunk \\nThu\\u1ed9c t\\u00ednh \\nVai tr\\u00f2 \\nV\\u00ed d\\u1ee5 minh h\\u1ecda \\ndocument_id \\nX\\u00e1c \\u0111\\u1ecbnh t\\u00e0i li\\u1ec7u v\\u00e0 l\\u1ea7n \\nBaoCao_02 \\n 1\\n\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":128,\"snippet\":\"Thu\\u1ed9c t\\u00ednh \\nVai tr\\u00f2 \\nV\\u00ed d\\u1ee5 minh h\\u1ecda \\nn\\u1ed9p \\nsection_id \\nX\\u00e1c \\u0111\\u1ecbnh s\\u1ed1 m\\u1ee5c \\n3.2 \\nchunk_index \\nTh\\u1ee9 t\\u1ef1 chunk c\\u1ee7a m\\u1ee5c \\n2\\/5 \\nTrang ch\\u1ee9a n\\u1ed9i dung \\npage_start, page_end \\n18\\u201321 \\nngu\\u1ed3n \\ncontent \\nV\\u0103n b\\u1ea3n g\\u1eedi \\u0111\\u1ebfn LLM \\nN\\u1ed9i dung tr\\u00edch xu\\u1ea5t \\n[C\\u1ea6N B\\u1ed4 SUNG: T\\u00ean th\\u01b0 vi\\u1ec7n tr\\u00edch xu\\u1ea5t PDF, c\\u00e1ch nh\\u1eadn di\\u1ec7n m\\u1ee5c X.X, gi\\u00e1 tr\\u1ecb chunk size v\\u00e0 \\noverlap th\\u1ef1c t\\u1ebf t\\u1eeb m\\u00e3 ngu\\u1ed3n. Kh\\u00f4ng l\\u1ea5y th\\u00f4ng s\\u1ed1 v\\u00ed d\\u1ee5 \\u1edf Ch\\u01b0\\u01a1ng 2 thay s\\u1ed1 li\\u1ec7u tri\\u1ec3n khai.] \\n6.5.5.  X\\u1eed l\\u00fd t\\u00f3m t\\u1eaft b\\u1eb1ng LLM \\nT\\u1ea1i b\\u01b0\\u1edbc Map, h\\u1ec7 th\\u1ed1ng l\\u1ea7n l\\u01b0\\u1ee3t g\\u1eedi t\\u1eebng chunk \\u0111\\u1ebfn API LLM c\\u00f9ng v\\u1edbi \\nprompt quy \\u0111\\u1ecbnh n\\u1ed9i dung c\\u1ea7n tr\\u00edch xu\\u1ea5t v\\u00e0 c\\u1ea5u tr\\u00fac \\u0111\\u1ea7u ra. Prompt y\\u00eau c\\u1ea7u m\\u00f4 \\nh\\u00ecnh t\\u1eadp trung v\\u00e0o nh\\u1eefng ph\\u1ea7n \\u0111\\u00e3 \\u0111\\u01b0\\u1ee3c tr\\u00ecnh b\\u00e0y trong chunk v\\u00e0 h\\u1ea1n ch\\u1ebf \\u0111\\u01b0a ra \\nnh\\u1eadn \\u0111\\u1ecbnh kh\\u00f4ng c\\u00f3 c\\u0103n c\\u1ee9 trong v\\u0103n b\\u1ea3n \\u0111\\u1ea7u v\\u00e0o. \\nK\\u1ebft qu\\u1ea3 t\\u1eeb API \\u0111\\u01b0\\u1ee3c y\\u00eau c\\u1ea7u \\u1edf d\\u1ea1ng JSON v\\u00e0 g\\u1eafn v\\u1edbi m\\u00e3 t\\u00e0i li\\u1ec7u, \\nch\\u01b0\\u01a1ng, m\\u1ee5c, chunk t\\u01b0\\u01a1ng \\u1ee9ng. H\\u1ec7 th\\u1ed1ng ki\\u1ec3m tra c\\u1ea5u tr\\u00fac ph\\u1ea3n h\\u1ed3i tr\\u01b0\\u1edbc khi s\\u1eed \\nd\\u1ee5ng trong nh\\u1eefng b\\u01b0\\u1edbc ti\\u1ebfp theo. Tr\\u01b0\\u1eddng h\\u1ee3p API tr\\u1ea3 v\\u1ec1 l\\u1ed7i, JSON kh\\u00f4ng h\\u1ee3p l\\u1ec7 \\nho\\u1eb7c d\\u1eef li\\u1ec7u r\\u1ed7ng c\\u1ea7n \\u0111\\u01b0\\u1ee3c nh\\u1eadn di\\u1ec7n l\\u00e0 l\\u1ed7i x\\u1eed l\\u00fd, kh\\u00f4ng xem nh\\u01b0 m\\u1ed9t b\\u1ea3n t\\u00f3m \\nt\\u1eaft th\\u00e0nh c\\u00f4ng. \\nTh\\u00f4ng s\\u1ed1 c\\u1ea5u h\\u00ecnh nh\\u01b0 m\\u00e3 m\\u00f4 h\\u00ecnh, s\\u1ed1 token t\\u1ed1i \\u0111a, th\\u1eddi gian ch\\u1edd v\\u00e0 c\\u00e1ch \\ng\\u1ecdi API c\\u1ea7n \\u0111\\u01b0\\u1ee3c \\u0111\\u1ed1i chi\\u1ebfu v\\u1edbi m\\u00e3 ngu\\u1ed3n c\\u1ee7a b\\u1ea3n \\u0111ang ch\\u1ea1y. T\\u00e0i li\\u1ec7u b\\u00e1o c\\u00e1o \\nch\\u1ec9 tr\\u00ecnh b\\u00e0y c\\u00e1c th\\u00f4ng s\\u1ed1 th\\u1ef1c s\\u1ef1 \\u0111\\u01b0\\u1ee3c s\\u1eed d\\u1ee5ng trong th\\u1eed nghi\\u1ec7m. \\n6.5.6.   T\\u1ed5ng h\\u1ee3p k\\u1ebft qu\\u1ea3 b\\u1eb1ng Map\\u2013Reduce \\nSau khi c\\u00f3 c\\u00e1c b\\u1ea3n t\\u00f3m t\\u1eaft c\\u1ee5c b\\u1ed9, h\\u1ec7 th\\u1ed1ng gom c\\u00e1c k\\u1ebft qu\\u1ea3 thu\\u1ed9c c\\u00f9ng \\nm\\u1ed9t m\\u1ee5c v\\u00e0 th\\u1ef1c hi\\u1ec7n Reduce \\u0111\\u1ec3 lo\\u1ea1i b\\u1ecf c\\u00e1c \\u00fd tr\\u00f9ng l\\u1eb7p, \\u0111\\u1ed3ng th\\u1eddi t\\u1ea1o b\\u1ea3n t\\u00f3m \\nt\\u1eaft th\\u1ed1ng nh\\u1ea5t cho m\\u1ee5c \\u0111\\u00f3. C\\u00e1c b\\u1ea3n t\\u00f3m t\\u1eaft m\\u1ee5c \\u0111\\u01b0\\u1ee3c ti\\u1ebfp t\\u1ee5c t\\u1ed5ng h\\u1ee3p th\\u00e0nh \\nch\\u01b0\\u01a1ng; cu\\u1ed1i c\\u00f9ng, nh\\u1eefng b\\u1ea3n t\\u00f3m t\\u1eaft ch\\u01b0\\u01a1ng \\u0111\\u01b0\\u1ee3c d\\u00f9ng \\u0111\\u1ec3 t\\u1ea1o n\\u1ed9i dung t\\u1ed5ng \\nh\\u1ee3p cho to\\u00e0n b\\u1ed9 b\\u00e1o c\\u00e1o. \\n 1\\n\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":128,\"snippet\":\"\\u1ea1i b\\u1ecf c\\u00e1c \\u00fd tr\\u00f9ng l\\u1eb7p, \\u0111\\u1ed3ng th\\u1eddi t\\u1ea1o b\\u1ea3n t\\u00f3m \\nt\\u1eaft th\\u1ed1ng nh\\u1ea5t cho m\\u1ee5c \\u0111\\u00f3. C\\u00e1c b\\u1ea3n t\\u00f3m t\\u1eaft m\\u1ee5c \\u0111\\u01b0\\u1ee3c ti\\u1ebfp t\\u1ee5c t\\u1ed5ng h\\u1ee3p th\\u00e0nh \\nch\\u01b0\\u01a1ng; cu\\u1ed1i c\\u00f9ng, nh\\u1eefng b\\u1ea3n t\\u00f3m t\\u1eaft ch\\u01b0\\u01a1ng \\u0111\\u01b0\\u1ee3c d\\u00f9ng \\u0111\\u1ec3 t\\u1ea1o n\\u1ed9i dung t\\u1ed5ng \\nh\\u1ee3p cho to\\u00e0n b\\u1ed9 b\\u00e1o c\\u00e1o. \\n 1\\n\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":129,\"snippet\":\"Hi\\u0300nh 6.2 Qu\\u00e1 tr\\u00ecnh t\\u1ed5ng h\\u1ee3p ph\\u00e2n c\\u1ea5p trong Reduce \\nTrong t\\u1eebng v\\u00f2ng Reduce, th\\u00f4ng tin v\\u1ec1 v\\u1ecb tr\\u00ed ch\\u01b0\\u01a1ng, m\\u1ee5c v\\u00e0 trang ngu\\u1ed3n \\nc\\u1ea7n \\u0111\\u01b0\\u1ee3c gi\\u1eef l\\u1ea1i \\u0111\\u1ec3 h\\u1ea1n ch\\u1ebf gh\\u00e9p nh\\u1ea7m n\\u1ed9i dung. N\\u1ebfu d\\u1eef li\\u1ec7u c\\u1ee7a m\\u1ed9t v\\u00f2ng v\\u1eabn \\nd\\u00e0i so v\\u1edbi gi\\u1edbi h\\u1ea1n \\u0111\\u1ea7u v\\u00e0o, h\\u1ec7 th\\u1ed1ng c\\u00f3 th\\u1ec3 chia th\\u00e0nh c\\u00e1c l\\u01b0\\u1ee3t t\\u1ed5ng h\\u1ee3p nh\\u1ecf \\nh\\u01a1n. K\\u1ebft qu\\u1ea3 cu\\u1ed1i c\\u00f9ng ch\\u1ec9 tr\\u00ecnh b\\u00e0y n\\u1ed9i dung \\u0111\\u01b0\\u1ee3c h\\u1ed7 tr\\u1ee3 b\\u1edfi t\\u00e0i li\\u1ec7u g\\u1ed1c. \\nTheo y\\u00eau c\\u1ea7u c\\u1eadp nh\\u1eadt c\\u1ee7a gi\\u1ea3ng vi\\u00ean h\\u01b0\\u1edbng d\\u1eabn, giao di\\u1ec7n t\\u00f3m t\\u1eaft kh\\u00f4ng \\nhi\\u1ec3n th\\u1ecb hai m\\u1ee5c \\u201cKh\\u00f3 kh\\u0103n g\\u1eb7p ph\\u1ea3i\\u201d v\\u00e0 \\u201cK\\u1ebf ho\\u1ea1ch ti\\u1ebfp theo\\u201d. B\\u1ea3n t\\u00f3m t\\u1eaft t\\u1eadp \\ntrung v\\u00e0o n\\u1ed9i dung \\u0111\\u00e3 th\\u1ef1c hi\\u1ec7n v\\u00e0 \\u0111\\u01b0\\u1ee3c t\\u1ed5 ch\\u1ee9c theo ch\\u01b0\\u01a1ng, m\\u1ee5c \\u0111\\u1ec3 gi\\u1ea3ng vi\\u00ean \\nd\\u1ec5 theo d\\u00f5i. \\n6.5.7.   T\\u00edch h\\u1ee3p AI v\\u00e0o h\\u1ec7 th\\u1ed1ng \\nCh\\u1ee9c n\\u0103ng AI \\u0111\\u01b0\\u1ee3c t\\u00edch h\\u1ee3p v\\u1edbi quy tr\\u00ecnh n\\u1ed9p b\\u00e1o c\\u00e1o ti\\u1ebfn \\u0111\\u1ed9. K\\u1ebft qu\\u1ea3 x\\u1eed \\nl\\u00fd c\\u1ea7n g\\u1eafn v\\u1edbi \\u0111\\u00fang b\\u00e1o c\\u00e1o v\\u00e0 \\u0111\\u00fang phi\\u00ean b\\u1ea3n n\\u1ed9p, tr\\u00e1nh s\\u1eed d\\u1ee5ng b\\u1ea3n t\\u00f3m t\\u1eaft \\nc\\u1ee7a t\\u1ec7p c\\u0169 khi sinh vi\\u00ean \\u0111\\u00e3 c\\u1eadp nh\\u1eadt n\\u1ed9i dung. Tr\\u00ean giao di\\u1ec7n gi\\u1ea3ng vi\\u00ean, h\\u1ec7 \\nth\\u1ed1ng hi\\u1ec3n th\\u1ecb tr\\u1ea1ng th\\u00e1i \\u0111ang x\\u1eed l\\u00fd, \\u0111\\u00e3 ho\\u00e0n th\\u00e0nh ho\\u1eb7c l\\u1ed7i t\\u00f9y theo k\\u1ebft qu\\u1ea3 th\\u1ef1c \\nt\\u1ebf. \\nGi\\u1ea3ng vi\\u00ean c\\u00f3 th\\u1ec3 \\u0111\\u1ecdc b\\u1ea3n t\\u00f3m t\\u1eaft \\u0111\\u1ec3 n\\u1eafm nh\\u1eefng \\u00fd ch\\u00ednh, sau \\u0111\\u00f3 m\\u1edf b\\u00e1o \\nc\\u00e1o g\\u1ed1c khi c\\u1ea7n \\u0111\\u1ed1i chi\\u1ebfu. Quy\\u1ec1n truy c\\u1eadp t\\u1ec7p v\\u00e0 k\\u1ebft qu\\u1ea3 t\\u00f3m t\\u1eaft ph\\u1ea3i tu\\u00e2n theo \\nph\\u00e2n quy\\u1ec1n c\\u1ee7a h\\u1ec7 th\\u1ed1ng. C\\u00e1c tr\\u01b0\\u1eddng d\\u1eef li\\u1ec7u d\\u00f9ng \\u0111\\u1ec3 l\\u01b0u k\\u1ebft qu\\u1ea3 c\\u1ea7n \\u0111\\u01b0\\u1ee3c ki\\u1ec3m \\ntra l\\u1ea1i so v\\u1edbi thi\\u1ebft k\\u1ebf c\\u01a1 s\\u1edf d\\u1eef li\\u1ec7u \\u1edf Ch\\u01b0\\u01a1ng 5, \\u0111\\u1eb7c bi\\u1ec7t khi y\\u00eau c\\u1ea7u \\u0111\\u1ea7u ra AI \\u0111\\u00e3 \\nthay \\u0111\\u1ed5i \\n6.6.  TH\\u1eec NGHI\\u1ec6M V\\u00c0 \\u0110\\u00c1NH GI\\u00c1 K\\u1ebeT QU\\u1ea2 T\\u00d3M T\\u1eaeT \\n 1\\n\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":130,\"snippet\":\"6.6.1. Thi\\u1ebft l\\u1eadp th\\u1eed nghi\\u1ec7m \\n\\u0110\\u1ec3 \\u0111\\u00e1nh gi\\u00e1 ch\\u1ee9c n\\u0103ng t\\u00f3m t\\u1eaft, nh\\u00f3m c\\u1ea7n l\\u1ef1a ch\\u1ecdn c\\u00e1c b\\u00e1o c\\u00e1o PDF c\\u00f3 \\u0111\\u1ed9 \\nd\\u00e0i v\\u00e0 c\\u00e1ch tr\\u00ecnh b\\u00e0y kh\\u00e1c nhau. T\\u00e0i li\\u1ec7u ng\\u1eafn \\u0111\\u01b0\\u1ee3c s\\u1eed d\\u1ee5ng \\u0111\\u1ec3 ki\\u1ec3m tra ho\\u1ea1t \\n\\u0111\\u1ed9ng c\\u01a1 b\\u1ea3n; t\\u00e0i li\\u1ec7u c\\u00f3 nhi\\u1ec1u ch\\u01b0\\u01a1ng, m\\u1ee5c d\\u00f9ng \\u0111\\u1ec3 ki\\u1ec3m tra kh\\u1ea3 n\\u0103ng nh\\u1eadn di\\u1ec7n \\nc\\u1ea5u tr\\u00fac; c\\u00f2n t\\u00e0i li\\u1ec7u d\\u00e0i d\\u00f9ng \\u0111\\u1ec3 ki\\u1ec3m tra qu\\u00e1 tr\\u00ecnh chia chunk v\\u00e0 t\\u1ed5ng h\\u1ee3p nhi\\u1ec1u \\nc\\u1ea5p. \\n\\u0110\\u1ed1i v\\u1edbi m\\u1ed7i b\\u00e1o c\\u00e1o, ng\\u01b0\\u1eddi th\\u1eed nghi\\u1ec7m ghi nh\\u1eadn t\\u00ean ho\\u1eb7c m\\u00e3 t\\u1ec7p, s\\u1ed1 \\ntrang, s\\u1ed1 m\\u1ee5c nh\\u1eadn di\\u1ec7n, s\\u1ed1 chunk, tr\\u1ea1ng th\\u00e1i x\\u1eed l\\u00fd v\\u00e0 th\\u1eddi gian ho\\u00e0n th\\u00e0nh. C\\u1ea7n \\nth\\u1ed1ng nh\\u1ea5t th\\u1eddi \\u0111i\\u1ec3m b\\u1eaft \\u0111\\u1ea7u v\\u00e0 k\\u1ebft th\\u00fac ph\\u00e9p \\u0111o \\u0111\\u1ec3 c\\u00f3 th\\u1ec3 so s\\u00e1nh k\\u1ebft qu\\u1ea3 gi\\u1eefa \\nc\\u00e1c l\\u1ea7n ch\\u1ea1y. T\\u1ec7p PDF d\\u1ea1ng scan \\u1ea3nh, n\\u1ebfu kh\\u00f4ng \\u0111\\u01b0\\u1ee3c h\\u1ed7 tr\\u1ee3 OCR, c\\u1ea7n \\u0111\\u01b0\\u1ee3c ghi \\nnh\\u1eadn nh\\u01b0 tr\\u01b0\\u1eddng h\\u1ee3p ri\\u00eang. \\nB\\u1ea3ng 6.3 Danh s\\u00e1ch t\\u00e0i li\\u1ec7u PDF d\\u00f9ng th\\u1eed nghi\\u1ec7m \\nM\\u00e3 PDF \\n\\u0110\\u1eb7c \\u0111i\\u1ec3m \\nS\\u1ed1 trang \\nS\\u1ed1 m\\u1ee5c \\nS\\u1ed1 chunk \\nPDF01 \\nB\\u00e1o c\\u00e1o ng\\u1eafn \\n[B\\u1ed5 sung] \\n[B\\u1ed5 sung] \\n[B\\u1ed5 sung] \\nB\\u00e1o c\\u00e1o nhi\\u1ec1u \\nPDF02 \\n[B\\u1ed5 sung] \\n[B\\u1ed5 sung] \\n[B\\u1ed5 sung] \\nch\\u01b0\\u01a1ng\\/m\\u1ee5c \\nPDF03 \\nB\\u00e1o c\\u00e1o d\\u00e0i \\n[B\\u1ed5 sung] \\n[B\\u1ed5 sung] \\n[B\\u1ed5 sung] \\n6.6.2. K\\u1ebft qu\\u1ea3 x\\u1eed l\\u00fd \\nK\\u1ebft qu\\u1ea3 th\\u1ef1c nghi\\u1ec7m c\\u1ea7n \\u0111\\u01b0\\u1ee3c l\\u1ea5y t\\u1eeb c\\u00e1c l\\u1ea7n ch\\u1ea1y tr\\u00ean h\\u1ec7 th\\u1ed1ng. Th\\u1eddi \\ngian x\\u1eed l\\u00fd \\u0111\\u01b0\\u1ee3c t\\u00ednh theo c\\u00f9ng m\\u1ed9t m\\u1ed1c \\u0111o gi\\u1eefa c\\u00e1c t\\u00e0i li\\u1ec7u. Trong tr\\u01b0\\u1eddng h\\u1ee3p \\nc\\u00f3 l\\u01b0u th\\u1eddi gian cho t\\u1eebng giai \\u0111o\\u1ea1n, nh\\u00f3m c\\u00f3 th\\u1ec3 tr\\u00ecnh b\\u00e0y th\\u00eam th\\u1eddi gian tr\\u00edch \\nxu\\u1ea5t, Map v\\u00e0 Reduce \\u0111\\u1ec3 x\\u00e1c \\u0111\\u1ecbnh b\\u01b0\\u1edbc x\\u1eed l\\u00fd t\\u1ed1n nhi\\u1ec1u th\\u1eddi gian nh\\u1ea5t. \\nB\\u1ea3ng 6.4 K\\u1ebft qu\\u1ea3 x\\u1eed l\\u00fd c\\u00e1c b\\u00e1o c\\u00e1o PDF \\nM\\u00e3 PDF \\nTr\\u1ea1ng th\\u00e1i \\nTh\\u1eddi gian (gi\\u00e2y) \\nGhi ch\\u00fa \\nPDF01 \\n[B\\u1ed5 sung] \\n[B\\u1ed5 sung] \\n[L\\u1ed7i ho\\u1eb7c k\\u1ebft qu\\u1ea3] \\nPDF02 \\n[B\\u1ed5 sung] \\n[B\\u1ed5 sung] \\n[L\\u1ed7i ho\\u1eb7c k\\u1ebft qu\\u1ea3] \\nPDF03 \\n[B\\u1ed5 sung] \\n[B\\u1ed5 sung] \\n[L\\u1ed7i ho\\u1eb7c k\\u1ebft qu\\u1ea3] \\nVi\\u1ec7c API ph\\u1ea3n h\\u1ed3i th\\u00e0nh c\\u00f4ng ch\\u1ec9 ch\\u1ee9ng minh t\\u00e1c v\\u1ee5 \\u0111\\u00e3 nh\\u1eadn \\u0111\\u01b0\\u1ee3c k\\u1ebft \\nqu\\u1ea3 k\\u1ef9 thu\\u1eadt, ch\\u01b0a \\u0111\\u1ee7 \\u0111\\u1ec3 k\\u1ebft lu\\u1eadn b\\u1ea3n t\\u00f3m t\\u1eaft ch\\u00ednh x\\u00e1c. Ch\\u1ea5t l\\u01b0\\u1ee3ng n\\u1ed9i dung c\\u1ea7n \\n\\u0111\\u01b0\\u1ee3c ki\\u1ec3m tra b\\u1eb1ng c\\u00e1ch \\u0111\\u1ed1i chi\\u1ebfu v\\u1edbi b\\u00e1o c\\u00e1o g\\u1ed1c \\u1edf c\\u00e1c m\\u1ee5c ti\\u1ebfp theo. Nh\\u1eefng \\nl\\u1ea7n ch\\u1ea1y kh\\u00f4ng th\\u00e0nh c\\u00f4ng c\\u0169ng ph\\u1ea3i \\u0111\\u01b0\\u1ee3c ghi l\\u1ea1i k\\u00e8m b\\u01b0\\u1edbc ph\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":130,\"snippet\":\"\\u1eb7c k\\u1ebft qu\\u1ea3] \\nPDF02 \\n[B\\u1ed5 sung] \\n[B\\u1ed5 sung] \\n[L\\u1ed7i ho\\u1eb7c k\\u1ebft qu\\u1ea3] \\nPDF03 \\n[B\\u1ed5 sung] \\n[B\\u1ed5 sung] \\n[L\\u1ed7i ho\\u1eb7c k\\u1ebft qu\\u1ea3] \\nVi\\u1ec7c API ph\\u1ea3n h\\u1ed3i th\\u00e0nh c\\u00f4ng ch\\u1ec9 ch\\u1ee9ng minh t\\u00e1c v\\u1ee5 \\u0111\\u00e3 nh\\u1eadn \\u0111\\u01b0\\u1ee3c k\\u1ebft \\nqu\\u1ea3 k\\u1ef9 thu\\u1eadt, ch\\u01b0a \\u0111\\u1ee7 \\u0111\\u1ec3 k\\u1ebft lu\\u1eadn b\\u1ea3n t\\u00f3m t\\u1eaft ch\\u00ednh x\\u00e1c. Ch\\u1ea5t l\\u01b0\\u1ee3ng n\\u1ed9i dung c\\u1ea7n \\n\\u0111\\u01b0\\u1ee3c ki\\u1ec3m tra b\\u1eb1ng c\\u00e1ch \\u0111\\u1ed1i chi\\u1ebfu v\\u1edbi b\\u00e1o c\\u00e1o g\\u1ed1c \\u1edf c\\u00e1c m\\u1ee5c ti\\u1ebfp theo. Nh\\u1eefng \\nl\\u1ea7n ch\\u1ea1y kh\\u00f4ng th\\u00e0nh c\\u00f4ng c\\u0169ng ph\\u1ea3i \\u0111\\u01b0\\u1ee3c ghi l\\u1ea1i k\\u00e8m b\\u01b0\\u1edbc ph\\u00e1t sinh l\\u1ed7i \\n 1\\n\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":131,\"snippet\":\"[C\\u1ea6N B\\u1ed4 SUNG: Th\\u1eddi gian v\\u00e0 tr\\u1ea1ng th\\u00e1i ch\\u1ea1y th\\u1eadt, \\u1ea3nh giao di\\u1ec7n t\\u00f3m t\\u1eaft, \\u0111o\\u1ea1n nh\\u1eadt k\\u00fd x\\u1eed l\\u00fd \\u0111\\u00e3 \\nl\\u01b0\\u1ee3c b\\u1ecf kh\\u00f3a ho\\u1eb7c th\\u00f4ng tin nh\\u1ea1y c\\u1ea3m.] \\n6.6.3. \\u0110\\u00e1nh gi\\u00e1 ch\\u1ea5t l\\u01b0\\u1ee3ng b\\u1ea3n t\\u00f3m t\\u1eaft \\nCh\\u1ea5t l\\u01b0\\u1ee3ng b\\u1ea3n t\\u00f3m t\\u1eaft \\u0111\\u01b0\\u1ee3c \\u0111\\u00e1nh gi\\u00e1 qua vi\\u1ec7c so s\\u00e1nh t\\u1eebng \\u00fd v\\u1edbi t\\u00e0i li\\u1ec7u \\nPDF. Ngo\\u00e0i y\\u00eau c\\u1ea7u n\\u1ed9i dung ng\\u1eafn g\\u1ecdn, nh\\u00f3m xem x\\u00e9t b\\u1ea3n t\\u00f3m t\\u1eaft c\\u00f3 \\u0111\\u00fang \\nth\\u00f4ng tin, ph\\u1ea3n \\u00e1nh \\u0111\\u01b0\\u1ee3c c\\u00e1c n\\u1ed9i dung ch\\u00ednh v\\u00e0 gi\\u1eef \\u0111\\u00fang c\\u1ea5u tr\\u00fac ch\\u01b0\\u01a1ng, m\\u1ee5c \\nc\\u1ee7a b\\u00e1o c\\u00e1o hay kh\\u0