REPLACE INTO `khoibaocaotiendo` (`id`, `MaKhoi`, `MaBaoCao`, `MaDotNop`, `MaGiaiDoan`, `MaDeTai`, `LanBaoCao`, `LanNop`, `TieuDe`, `NoiDungBaoCao`, `KetQuaDatDuoc`, `KhoKhan`, `CongViecChuaHoanThanh`, `HuongGiaiQuyet`, `KeHoachTiepTheo`, `TenFile`, `DuongDanFile`, `LinkCode`, `TrangThai`, `PhanTramHoanThanh`, `NhanXetGV`, `NguoiNhanXet`, `NgayNop`, `NgayNhanXet`, `TomTatAI`, `TomTatJson`, `created_at`, `updated_at`) VALUES ('6', 'KHOI_D1_V6_ad6a45', 'BC_DOT_1', '1', '1', 'DT27', '1', '6', 'Đợt 1 – Khảo sát và mô tả nghiệp vụ (Phiên bản 6)', 'nộp lại', '', '', '', '', '', '[Vn Document]xay-dung-website-quan-ly-khoa-luan-tot-nghiep-dwa1752077489.pdf', 'baocao/baocao_dot1_v6_3982ae0b7d8379f2.pdf', NULL, 'Chờ duyệt', NULL, NULL, NULL, '2026-11-01 12:28:22', NULL, 'Báo cáo khóa luận xây dựng website quản lý khóa luận tốt nghiệp gồm năm chương, trình bày lý do chọn đề tài, cơ sở lý thuyết, phân tích thiết kế, thực nghiệm và tổng kết. Các nội dung chính bao gồm giới thiệu công nghệ, thiết kế use case cùng cơ sở dữ liệu, và cấu hình cài đặt hệ thống.

Tác giả đề xuất hệ thống với phân quyền giáo vụ, sinh viên và giảng viên, cùng các tính năng quản lý tài khoản, hội đồng, khóa luận và lưu điểm. Qua chương tổng kết, tác giả báo cáo đã cơ bản hoàn thành hệ thống với các chức năng cần thiết và nêu ra hướng phát triển.', '{\"overall_summary\":\"B\\u00e1o c\\u00e1o kh\\u00f3a lu\\u1eadn x\\u00e2y d\\u1ef1ng website qu\\u1ea3n l\\u00fd kh\\u00f3a lu\\u1eadn t\\u1ed1t nghi\\u1ec7p g\\u1ed3m n\\u0103m ch\\u01b0\\u01a1ng, tr\\u00ecnh b\\u00e0y l\\u00fd do ch\\u1ecdn \\u0111\\u1ec1 t\\u00e0i, c\\u01a1 s\\u1edf l\\u00fd thuy\\u1ebft, ph\\u00e2n t\\u00edch thi\\u1ebft k\\u1ebf, th\\u1ef1c nghi\\u1ec7m v\\u00e0 t\\u1ed5ng k\\u1ebft. C\\u00e1c n\\u1ed9i dung ch\\u00ednh bao g\\u1ed3m gi\\u1edbi thi\\u1ec7u c\\u00f4ng ngh\\u1ec7, thi\\u1ebft k\\u1ebf use case c\\u00f9ng c\\u01a1 s\\u1edf d\\u1eef li\\u1ec7u, v\\u00e0 c\\u1ea5u h\\u00ecnh c\\u00e0i \\u0111\\u1eb7t h\\u1ec7 th\\u1ed1ng.\\n\\nT\\u00e1c gi\\u1ea3 \\u0111\\u1ec1 xu\\u1ea5t h\\u1ec7 th\\u1ed1ng v\\u1edbi ph\\u00e2n quy\\u1ec1n gi\\u00e1o v\\u1ee5, sinh vi\\u00ean v\\u00e0 gi\\u1ea3ng vi\\u00ean, c\\u00f9ng c\\u00e1c t\\u00ednh n\\u0103ng qu\\u1ea3n l\\u00fd t\\u00e0i kho\\u1ea3n, h\\u1ed9i \\u0111\\u1ed3ng, kh\\u00f3a lu\\u1eadn v\\u00e0 l\\u01b0u \\u0111i\\u1ec3m. Qua ch\\u01b0\\u01a1ng t\\u1ed5ng k\\u1ebft, t\\u00e1c gi\\u1ea3 b\\u00e1o c\\u00e1o \\u0111\\u00e3 c\\u01a1 b\\u1ea3n ho\\u00e0n th\\u00e0nh h\\u1ec7 th\\u1ed1ng v\\u1edbi c\\u00e1c ch\\u1ee9c n\\u0103ng c\\u1ea7n thi\\u1ebft v\\u00e0 n\\u00eau ra h\\u01b0\\u1edbng ph\\u00e1t tri\\u1ec3n.\",\"completed_work\":[{\"content\":\"T\\u00e1c gi\\u1ea3 \\u0111\\u00e3 v\\u1eadn d\\u1ee5ng ki\\u1ebfn th\\u1ee9c, t\\u1ef1 t\\u00ecm hi\\u1ec3u Spring Boot v\\u00e0 x\\u00e2y d\\u1ef1ng giao di\\u1ec7n website b\\u1eb1ng ReactJS, c\\u01a1 b\\u1ea3n ho\\u00e0n th\\u00e0nh \\u0111\\u1ec1 t\\u00e0i x\\u00e2y d\\u1ef1ng website qu\\u1ea3n l\\u00fd kh\\u00f3a lu\\u1eadn t\\u1ed1t nghi\\u1ec7p v\\u1edbi c\\u00e1c ch\\u1ee9c n\\u0103ng c\\u1ea7n thi\\u1ebft.\",\"kind\":\"reported_work\",\"source_ids\":[\"AI-009:0001\"],\"source_pages\":[71],\"evidence\":\"Nh\\u1eddv\\u00e0o qu\\u00e1 tr\\u00ecnh ki\\u00ean tr\\u00ec v\\u00e0 v\\u1eadn d\\u1ee5ng ki\\u1ebfn th\\u1ee9c \\u0111\\u00e3 h\\u1ecdc, em \\u0111\\u00e3 c\\u01a1 b\\u1ea3n ho\\u00e0n\\nth\\u00e0nh \\u0111\\u1ec1t\\u00e0i \\u201cX\\u00e2y d\\u1ef1ng website qu\\u1ea3n l\\u00fd kh\\u00f3a lu\\u1eadn t\\u1ed1t nghi\\u1ec7p\\u201d c\\u00f3 c\\u00e1c ch\\u1ee9c n\\u0103ng c\\u1ea7n\\nthi\\u1ebft: Qu\\u1ea3n l\\u00fd t\\u00e0i kho\\u1ea3n ng\\u01b0\\u1eddi d\\u00f9ng, Qu\\u1ea3n l\\u00fd \\u0111i\\u1ec3m, kh\\u00f3a lu\\u1eadn, h\\u1ed9i \\u0111\\u1ed3ng, ch\\u1ee9c n\\u0103ng\\nth\\u1ed1ng k\\u00ea, ngo\\u00e0i ra trong qu\\u00e1 tr\\u00ecnh t\\u00ecm ki\\u1ebfm em \\u0111\\u00e3 v\\u1eadn d\\u1ee5ng google sheet v\\u00e0 appScript\\n\\u0111\\u1ec3g\\u1eedi mail cho gi\\u00e1o vi\\u00ean ph\\u1ea3n bi\\u1ec7n v\\u00e0 th\\u00f4ng b\\u00e1o \\u0111i\\u1ec3m cho sinh vi\\u00ean.\",\"source_references\":[{\"source_id\":\"AI-009:0001\",\"page\":71,\"end_page\":71,\"quote\":\"Nh\\u1eddv\\u00e0o qu\\u00e1 tr\\u00ecnh ki\\u00ean tr\\u00ec v\\u00e0 v\\u1eadn d\\u1ee5ng ki\\u1ebfn th\\u1ee9c \\u0111\\u00e3 h\\u1ecdc, em \\u0111\\u00e3 c\\u01a1 b\\u1ea3n ho\\u00e0n\\nth\\u00e0nh \\u0111\\u1ec1t\\u00e0i \\u201cX\\u00e2y d\\u1ef1ng website qu\\u1ea3n l\\u00fd kh\\u00f3a lu\\u1eadn t\\u1ed1t nghi\\u1ec7p\\u201d c\\u00f3 c\\u00e1c ch\\u1ee9c n\\u0103ng c\\u1ea7n\\nthi\\u1ebft: Qu\\u1ea3n l\\u00fd t\\u00e0i kho\\u1ea3n ng\\u01b0\\u1eddi d\\u00f9ng, Qu\\u1ea3n l\\u00fd \\u0111i\\u1ec3m, kh\\u00f3a lu\\u1eadn, h\\u1ed9i \\u0111\\u1ed3ng, ch\\u1ee9c n\\u0103ng\\nth\\u1ed1ng k\\u00ea, ngo\\u00e0i ra trong qu\\u00e1 tr\\u00ecnh t\\u00ecm ki\\u1ebfm em \\u0111\\u00e3 v\\u1eadn d\\u1ee5ng google sheet v\\u00e0 appScript\\n\\u0111\\u1ec3g\\u1eedi mail cho gi\\u00e1o vi\\u00ean ph\\u1ea3n bi\\u1ec7n v\\u00e0 th\\u00f4ng b\\u00e1o \\u0111i\\u1ec3m cho sinh vi\\u00ean.\",\"start\":41400,\"end\":41789,\"quote_verified\":true,\"semantic_support\":\"NOT_VERIFIED\"}],\"verified\":true,\"relevance_verified\":false,\"semantic_support\":\"NOT_VERIFIED\"}],\"citations\":[{\"page\":7,\"snippet\":\"Kh\\u00f3a lu\\u1eadn t\\u1ed1t nghi\\u1ec7p c\\u1ee7a em mang t\\u00ean \\u201cX\\u00e2y d\\u1ef1ng website qu\\u1ea3n l\\u00fd kh\\u00f3a lu\\u1eadn\\nt\\u1ed1t nghi\\u1ec7p\\u201d.\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":7,\"snippet\":\"Quy tr\\u00ecnh th\\u1ef1c hi\\u1ec7n c\\u1ee7a website n\\u00e0y bao g\\u1ed3m c\\u00e1c c\\u00f4ng \\u0111o\\u1ea1n sau: t\\u1ea1o t\\u00e0i\\nkho\\u1ea3n ng\\u01b0\\u1eddi d\\u00f9ng, kh\\u00f3a lu\\u1eadn, h\\u1ed9i \\u0111\\u1ed3ng, l\\u01b0u \\u0111i\\u1ec3m, in \\u0111i\\u1ec3m v\\u00e0 nh\\u1eadn \\u0111i\\u1ec3m.\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":7,\"snippet\":\"Website v\\u1edbi\\ngiao di\\u1ec7n \\u0111\\u01a1n gi\\u1ea3n, nhi\\u1ec1u t\\u00ednh n\\u0103ng ti\\u1ec7n \\u00edch gi\\u00fap cho ng\\u01b0\\u1eddi d\\u00f9ng d\\u1ec5thao t\\u00e1c v\\u00e0 qu\\u1ea3n\\nl\\u00fd, c\\u00f9ng v\\u1edbi \\u0111\\u00f3 l\\u00e0 s\\u1ef1b\\u1ea3o m\\u1eadt m\\u00e0 website mang l\\u1ea1i.\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":7,\"snippet\":\"Gi\\u00e1o v\\u1ee5khoa c\\u00f3 quy\\u1ec1n t\\u1ea1o ra kho\\u00e1\\nlu\\u1eadn, h\\u1ed9i \\u0111\\u1ed3ng v\\u00e0 qu\\u1ea3n l\\u00fd s\\u1ed1l\\u01b0\\u01a1ng th\\u00e0nh vi\\u00ean trong t\\u1eebng h\\u1ed9i \\u0111\\u1ed3ng, kho\\u00e1 lu\\u1eadn.\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":7,\"snippet\":\"Gi\\u00fap\\nsinh vi\\u00ean qu\\u1ea3n l\\u00fd b\\u00e0i l\\u00e0m c\\u1ee7a m\\u00ecnh, gi\\u1ea3ng vi\\u00ean qu\\u1ea3n l\\u00fd c\\u00e1c h\\u1ed9i \\u0111\\u1ed3ng v\\u00e0 kh\\u00f3a lu\\u1eadn m\\u00e0\\nm\\u00ecnh tham gia, l\\u01b0u \\u0111i\\u1ec3m cho t\\u1eebng kho\\u00e1 lu\\u1eadn khi \\u0111\\u00e3 ho\\u00e0n th\\u00e0nh vi\\u1ec7c ch\\u1ea5m \\u0111i\\u1ec3m.\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":8,\"snippet\":\"My graduation thesis is entitled \\\"Building a website to manage graduation thesis\\\".\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":8,\"snippet\":\"The website has a simple interface, many convenient features that make it easy for students and lecturers to manipulate and manage, along with the security that the website brings.\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":15,\"snippet\":\"\\u0110\\u1ec3\\u0111\\u1ea3m b\\u1ea3o t\\u00ednh \\u0111\\u00fang \\u0111\\u1eafn v\\u00e0 linh ho\\u1ea1t trong qu\\u00e1 tr\\u00ecnh qu\\u1ea3n l\\u00fd v\\u00e0 ch\\u1ea5m \\u0111i\\u1ec3m kh\\u00f3a lu\\u1eadn em \\u0111\\u00e3 l\\u1ef1a ch\\u1ecdn \\u0111\\u1ec1t\\u00e0i \\u201cX\\u00e2y d\\u1ef1ng website qu\\u1ea3n l\\u00fd kh\\u00f3a lu\\u1eadn t\\u1ed1t nghi\\u1ec7p\\u201d.\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":15,\"snippet\":\"- T\\u1ea1o t\\u00e0i kho\\u1ea3n sinh vi\\u00ean t\\u1eebfile excel n\\u1ebfu th\\u1ecfa m\\u00e3n \\u0111i\\u1ec1u ki\\u1ec7n l\\u00e0m kh\\u00f3a lu\\u1eadn t\\u1ed1t nghi\\u1ec7p: Sinh vi\\u00ean c\\u00f3 nguy\\u1ec7n v\\u1ecdng l\\u00e0m kh\\u00f3a lu\\u1eadn t\\u1ed1t nghi\\u1ec7p, \\u0111i\\u1ec3m \\u0111\\u1ed3\\u00e1n ng\\u00e0nh tr\\u00ean t\\u00e1m v\\u00e0 \\u0111\\u01b0\\u1ee3c s\\u1ef1\\u0111\\u1ed3ng \\u00fd t\\u1eebgi\\u00e1o vi\\u00ean h\\u01b0\\u1edbng d\\u1eabn, \\u0111i\\u1ec3m trung b\\u00ecnh tr\\u00ean hai ph\\u1ea9y n\\u0103m \\u0111i\\u1ec3m, kh\\u00f4ng n\\u1ee3qu\\u00e1 m\\u1ed9t m\\u00f4n.\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":16,\"snippet\":\"- Th\\u00e0nh l\\u1eadp h\\u1ed9i \\u0111\\u1ed3ng b\\u1ea3o v\\u1ec7kh\\u00f3a lu\\u1eadn, t\\u1ed1i thi\\u1ec3u ba, t\\u1ed1i \\u0111a n\\u0103m gi\\u1ea3ng vi\\u00ean bao g\\u1ed3m m\\u1ed9t ch\\u1ee7t\\u1ecbch, m\\u1ed9t th\\u01b0 k\\u00fd, m\\u1ed9t ph\\u1ea3n bi\\u1ec7n (khi gi\\u00e1o v\\u1ee5ph\\u00e2n c\\u00f4ng gi\\u00e1o vi\\u00ean ph\\u1ea3n bi\\u1ec7n h\\u1ec7th\\u1ed1ng s\\u1ebdg\\u1eedi mail th\\u00f4ng b\\u00e1o cho gi\\u00e1o vi\\u00ean v\\u1eeba \\u0111\\u01b0\\u1ee3c giao nhi\\u1ec7m v\\u1ee5l\\u00e0m gi\\u00e1o vi\\u00ean ph\\u1ea3n bi\\u1ec7n cho h\\u1ed9i \\u0111\\u1ed3ng), m\\u1ed9t gi\\u00e1o vi\\u00ean \\u0111\\u01b0\\u1ee3c ph\\u00e9p tham gia t\\u1ed1i \\u0111a hai h\\u1ed9i \\u0111\\u1ed3ng.\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":16,\"snippet\":\"- \\u0110\\u0103ng nh\\u1eadp v\\u00e0o h\\u1ec7th\\u1ed1ng v\\u00e0 ghi \\u0111i\\u1ec3m t\\u1eebng ti\\u00eau ch\\u00ed c\\u1ee7a kh\\u00f3a lu\\u1eadn.\\n- Th\\u1ea3o lu\\u1eadn v\\u1edbi sinh vi\\u00ean qua email \\u0111\\u1ec3th\\u1ed1ng nh\\u1ea5t \\u0111\\u1ec1t\\u00e0i sau \\u0111\\u00f3 th\\u00eam \\u0111\\u1ec1t\\u00e0i cho\\nsinh vi\\u00ean.\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":17,\"snippet\":\"- \\u0110\\u0103ng nh\\u1eadp v\\u00e0o h\\u1ec7th\\u1ed1ng \\u0111\\u1ec3n\\u1ed9p b\\u00e0i l\\u00e0m n\\u1ebfu qu\\u00e1 th\\u1eddi gian th\\u00ec s\\u1ebdkh\\u00f4ng \\u0111\\u01b0\\u1ee3c\\nn\\u1ed9p b\\u00e0i.\\n- Nh\\u1eadn email th\\u00f4ng b\\u00e1o \\u0111i\\u1ec3m trung b\\u00ecnh t\\u1eebh\\u1ed9i \\u0111\\u1ed3ng.\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":17,\"snippet\":\"- Ch\\u01b0\\u01a1ng 1. T\\u1ed5ng quan v\\u1ec1h\\u1ec7th\\u1ed1ng: m\\u00f4 t\\u1ea3v\\u1ec1l\\u00fd do ch\\u1ecdn \\u0111\\u1ec1t\\u00e0i v\\u00e0 ch\\u1ee9c n\\u0103ng c\\u01a1\\nb\\u1ea3n c\\u1ee7a h\\u1ec7th\\u1ed1ng.\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":18,\"snippet\":\"CH\\u01af\\u01a0NG 2. C\\u01a0 S\\u1edeL\\u00dd THUY\\u1ebeT\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":18,\"snippet\":\"2.1. BackEnd\",\"verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"page\":18,\"snippet\":\"Java l\\u00e0 ng\\u00f