9ng d\\u1ee5ng v\\u1edbi c\\u01a1 s\\u1edf d\\u1eef li\\u1ec7u MySQL \\ntrong qu\\u00e1 tr\\u00ecnh ph\\u00e1t tri\\u1ec3n.\",\"source_references\":[{\"source_id\":\"AI-009:0004\",\"page\":56,\"end_page\":56,\"quote\":\"Laragon \\u0111\\u01b0\\u1ee3c s\\u1eed d\\u1ee5ng \\u0111\\u1ec3 ch\\u1ea1y h\\u1ec7 th\\u1ed1ng Laravel trong m\\u00f4i tr\\u01b0\\u1eddng localhost, \\nki\\u1ec3m tra c\\u00e1c ch\\u1ee9c n\\u0103ng c\\u1ee7a h\\u1ec7 th\\u1ed1ng v\\u00e0 k\\u1ebft n\\u1ed1i \\u1ee9ng d\\u1ee5ng v\\u1edbi c\\u01a1 s\\u1edf d\\u1eef li\\u1ec7u MySQL \\ntrong qu\\u00e1 tr\\u00ecnh ph\\u00e1t tri\\u1ec3n.\",\"start\":84568,\"end\":84751,\"quote_verified\":true,\"semantic_support\":\"NOT_VERIFIED\"}],\"verified\":true,\"relevance_verified\":false,\"semantic_support\":\"NOT_VERIFIED\"},{\"content\":\"MySQL l\\u00e0 h\\u1ec7 qu\\u1ea3n tr\\u1ecb c\\u01a1 s\\u1edf d\\u1eef li\\u1ec7u quan h\\u1ec7 t\\u1ed5 ch\\u1ee9c d\\u1eef li\\u1ec7u th\\u00e0nh c\\u00e1c b\\u1ea3ng c\\u00f3 m\\u1ed1i quan h\\u1ec7 \\u0111\\u1ec3 l\\u01b0u tr\\u1eef th\\u00f4ng tin sinh vi\\u00ean, gi\\u1ea3ng vi\\u00ean, kh\\u00f3a lu\\u1eadn, b\\u00e1o c\\u00e1o ti\\u1ebfn \\u0111\\u1ed9 v\\u00e0 k\\u1ebft qu\\u1ea3 t\\u00f3m t\\u1eaft.\",\"kind\":\"other\",\"source_ids\":[\"AI-009:0005\"],\"source_pages\":[56],\"evidence\":\"MySQL l\\u00e0 h\\u1ec7 qu\\u1ea3n tr\\u1ecb c\\u01a1 s\\u1edf d\\u1eef li\\u1ec7u quan h\\u1ec7 \\u0111\\u01b0\\u1ee3c s\\u1eed d\\u1ee5ng \\u0111\\u1ec3 l\\u01b0u tr\\u1eef v\\u00e0 qu\\u1ea3n \\nl\\u00fd d\\u1eef li\\u1ec7u c\\u1ee7a h\\u1ec7 th\\u1ed1ng. D\\u1eef li\\u1ec7u \\u0111\\u01b0\\u1ee3c t\\u1ed5 ch\\u1ee9c th\\u00e0nh c\\u00e1c b\\u1ea3ng c\\u00f3 m\\u1ed1i quan h\\u1ec7 v\\u1edbi \\nnhau, ph\\u1ee5c v\\u1ee5 vi\\u1ec7c qu\\u1ea3n l\\u00fd th\\u00f4ng tin sinh vi\\u00ean, gi\\u1ea3ng vi\\u00ean, kh\\u00f3a lu\\u1eadn, b\\u00e1o c\\u00e1o ti\\u1ebfn \\n\\u0111\\u1ed9 v\\u00e0 k\\u1ebft qu\\u1ea3 t\\u00f3m t\\u1eaft.\",\"source_references\":[{\"source_id\":\"AI-009:0005\",\"page\":56,\"end_page\":56,\"quote\":\"MySQL l\\u00e0 h\\u1ec7 qu\\u1ea3n tr\\u1ecb c\\u01a1 s\\u1edf d\\u1eef li\\u1ec7u quan h\\u1ec7 \\u0111\\u01b0\\u1ee3c s\\u1eed d\\u1ee5ng \\u0111\\u1ec3 l\\u01b0u tr\\u1eef v\\u00e0 qu\\u1ea3n \\nl\\u00fd d\\u1eef li\\u1ec7u c\\u1ee7a h\\u1ec7 th\\u1ed1ng. D\\u1eef li\\u1ec7u \\u0111\\u01b0\\u1ee3c t\\u1ed5 ch\\u1ee9c th\\u00e0nh c\\u00e1c b\\u1ea3ng c\\u00f3 m\\u1ed1i quan h\\u1ec7 v\\u1edbi \\nnhau, ph\\u1ee5c v\\u1ee5 vi\\u1ec7c qu\\u1ea3n l\\u00fd th\\u00f4ng tin sinh vi\\u00ean, gi\\u1ea3ng vi\\u00ean, kh\\u00f3a lu\\u1eadn, b\\u00e1o c\\u00e1o ti\\u1ebfn \\n\\u0111\\u1ed9 v\\u00e0 k\\u1ebft qu\\u1ea3 t\\u00f3m t\\u1eaft.\",\"start\":84782,\"end\":85046,\"quote_verified\":true,\"semantic_support\":\"NOT_VERIFIED\"}],\"verified\":true,\"relevance_verified\":false,\"semantic_support\":\"NOT_VERIFIED\"},{\"content\":\"phpMyAdmin cung c\\u1ea5p giao di\\u1ec7n Web tr\\u1ef1c quan \\u0111\\u1ec3 qu\\u1ea3n l\\u00fd c\\u01a1 s\\u1edf d\\u1eef li\\u1ec7u MySQL.\",\"kind\":\"other\",\"source_ids\":[\"AI-009:0006\"],\"source_pages\":[56],\"evidence\":\"phpMyAdmin cung c\\u1ea5p giao di\\u1ec7n Web tr\\u1ef1c quan h\\u1ed7 tr\\u1ee3 qu\\u1ea3n l\\u00fd c\\u01a1 s\\u1edf d\\u1eef li\\u1ec7u \\nMySQL, cho ph\\u00e9p th\\u1ef1c hi\\u1ec7n c\\u00e1c thao t\\u00e1c nh\\u01b0 t\\u1ea1o c\\u01a1 s\\u1edf d\\u1eef li\\u1ec7u, x\\u00e2y d\\u1ef1ng b\\u1ea3ng, \\nxem d\\u1eef li\\u1ec7u, th\\u1ef1c hi\\u1ec7n c\\u00e2u l\\u1ec7nh SQL v\\u00e0 qu\\u1ea3n l\\u00fd c\\u1ea5u tr\\u00fac d\\u1eef li\\u1ec7u.\",\"source_references\":[{\"source_id\":\"AI-009:0006\",\"page\":56,\"end_page\":56,\"quote\":\"phpMyAdmin cung c\\u1ea5p giao di\\u1ec7n Web tr\\u1ef1c quan h\\u1ed7 tr\\u1ee3 qu\\u1ea3n l\\u00fd c\\u01a1 s\\u1edf d\\u1eef li\\u1ec7u \\nMySQL, cho ph\\u00e9p th\\u1ef1c hi\\u1ec7n c\\u00e1c thao t\\u00e1c nh\\u01b0 t\\u1ea1o c\\u01a1 s\\u1edf d\\u1eef li\\u1ec7u, x\\u00e2y d\\u1ef1ng b\\u1ea3ng, \\nxem d\\u1eef li\\u1ec7u, th\\u1ef1c