\\u1eaft b\\u00e1o c\\u00e1o kh\\u00f3a lu\\u1eadn b\\u1eb1ng m\\u00f4 h\\u00ecnh ng\\u00f4n ng\\u1eef l\\u1edbn.\",\"start\":161393,\"end\":161518,\"quote_verified\":true,\"semantic_support\":\"NOT_VERIFIED\"}],\"verified\":true,\"relevance_verified\":false,\"semantic_support\":\"NOT_VERIFIED\"},{\"content\":\"N\\u1ed9i dung \\u0111\\u01b0\\u1ee3c ph\\u00e2n \\u0111o\\u1ea1n theo c\\u1ea5u tr\\u00fac ch\\u01b0\\u01a1ng m\\u1ee5c, t\\u00f3m t\\u1eaft b\\u1eb1ng LLM v\\u00e0 t\\u1ed5ng h\\u1ee3p theo ph\\u01b0\\u01a1ng ph\\u00e1p Map-Reduce.\",\"kind\":\"other\",\"source_ids\":[\"AI-022:0002\"],\"source_pages\":[138],\"evidence\":\"Thay v\\u00e0o \\u0111\\u00f3, n\\u1ed9i dung \\u0111\\u01b0\\u1ee3c ph\\u00e2n \\u0111o\\u1ea1n theo c\\u1ea5u tr\\u00fac ch\\u01b0\\u01a1ng, m\\u1ee5c v\\u00e0 chia nh\\u1ecf khi c\\u1ea7n thi\\u1ebft. C\\u00e1c \\u0111o\\u1ea1n v\\u0103n b\\u1ea3n \\u0111\\u01b0\\u1ee3c t\\u00f3m t\\u1eaft b\\u1eb1ng LLM, sau \\u0111\\u00f3 t\\u1ed5ng h\\u1ee3p theo ph\\u01b0\\u01a1ng ph\\u00e1p Map\\u2013Reduce.\",\"source_references\":[{\"source_id\":\"AI-022:0002\",\"page\":138,\"end_page\":138,\"quote\":\"Thay v\\u00e0o \\u0111\\u00f3, n\\u1ed9i dung \\u0111\\u01b0\\u1ee3c ph\\u00e2n \\u0111o\\u1ea1n theo c\\u1ea5u tr\\u00fac ch\\u01b0\\u01a1ng, m\\u1ee5c v\\u00e0 chia nh\\u1ecf khi c\\u1ea7n thi\\u1ebft. C\\u00e1c \\u0111o\\u1ea1n v\\u0103n b\\u1ea3n \\u0111\\u01b0\\u1ee3c t\\u00f3m t\\u1eaft b\\u1eb1ng LLM, sau \\u0111\\u00f3 t\\u1ed5ng h\\u1ee3p theo ph\\u01b0\\u01a1ng ph\\u00e1p Map\\u2013Reduce.\",\"start\":161764,\"end\":161940,\"quote_verified\":true,\"semantic_support\":\"NOT_VERIFIED\"}],\"verified\":true,\"relevance_verified\":false,\"semantic_support\":\"NOT_VERIFIED\"},{\"content\":\"N\\u1ed9i dung t\\u1eebng trang \\u0111\\u01b0\\u1ee3c tr\\u00edch xu\\u1ea5t th\\u00e0nh v\\u0103n b\\u1ea3n, t\\u00ecm ti\\u00eau \\u0111\\u1ec1 ch\\u01b0\\u01a1ng m\\u1ee5c v\\u00e0 chia th\\u00e0nh c\\u00e1c chunk nh\\u1ecf.\",\"kind\":\"other\",\"source_ids\":[\"AI-022:0003\"],\"source_pages\":[139],\"evidence\":\"N\\u1ed9i dung t\\u1eebng trang \\u0111\\u01b0\\u1ee3c tr\\u00edch xu\\u1ea5t th\\u00e0nh v\\u0103n b\\u1ea3n, sau \\u0111\\u00f3 h\\u1ec7 th\\u1ed1ng t\\u00ecm c\\u00e1c ti\\u00eau \\u0111\\u1ec1 ch\\u01b0\\u01a1ng, m\\u1ee5c \\u0111\\u1ec3 x\\u00e1c \\u0111\\u1ecbnh ranh gi\\u1edbi n\\u1ed9i dung. C\\u00e1c m\\u1ee5c d\\u00e0i ti\\u1ebfp t\\u1ee5c \\u0111\\u01b0\\u1ee3c chia th\\u00e0nh nh\\u1eefng chunk nh\\u1ecf c\\u00f3 \\u0111\\u1ed9 d\\u00e0i ph\\u00f9 h\\u1ee3p v\\u1edbi gi\\u1edbi h\\u1ea1n x\\u1eed l\\u00fd c\\u1ee7a m\\u00f4 h\\u00ecnh.\",\"source_references\":[{\"source_id\":\"AI-022:0003\",\"page\":139,\"end_page\":139,\"quote\":\"N\\u1ed9i dung t\\u1eebng trang \\u0111\\u01b0\\u1ee3c tr\\u00edch xu\\u1ea5t th\\u00e0nh v\\u0103n b\\u1ea3n, sau \\u0111\\u00f3 h\\u1ec7 th\\u1ed1ng t\\u00ecm c\\u00e1c ti\\u00eau \\u0111\\u1ec1 ch\\u01b0\\u01a1ng, m\\u1ee5c \\u0111\\u1ec3 x\\u00e1c \\u0111\\u1ecbnh ranh gi\\u1edbi n\\u1ed9i dung. C\\u00e1c m\\u1ee5c d\\u00e0i ti\\u1ebfp t\\u1ee5c \\u0111\\u01b0\\u1ee3c chia th\\u00e0nh nh\\u1eefng chunk nh\\u1ecf c\\u00f3 \\u0111\\u1ed9 d\\u00e0i ph\\u00f9 h\\u1ee3p v\\u1edbi gi\\u1edbi h\\u1ea1n x\\u1eed l\\u00fd c\\u1ee7a m\\u00f4 h\\u00ecnh.\",\"start\":162682,\"end\":162913,\"quote_verified\":true,\"semantic_support\":\"NOT_VERIFIED\"}],\"verified\":true,\"relevance_verified\":false,\"semantic_support\":\"NOT_VERIFIED\"},{\"content\":\"\\u1ede giai \\u0111o\\u1ea1n Map, LLM t\\u00f3m t\\u1eaft t\\u1eebng chunk v\\u00e0 \\u1edf giai \\u0111o\\u1ea1n Reduce, k\\u1ebft qu\\u1ea3 \\u0111\\u01b0\\u1ee3c t\\u1ed5ng h\\u1ee3p theo c\\u00e1c c\\u1ea5p.\",\"kind\":\"other\",\"source_ids\":[\"AI-022:0004\"],\"source_pages\":[139],\"evidence\":\"\\u1ede giai \\u0111o\\u1ea1n Map, LLM t\\u00f3m t\\u1eaft t\\u1eebng chunk v\\u00e0 tr\\u1ea3 v\\u1ec1 d\\u1eef li\\u1ec7u c\\u00f3 c\\u1ea5u tr\\u00fac. \\u1ede giai \\u0111o\\u1ea1n Reduce, k\\u1ebft qu\\u1ea3 \\u0111\\u01b0\\u1ee3c t\\u1ed5ng h\\u1ee3p theo c\\u00e1c c\\u1ea5p t\\u1eeb chunk \\u0111\\u1ebfn m\\u1ee5c, ch\\u01b0\\u01a1ng v\\u00e0 t\\u00e0i li\\u1ec7u.\",\"source_references\":[{\"source_id\":\"AI-022:0004\",\"page\":139,\"end_page\":139,\"quote\":\"\\u1ede giai \\u0111o\\u1ea1n Map, LLM t\\u00f3m t\\u1eaft t\\u1eebng chunk v\\u00e0 tr\\u1ea3 v\\u1ec1 d\\u1eef li\\u1ec7u c\\u00f3 c\\u1ea5u tr\\u00fac. \\u1ede giai \\u0111o\\u1ea1n Reduce, k\\u1ebft qu\\u1ea3 \\u0111\\u01b0\\u1ee3c t\\u1ed5ng h\\u1ee3p theo c\\u00e1c c\\u1ea5p t\\u1eeb chunk \\u0111\\u1ebfn m\\u1ee5c, ch\\u01b0\\u01a1ng v\\u00e0 t\\u00e0i li\\u1ec7u.\",\"start\":162915,\"end\":163080,\"quote_verified\":true,\"semantic_support\":\"NOT_VERIFIED\"}],\"verified\":true,\"relevance_verified\":false,\"semantic_support\":\"NOT_VERIFIED\"},{\"content\":\"H\\u1ec7 th\\u1ed1ng \\u01b0u ti\\u00ean chia t\\u00e0i li\\u1ec7u theo c\\u1ea5u tr\\u00fac ch\\u01b0\\u01a1ng m\\u1ee5c \\u0111\\u1ec3 gi\\u1eef n\\u1ed9i dung c\\u00f9ng m\\u1ee5c v\\u00e0 hi\\u1ec3n th\\u1ecb s\\u1ed1 th\\u1ee9 t\\u1ef1 \\u0111\\u00fang.\",\"kind\":\"other\",\"source_ids\":[\"AI-023:0001\"],\"source_pages\":[140],\"evidence\":\"H\\u1ec7 th\\u1ed1ng \\u01b0u ti\\u00ean chia t\\u00e0i li\\u1ec7u d\\u1ef1a theo c\\u1ea5u tr\\u00fac ch\\u01b0\\u01a1ng, m\\u1ee5c nh\\u01b0 1, 1.1, 2.3 thay v\\u00ec c\\u1eaft to\\u00e0n b\\u1ed9 v\\u0103n b\\u1ea3n th\\u00e0nh nh\\u1eefng \\u0111o\\u1ea1n c\\u00f3 k\\u00edch th\\u01b0\\u1edbc c\\u1ed1 \\u0111\\u1ecbnh ngay t\\u1eeb \\u0111\\u1ea7u.\",\"source_references\":[{\"source_id\":\"AI-023:0001\",\"page\":140,\"end_page\":140,\"quote\":\"H\\u1ec7 th\\u1ed1ng \\u01b0u ti\\u00ean chia t\\u00e0i li\\u1ec7u d\\u1ef1a theo c\\u1ea5u tr\\u00fac ch\\u01b0\\u01a1ng, m\\u1ee5c nh\\u01b0 1, 1.1, 2.3 thay v\\u00ec c\\u1eaft to\\u00e0n b\\u1ed9 v\\u0103n b\\u1ea3n th\\u00e0nh nh\\u1eefng \\u0111o\\u1ea1n c\\u00f3 k\\u00edch th\\u01b0\\u1edbc c\\u1ed1 \\u0111\\u1ecbnh ngay t\\u1eeb \\u0111\\u1ea7u.\",\"start\":163521,\"en