u1ef1c hi\\u1ec7n kh\\u1ea3o s\\u00e1t nghi\\u1ec7p v\\u1ee5, ph\\u00e2n t\\u00edch y\\u00eau c\\u1ea7u, thi\\u1ebft k\\u1ebf c\\u01a1 s\\u1edf d\\u1eef li\\u1ec7u v\\u00e0 x\\u00e2y d\\u1ef1ng ph\\u1ea7n m\\u1ec1m qu\\u1ea3n l\\u00fd c\\u00f4ng t\\u00e1c kh\\u00f3a lu\\u1eadn t\\u1ed1t nghi\\u1ec7p. K\\u1ebft qu\\u1ea3 b\\u00e1o c\\u00e1o cho th\\u1ea5y h\\u1ec7 th\\u1ed1ng \\u0111\\u00e3 \\u0111\\u00e1p \\u1ee9ng ph\\u1ea7n l\\u1edbn c\\u00e1c nh\\u00f3m y\\u00eau c\\u1ea7u ch\\u1ee9c n\\u0103ng ph\\u1ee5c v\\u1ee5 quy tr\\u00ecnh qu\\u1ea3n l\\u00fd. Tuy nhi\\u00ean, ph\\u1ea1m vi ki\\u1ec3m th\\u1eed c\\u1ee7a \\u0111\\u1ec1 t\\u00e0i v\\u1eabn c\\u00f2n gi\\u1edbi h\\u1ea1n v\\u00e0 ch\\u01b0a \\u0111\\u00e1nh gi\\u00e1 \\u0111\\u1ea7y \\u0111\\u1ee7 c\\u00e1c t\\u00ecnh hu\\u1ed1ng nghi\\u1ec7p v\\u1ee5, b\\u1ea3o m\\u1eadt c\\u0169ng nh\\u01b0 t\\u1ea3i ng\\u01b0\\u1eddi d\\u00f9ng \\u0111\\u1ed3ng th\\u1eddi. V\\u1ec1 h\\u01b0\\u1edbng ph\\u00e1t tri\\u1ec3n, t\\u00e1c gi\\u1ea3 \\u0111\\u1ec1 xu\\u1ea5t ti\\u1ebfp t\\u1ee5c r\\u00e0 so\\u00e1t nghi\\u1ec7p v\\u1ee5, ho\\u00e0n thi\\u1ec7n giao di\\u1ec7n v\\u00e0 t\\u0103ng t\\u00ednh nh\\u1ea5t qu\\u00e1n d\\u1eef li\\u1ec7u d\\u1ef1a tr\\u00ean ph\\u1ea3n h\\u1ed3i th\\u1ef1c t\\u1ebf.\",\"items\":[{\"content\":\"Ch\\u01b0\\u01a1ng k\\u1ebft lu\\u1eadn t\\u1ed5ng k\\u1ebft l\\u1ea1i qu\\u00e1 tr\\u00ecnh t\\u00e1c gi\\u1ea3 th\\u1ef1c hi\\u1ec7n kh\\u1ea3o s\\u00e1t nghi\\u1ec7p v\\u1ee5, ph\\u00e2n t\\u00edch y\\u00eau c\\u1ea7u, thi\\u1ebft k\\u1ebf c\\u01a1 s\\u1edf d\\u1eef li\\u1ec7u v\\u00e0 x\\u00e2y d\\u1ef1ng ph\\u1ea7n m\\u1ec1m qu\\u1ea3n l\\u00fd c\\u00f4ng t\\u00e1c kh\\u00f3a lu\\u1eadn t\\u1ed1t nghi\\u1ec7p. K\\u1ebft qu\\u1ea3 b\\u00e1o c\\u00e1o cho th\\u1ea5y h\\u1ec7 th\\u1ed1ng \\u0111\\u00e3 \\u0111\\u00e1p \\u1ee9ng ph\\u1ea7n l\\u1edbn c\\u00e1c nh\\u00f3m y\\u00eau c\\u1ea7u ch\\u1ee9c n\\u0103ng ph\\u1ee5c v\\u1ee5 quy tr\\u00ecnh qu\\u1ea3n l\\u00fd.\",\"kind\":\"other\",\"source_ids\":[\"AI-026:0001\",\"AI-026:0002\"],\"source_pages\":[154],\"evidence\":\"\\u0110\\u1ec1 t\\u00e0i \\u0111\\u00e3 th\\u1ef1c hi\\u1ec7n kh\\u1ea3o s\\u00e1t nghi\\u1ec7p v\\u1ee5, ph\\u00e2n t\\u00edch y\\u00eau c\\u1ea7u, thi\\u1ebft k\\u1ebf c\\u01a1 s\\u1edf d\\u1eef li\\u1ec7u v\\u00e0 x\\u00e2y d\\u1ef1ng ph\\u1ea7n m\\u1ec1m qu\\u1ea3n l\\u00fd c\\u00f4ng t\\u00e1c kh\\u00f3a lu\\u1eadn t\\u1ed1t nghi\\u1ec7p.\",\"source_references\":[{\"source_id\":\"AI-026:0001\",\"page\":154,\"end_page\":154,\"quote\":\"\\u0110\\u1ec1 t\\u00e0i \\u0111\\u00e3 th\\u1ef1c hi\\u1ec7n kh\\u1ea3o s\\u00e1t nghi\\u1ec7p v\\u1ee5, ph\\u00e2n t\\u00edch y\\u00eau c\\u1ea7u, thi\\u1ebft k\\u1ebf c\\u01a1 s\\u1edf d\\u1eef li\\u1ec7u v\\u00e0 x\\u00e2y d\\u1ef1ng ph\\u1ea7n m\\u1ec1m qu\\u1ea3n l\\u00fd c\\u00f4ng t\\u00e1c kh\\u00f3a lu\\u1eadn t\\u1ed1t nghi\\u1ec7p.\",\"start\":184334,\"end\":184476,\"quote_verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"source_id\":\"AI-026:0002\",\"page\":154,\"end_page\":154,\"quote\":\"So v\\u1edbi m\\u1ee5c ti\\u00eau ban \\u0111\\u1ea7u, ph\\u1ea7n m\\u1ec1m \\u0111\\u00e3 \\u0111\\u00e1p \\u1ee9ng ph\\u1ea7n l\\u1edbn c\\u00e1c nh\\u00f3m y\\u00eau c\\u1ea7u ch\\u1ee9c n\\u0103ng ph\\u1ee5c v\\u1ee5 quy tr\\u00ecnh qu\\u1ea3n l\\u00fd kh\\u00f3a lu\\u1eadn.\",\"start\":184957,\"end\":185075,\"quote_verified\":true,\"semantic_support\":\"NOT_VERIFIED\"}],\"verified\":true,\"relevance_verified\":false,\"semantic_support\":\"NOT_VERIFIED\"},{\"content\":\"Tuy nhi\\u00ean, ph\\u1ea1m vi ki\\u1ec3m th\\u1eed c\\u1ee7a \\u0111\\u1ec1 t\\u00e0i v\\u1eabn c\\u00f2n gi\\u1edbi h\\u1ea1n v\\u00e0 ch\\u01b0a \\u0111\\u00e1nh gi\\u00e1 \\u0111\\u1ea7y \\u0111\\u1ee7 c\\u00e1c t\\u00ecnh hu\\u1ed1ng nghi\\u1ec7p v\\u1ee5, b\\u1ea3o m\\u1eadt c\\u0169ng nh\\u01b0 t\\u1ea3i ng\\u01b0\\u1eddi d\\u00f9ng \\u0111\\u1ed3ng th\\u1eddi. V\\u1ec1 h\\u01b0\\u1edbng ph\\u00e1t tri\\u1ec3n, t\\u00e1c gi\\u1ea3 \\u0111\\u1ec1 xu\\u1ea5t ti\\u1ebfp t\\u1ee5c r\\u00e0 so\\u00e1t nghi\\u1ec7p v\\u1ee5, ho\\u00e0n thi\\u1ec7n giao di\\u1ec7n v\\u00e0 t\\u0103ng t\\u00ednh nh\\u1ea5t qu\\u00e1n d\\u1eef li\\u1ec7u d\\u1ef1a tr\\u00ean ph\\u1ea3n h\\u1ed3i th\\u1ef1c t\\u1ebf.\",\"kind\":\"other\",\"source_ids\":[\"AI-026:0003\",\"AI-026:0004\"],\"source_pages\":[154],\"evidence\":\"Ph\\u1ea1m vi ki\\u1ec3m th\\u1eed c\\u00f2n gi\\u1edbi h\\u1ea1n, ch\\u01b0a \\u0111\\u00e1nh gi\\u00e1 \\u0111\\u1ea7y \\u0111\\u1ee7 c\\u00e1c t\\u00ecnh hu\\u1ed1ng nghi\\u1ec7p v\\u1ee5, b\\u1ea3o m\\u1eadt v\\u00e0 nhi\\u1ec1u ng\\u01b0\\u1eddi d\\u00f9ng truy c\\u1eadp \\u0111\\u1ed3ng th\\u1eddi.\",\"source_references\":[{\"source_id\":\"AI-026:0003\",\"page\":154,\"end_page\":154,\"quote\":\"Ph\\u1ea1m vi ki\\u1ec3m th\\u1eed c\\u00f2n gi\\u1edbi h\\u1ea1n, ch\\u01b0a \\u0111\\u00e1nh gi\\u00e1 \\u0111\\u1ea7y \\u0111\\u1ee7 c\\u00e1c t\\u00ecnh hu\\u1ed1ng nghi\\u1ec7p v\\u1ee5, b\\u1ea3o m\\u1eadt v\\u00e0 nhi\\u1ec1u ng\\u01b0\\u1eddi d\\u00f9ng truy c\\u1eadp \\u0111\\u1ed3ng th\\u1eddi.\",\"start\":185654,\"end\":185780,\"quote_verified\":true,\"semantic_support\":\"NOT_VERIFIED\"},{\"source_id\":\"AI-026:0004\",\"page\":154,\"end_page\":154,\"quote\":\"Ti\\u1ebfp t\\u1ee5c r\\u00e0 so\\u00e1t quy tr\\u00ecnh nghi\\u1ec7p v\\u1ee5, ho\\u00e0n thi\\u1ec7n giao di\\u1ec7n v\\u00e0 t\\u0103ng t\\u00ednh nh\\u1ea5t qu\\u00e1n d\\u1eef li\\u1ec7u theo ph\\u1ea3n h\\u1ed3i c\\u1ee7a ng\\u01b0\\u1eddi s\\u1eed d\\u1ee5ng.\",\"start\":186190,\"end\":186313,\"quote_verified\":true,\"semantic_support\":\"NOT_VERIFIED\"}],\"verified\":true,\"relevance_verified\":false,\"semantic_support\":\"NOT_VERIFIED\"}],\"status\":\"completed\",\"sections\":[],\"related_assets\":[]}],\"caption_index\":{\"version\":\"caption-text-1\",\"status\":\"completed\",\"assets\":[{\"asset_id\":\"caption-bafcce3152dc212a56ae\",\"type\":\"FIGURE_CAPTION\",\"label\":\"H\\u00ecnh 1.1\",\"display_text\":\"H\\u00ecnh 1.1 Bi\\u1ec3u m\\u1eabu Th\\u00f4ng b\\u00e1o t