ee3 qu\\u1ea3n l\\u00fd to\\u00e0n b\\u1ed9 \\\\nc\\u00f4ng t\\u00e1c kh\\u00f3a lu\\u1eadn t\\u1ed1t nghi\\u1ec7p c\\u1ee7a khoa C\\u00f4ng ngh\\u1ec7 th\\u00f4ng tin. H\\u1ec7 th\\u1ed1ng \\u0111\\u01b0\\u1ee3c ph\\u00e1t \\\\ntri\\u1ec3n theo m\\u00f4 h\\u00ecnh qu\\u1ea3n l\\u00fd t\\u1eadp trung, cho ph\\u00e9p c\\u00e1c \\u0111\\u1ed1i t\\u01b0\\u1ee3ng s\\u1eed d\\u1ee5ng th\\u1ef1c hi\\u1ec7n c\\u00e1c \\\\nnghi\\u1ec7p v\\u1ee5 t\\u01b0\\u01a1ng \\u1ee9ng th\\u00f4ng qua t\\u00e0i kho\\u1ea3n \\u0111\\u01b0\\u1ee3c ph\\u00e2n quy\\u1ec1n. \\\\nC\\u00e1c \\u0111\\u1ed1i t\\u01b0\\u1ee3ng s\\u1eed d\\u1ee5ng ch\\u00ednh c\\u1ee7a h\\u1ec7 th\\u1ed1ng bao g\\u1ed3m: \\\\n\\u2022 \\\\nGi\\u00e1o v\\u1ee5 \\\\n\\u2022 \\\\nGi\\u1ea3ng vi\\u00ean \\\\n\\u2022 \\\\nSinh vi\\u00ean \\\\n\\u2022 \\\\nTr\\u01b0\\u1edfng b\\u00f4 m\\u00f4n \\\\n\\u2022 \\\\nTr\\u01b0\\u1edfng khoa \\\\nM\\u1ed7i \\u0111\\u1ed1i t\\u01b0\\u1ee3ng s\\u1ebd \\u0111\\u01b0\\u1ee3c c\\u1ea5p t\\u00e0i kho\\u1ea3n \\u0111\\u0103ng nh\\u1eadp v\\u00e0 ch\\u1ec9 \\u0111\\u01b0\\u1ee3c s\\u1eed d\\u1ee5ng nh\\u1eefng \\\\nch\\u1ee9c n\\u0103ng ph\\u00f9 h\\u1ee3p v\\u1edbi quy\\u1ec1n h\\u1ea1n c\\u1ee7a m\\u00ecnh. \\\\n\\u2022 \\\\nCh\\u1ee9c n\\u0103ng d\\u00e0nh cho Gi\\u00e1o v\\u1ee5 \\\\nGi\\u00e1o v\\u1ee5 l\\u00e0 ng\\u01b0\\u1eddi qu\\u1ea3n l\\u00fd to\\u00e0n b\\u1ed9 quy tr\\u00ecnh th\\u1ef1c hi\\u1ec7n kh\\u00f3a lu\\u1eadn t\\u1ed1t nghi\\u1ec7p c\\u1ee7a \\\\nkhoa. C\\u00e1c nghi\\u1ec7p v\\u1ee5 th\\u1ef1c hi\\u1ec7n bao g\\u1ed3m: \\\\n- \\\\nQu\\u1ea3n l\\u00fd th\\u00f4ng tin h\\u1ecdc k\\u1ef3, k\\u1ebf ho\\u1ea1ch v\\u00e0 c\\u00e1c m\\u1ed1c th\\u1eddi gian \\\\nth\\u1ef1c hi\\u1ec7n kh\\u00f3a lu\\u1eadn. \\\\n- \\\\nQu\\u1ea3n l\\u00fd danh m\\u1ee5c \\u0111\\u1ec1 t\\u00e0i kh\\u00f3a lu\\u1eadn do gi\\u1ea3ng vi\\u00ean \\u0111\\u1ec1 xu\\u1ea5t \\\\nho\\u1eb7c khoa ph\\u00ea duy\\u1ec7t. \\\\n- \\\\nQu\\u1ea3n l\\u00fd danh s\\u00e1ch sinh vi\\u00ean \\u0111\\u1ee7